  // pollCloudRevision tick that finds a newer remote revision — including
  // while the player is just navigating between pages) must never replace
  // or clear the live Play Mode setup/generated deployment. It's per-device
  // state, not something mergeAccountData's `keys` list ever covered, so
  // without this it would silently vanish the moment this device rebased
  // onto another device's snapshot.
  const keepPlaySession=state?.playSession||null;
  const next=mergeAccountData(remoteData||{rosters:[],active:null},state||{});
  next.playSession=keepPlaySession;
