const STORAGE_MODE=window.MordheimundaStorage.mode(); const ACCOUNT_SESSION_KEY='mordheimunda_account_session';
const accountSession=()=>{try{return JSON.parse(localStorage.getItem(ACCOUNT_SESSION_KEY)||'null')}catch{return null}};
// Never true on the deployed site (mordheimunda.vercel.app etc.) — only on a
// server actually running on your own machine. Lets the Admin tab render
// immediately on localhost even before an account/DB is set up; the
// server-side counterpart (localDevAdmin in server.js) is what makes any
// login on that same local server count as admin, when one exists.
const isLocalDevHost=()=>/^(localhost|127\.0\.0\.1|\[?::1\]?)$/.test(location.hostname);
const isAdminSession=()=>isLocalDevHost()||!!accountSession()?.isAdmin;
function refreshAdminNavVisibility(){const wrap=document.getElementById('navAdmin');const on=isAdminSession();if(wrap)wrap.classList.toggle('is-visible',on);const group=document.getElementById('navAdminGroup');if(group)group.classList.toggle('is-visible',on)}

// Nav groups (V155): tapping/clicking a group's head expands or collapses
// ONLY that group, on phone and on desktop, and never touches any other
// group's state — several groups can be open at once. Both breakpoints
// start CLOSED and share the same .nav-group-open class (styles.css wires
// it to the expanded state on both phone and desktop).
document.addEventListener('click',(e)=>{
  const head=e.target.closest('.nav-group-head');
  if(!head)return;
  e.preventDefault();
  const group=head.closest('.nav-group');
  if(!group)return;
  group.classList.toggle('nav-group-open');
});
const dataStore=window.MordheimundaStorage;
function translateSiteText(v){const text=String(v);if(siteLanguage==='fr'){const hit=I18N_FR[text]||FACTION_FR[text];if(hit)return hit;
    const fm=text.match(/^(\s*)([\s\S]*?)(\s*)$/);const fc=fm[2];if(!fc)return text;const fh=I18N_FR[fc]||FACTION_FR[fc]||i18nEnReverse()[fc];if(fh)return fm[1]+fh+fm[3];
    for(const [re,to] of I18N_FR_PATTERNS){if(re.test(fc))return fm[1]+fc.replace(re,to)+fm[3]}
    return text}if(I18N_EN[text])return I18N_EN[text];
  // V-I18NFULL: also match ignoring surrounding whitespace, then sentence
  // patterns with numbers, then French data names (equipment categories,
  // stat names…) inside longer texts. "Main Gauche" is a weapon name: kept.
  const m=text.match(/^(\s*)([\s\S]*?)(\s*)$/);const core=m[2];if(!core)return text;
  if(I18N_EN[core])return m[1]+I18N_EN[core]+m[3];
  for(const [re,to] of I18N_EN_PATTERNS){if(re.test(core))return m[1]+core.replace(re,to)+m[3]}
  const out=core.replace(I18N_EN_FRAGMENT_RE,f=>I18N_EN_FRAGMENTS[f]||f);
  return out===core?text:m[1]+out+m[3];} 

// V-I18NPERF: this used to always walk the WHOLE document.body — on every
// single render() (i.e. on nearly every click/keystroke anywhere in the
// app, since render() replaces #content's entire innerHTML each time), it
// re-walked and re-translated every text node and every placeholder/title/
// aria-label attribute on the ENTIRE page, including the sidebar nav and
// anything else that hadn't changed at all since the last pass. On a big
// roster page (many fighter cards, each with a dozen+ titled stat cells and
// ref-link tooltips) that's thousands of DOM touches per interaction — the
// likely source of the reported mobile lag. The sidebar/static chrome only
// ever needs this ONCE (page load) or when the language is actually
// switched; every other render only needs to translate the subtree that
// renderOriginal() just rebuilt. `root` scopes the walk accordingly —
// renderCurrentRoute passes it the real content root on the hot path, and
// falls back to a full document.body pass on first load / language switch.
function applySiteLanguage(root){
 root=root||document.body;
 document.documentElement.lang=siteLanguage;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 nodes.forEach(n=>{if(n.parentElement?.closest('#languageSelect'))return;if(n.__i18nOriginal===undefined)n.__i18nOriginal=n.nodeValue;n.nodeValue=translateSiteText(n.__i18nOriginal);});
 root.querySelectorAll('input[placeholder],textarea[placeholder],[title],[aria-label]').forEach(el=>{
   if(el.dataset.i18nPlaceholder===undefined&&el.placeholder)el.dataset.i18nPlaceholder=el.placeholder;
   if(el.dataset.i18nTitle===undefined&&el.title)el.dataset.i18nTitle=el.title;
   if(el.dataset.i18nAria===undefined&&el.getAttribute('aria-label'))el.dataset.i18nAria=el.getAttribute('aria-label');
   if(siteLanguage==='en'){if(el.placeholder)el.placeholder=translateSiteText(el.dataset.i18nPlaceholder||el.placeholder);if(el.title)el.title=translateSiteText(el.dataset.i18nTitle||el.title);if(el.getAttribute('aria-label'))el.setAttribute('aria-label',translateSiteText(el.dataset.i18nAria||el.getAttribute('aria-label')));}
   else{if(el.dataset.i18nPlaceholder!==undefined)el.placeholder=el.dataset.i18nPlaceholder;if(el.dataset.i18nTitle!==undefined)el.title=el.dataset.i18nTitle;if(el.dataset.i18nAria!==undefined)el.setAttribute('aria-label',el.dataset.i18nAria);}
 });
 const sel=document.getElementById('languageSelect');if(sel){sel.value=siteLanguage;const label=sel.closest('.language-control')?.querySelector('span');if(label)label.textContent=siteLanguage==='en'?'Language':'Langue';const opts=sel.options;if(opts[0])opts[0].textContent='English';if(opts[1])opts[1].textContent='Français';}
}
// Forces the next applySiteLanguage() call (inside renderCurrentRoute) to do
// a full document.body pass instead of the narrow #content-only one — set
// on first load and whenever the language is switched, since those are the
// only two moments the sidebar/static chrome actually needs re-translating.
let i18nNeedsFullPass=true;
function setSiteLanguage(v){siteLanguage=v==='fr'?'fr':'en';localStorage.setItem(SITE_LANGUAGE_KEY,siteLanguage);i18nNeedsFullPass=true;renderCurrentRoute();}
function render(view='dashboard',opts={}){ensureFrRules();
  const next=routeForView(view);
  if(opts.history!==false&&next!==appPath(location.pathname)){history.pushState({mordheimunda:true,view},'',next)}
  // A handful of search/filter fields call render() straight from their
  // oninput handler to refresh the list they filter (rather than patching
  // just their own results container). render() replaces #content's whole
  // innerHTML, which destroys and recreates that very input — the browser
  // then has nothing focused, so it drops the caret and the page's scroll
  // position resets to the top on literally every keystroke. When the
  // active element is a text field inside #content, remember it (and the
  // scroll position) and restore both once the new markup is in, so typing
  // in any such search box behaves like typing anywhere else.
  const contentEl=$('#content');
  const active=document.activeElement;
  let restore=null;
  if(active&&contentEl&&contentEl.contains(active)&&(active.tagName==='INPUT'||active.tagName==='TEXTAREA')){
    // V-NUMBERINPUTRESTORE: reading selectionStart/selectionEnd throws on
    // an <input type="number"> (and date/email/etc.) in Chrome/WebKit —
    // "The input element's type does not support selection range". That
    // exception, unguarded, used to abort this whole function BEFORE the
    // renderCurrentRoute() call below ever ran — so on those browsers,
    // typing in any bare number field anywhere on the site (a map builder
    // distance, a player-count field, …) never actually re-rendered on
    // that keystroke, and the next render that DID land (the next click,
    // blur, etc.) had no scroll/focus snapshot to restore at all, landing
    // back at the top like a page navigation. Guarding the read (rather
    // than just the later setSelectionRange call, which was already safe)
    // is what actually fixes it — everything downstream was already fine.
    let selStart=null,selEnd=null;
    try{selStart=active.selectionStart;selEnd=active.selectionEnd;}catch(e){}
    restore={id:active.id||'',cls:active.className||'',selStart,selEnd,scrollY:window.scrollY,mainScroll:$('.main')?$('.main').scrollTop:0};
  }
  renderCurrentRoute();
  if(restore){
    let el=null;
    if(restore.id)el=document.getElementById(restore.id);
    if(!el&&restore.cls){
      const sel='#content .'+restore.cls.trim().split(/\s+/).filter(Boolean).join('.');
      try{el=sel!=='#content .'?document.querySelector(sel):null}catch(e){}
    }
    if(el&&(el.tagName==='INPUT'||el.tagName==='TEXTAREA')){
      el.focus();
      if(typeof restore.selStart==='number'&&el.setSelectionRange){try{el.setSelectionRange(restore.selStart,restore.selEnd)}catch(e){}}
    }
    window.scrollTo(0,restore.scrollY);
    const main=$('.main');if(main)main.scrollTop=restore.mainScroll||0;
  }
}
function dashKpi(label,value,accent){return `<div class="dash-kpi-card"><span class="dash-kpi-label">${esc(label)}</span><strong class="dash-kpi-value"${accent?` style="color:${accent}"`:''}>${value}</strong></div>`}
function dashWarbandCard(r,reorder){const en=siteLanguage==='en';const f=faction(r)||{displayName:r?.factionName||r?.factionId||(en?'Unknown faction':'Faction inconnue'),budget:1000};const bar=f.group==='Undead'||/vampir|mort|zombi|skelet/i.test(f.displayName||'')?'#a5453a':'#9dfa3c';const labelColor=bar==='#a5453a'?'#c97a7a':'#7ddd2e';const bannerVisual=r.icon?`<img class="dash-wcard-cover"${imageFocusStyle(r.iconFocus)} src="${esc(r.icon)}" alt="${en?'Icon for':'Icône de'} ${esc(r.name)}">`:`<span class="gang-icon">${imageMarkup(r.icon,'gang',`${en?'Icon for':'Icône de'} ${esc(r.name)}`,r.iconFocus)}</span>`;
  // V147 — landscape poster card ported from the Main.dc.html mockup: a wide
  // image band (~72%) with just the rank tag, accent bar and duplicate icon,
  // and a slim bottom strip (~28%) holding only faction + name on the left
  // and the warband's Cote (total value) in a small badge on the right —
  // fighters/gold no longer shown on the dashboard card at all.
  // V-REORDERWARBANDS: on the full "Mes bandes" list (never the 3-item
  // dashboard preview, which doesn't get a `reorder` opts object), two small
  // move buttons let the order in state.rosters itself be changed — that
  // array's order IS the display order everywhere a roster list is shown,
  // so reordering here is enough; nothing else needs to read a separate
  // "position" field.
  const reorderBtns=reorder?`<div class="dash-wcard-reorder"><button type="button" class="dash-wcard-move" title="${en?'Move up':'Monter'}" aria-label="${en?'Move up':'Monter'}" ${reorder.index<=0?'disabled':''} onclick="event.preventDefault();event.stopPropagation();moveRosterOrder('${r.id}',-1)">▲</button><button type="button" class="dash-wcard-move" title="${en?'Move down':'Descendre'}" aria-label="${en?'Move down':'Descendre'}" ${reorder.index>=reorder.total-1?'disabled':''} onclick="event.preventDefault();event.stopPropagation();moveRosterOrder('${r.id}',1)">▼</button></div>`:'';
  return `<a href="${warbandPath(r.id)}" data-app-route="1"${reorder?` data-roster-id="${esc(r.id)}"`:''} class="dash-wcard"><div class="dash-wcard-banner">${bannerVisual}<span class="dash-wcard-bar" style="background:${bar}"></span>${reorderBtns}<button type="button" class="dash-wcard-dup" title="${en?'Duplicate':'Dupliquer'}" aria-label="${en?'Duplicate':'Dupliquer'} ${esc(r.name)}" onclick="event.preventDefault();event.stopPropagation();duplicateRoster('${r.id}')">⧉</button><span class="dash-wcard-rep">${en?'Rep.':'Rép.'} ${Number(r.reputation||0)}</span></div><div class="dash-wcard-body"><div class="dash-wcard-text"><span class="dash-wcard-faction" style="color:${labelColor}">${esc(f.displayName)}</span><strong class="dash-wcard-name">${esc(r.name)}</strong></div><div class="dash-wcard-cote"><span>${en?'Rating':'Cote'}</span><b>${total(r)}</b></div></div></a>`}
function moveRosterOrder(id,dir){
  const idx=state.rosters.findIndex(r=>r.id===id);if(idx<0)return;
  const to=idx+dir;if(to<0||to>=state.rosters.length)return;
  const [item]=state.rosters.splice(idx,1);state.rosters.splice(to,0,item);
  save(true);render('rosters');
}
// V-ROSTERDRAG: press-and-hold to drag-reorder a warband card on "Mes
// bandes", same mechanism as the fighter cards in a roster builder
// (beginFighterPointerDrag et al.) — the ▲▼ move buttons above stay in
// place as the text-based way to reorder, this is just an added gesture,
// not a replacement.
// V-LONGPRESS: on touch screens a card is picked up only after the finger
// stays still on it for TOUCH_REORDER_HOLD_MS (Munda Manager style); moving
// more than TOUCH_REORDER_SLOP_PX before that is a scroll and never drags.
const TOUCH_REORDER_HOLD_MS=1000;
const TOUCH_REORDER_SLOP_PX=10;
// While a card is being dragged, holding the finger/cursor near the top or
// bottom edge scrolls the page so far-away slots (tall fighter cards) can
// be reached; the drop target is re-evaluated as the page moves.
let reorderAutoScroll={raf:0,x:0,y:0,update:null};
function reorderAutoScrollTrack(e,update){
  reorderAutoScroll.x=e.clientX;reorderAutoScroll.y=e.clientY;reorderAutoScroll.update=update;
  if(reorderAutoScroll.raf)return;
  const step=()=>{
    const a=reorderAutoScroll;if(!a.update){a.raf=0;return;}
    const edge=Math.min(90,window.innerHeight*0.15),h=window.innerHeight;
    const v=a.y<edge?-(edge-a.y)/edge*18:a.y>h-edge?(a.y-(h-edge))/edge*18:0;
    if(v){window.scrollBy(0,v);a.update({clientX:a.x,clientY:a.y});}
    a.raf=requestAnimationFrame(step);
  };
  reorderAutoScroll.raf=requestAnimationFrame(step);
}
function reorderAutoScrollStop(){cancelAnimationFrame(reorderAutoScroll.raf);reorderAutoScroll={raf:0,x:0,y:0,update:null};}
let rosterPointerStart=null;
let rosterPointerActive=false;
let rosterPointerMoved=false;
let rosterPointerTimer=null;
let rosterSuppressClickUntil=0;
let rosterPointerDropTarget=null;
let rosterPointerDropAfter=false;
function clearRosterDragVisuals(){
  document.querySelectorAll('.dash-wcard.dragging,.dash-wcard.drag-over').forEach(c=>c.classList.remove('dragging','drag-over'));
}
function beginRosterPointerDrag(e){
  const card=e.currentTarget;
  if(!card)return;
  if(e.pointerType==='mouse'&&e.button!==0)return;
  if(e.target.closest('button,input,textarea,select'))return;
  clearTimeout(rosterPointerTimer);
  rosterPointerStart={card,pointerId:e.pointerId,x:e.clientX,y:e.clientY,type:e.pointerType};
  rosterPointerActive=false;
  rosterPointerMoved=false;
  rosterPointerDropTarget=null;
  rosterPointerDropAfter=false;
  if(e.pointerType==='touch'){
    rosterPointerTimer=setTimeout(()=>activateRosterPointerDrag(e.pointerId),TOUCH_REORDER_HOLD_MS);
  }
}
function activateRosterPointerDrag(pointerId){
  const st=rosterPointerStart;
  if(!st)return;
  rosterPointerActive=true;
  st.card.classList.add('dragging');
  if(st.type==='touch'){rosterSuppressClickUntil=Date.now()+60000;try{navigator.vibrate?.(30)}catch(_){}}
  try{st.card.setPointerCapture(pointerId)}catch(_){}
}
function updateRosterDropTarget(e){
  const st=rosterPointerStart;
  if(!st||!rosterPointerActive)return;
  const el=document.elementFromPoint(e.clientX,e.clientY);
  const target=el?.closest?.('.dash-wcard[data-roster-id]');
  document.querySelectorAll('.dash-wcard.drag-over').forEach(c=>c.classList.remove('drag-over'));
  if(!target||target===st.card){
    rosterPointerDropTarget=null;
    rosterPointerDropAfter=false;
    return;
  }
  rosterPointerDropTarget=target;
  const rect=target.getBoundingClientRect();
  rosterPointerDropAfter=e.clientX>=rect.left+rect.width/2;
  target.classList.add('drag-over');
}
function moveRosterPointerDrag(e){
  const st=rosterPointerStart;
  if(!st||e.pointerId!==st.pointerId)return;
  const dx=e.clientX-st.x,dy=e.clientY-st.y;
  if(!rosterPointerActive){
    // Touch: any real movement before the hold delay means the finger is
    // scrolling — drop the pending reorder and let the page scroll.
    if(st.type==='touch'){
      if(Math.hypot(dx,dy)>TOUCH_REORDER_SLOP_PX){clearTimeout(rosterPointerTimer);rosterPointerStart=null;}
      return;
    }
    if(Math.hypot(dx,dy)<6)return;
    clearTimeout(rosterPointerTimer);
    activateRosterPointerDrag(e.pointerId);
  }
  if(!rosterPointerActive)return;
  rosterPointerMoved=true;
  e.preventDefault();
  updateRosterDropTarget(e);
  reorderAutoScrollTrack(e,updateRosterDropTarget);
}
function finishRosterPointerDrag(e,cancelled=false){
  clearTimeout(rosterPointerTimer);
  const st=rosterPointerStart;
  if(!st)return;
  const moved=rosterPointerActive&&rosterPointerMoved;
  const source=st.card;
  if(moved&&!cancelled){
    e.preventDefault();
    rosterSuppressClickUntil=Date.now()+500;
    const target=rosterPointerDropTarget;
    if(target){
      const sourceId=source.dataset.rosterId;
      const targetId=target.dataset.rosterId;
      const list=state.rosters.slice();
      const from=list.findIndex(x=>x.id===sourceId);
      let to=list.findIndex(x=>x.id===targetId);
      if(from>=0&&to>=0&&from!==to){
        const [item]=list.splice(from,1);
        if(from<to)to--;
        list.splice(rosterPointerDropAfter?to+1:to,0,item);
        state.rosters=list;
        save(true);
      }
    }
  }
  if(rosterPointerActive&&st.type==='touch')rosterSuppressClickUntil=Date.now()+500;
  reorderAutoScrollStop();
  clearRosterDragVisuals();
  try{source.releasePointerCapture?.(st.pointerId)}catch(_){}
  rosterPointerStart=null;
  rosterPointerActive=false;
  rosterPointerDropTarget=null;
  rosterPointerDropAfter=false;
  setTimeout(()=>rosterPointerMoved=false,50);
  if(moved&&!cancelled)render('rosters');
}
function attachRosterInteractions(){
  document.querySelectorAll('.dash-wcard[data-roster-id]').forEach(card=>{
    if(card.dataset.bound==='1')return;
    card.dataset.bound='1';
    // V-ROSTERDRAG-NATIVEDRAG: this card is an <a href> — browsers make
    // links natively draggable (a ghost-image "drag the link out" gesture)
    // regardless of the pointer handlers below, and once that native drag
    // starts it swallows the pointermove sequence our own drag logic needs,
    // so the press-and-hold reorder never activated. Block it outright.
    card.addEventListener('dragstart',e=>e.preventDefault());
    card.addEventListener('pointerdown',beginRosterPointerDrag);
    card.addEventListener('touchmove',e=>{if(rosterPointerActive)e.preventDefault();},{passive:false});
    card.addEventListener('contextmenu',e=>{if(rosterPointerStart)e.preventDefault();});
    card.addEventListener('pointermove',moveRosterPointerDrag);
    card.addEventListener('pointerup',e=>finishRosterPointerDrag(e,false));
    card.addEventListener('pointercancel',e=>finishRosterPointerDrag(e,true));
    card.addEventListener('click',e=>{
      if(Date.now()<rosterSuppressClickUntil||rosterPointerMoved){
        e.preventDefault();
        e.stopPropagation();
      }
    });
  });
}
