let pbSubState=(()=>{try{return JSON.parse(restoreUiState('pbSubOpen','{}'))||{}}catch(e){return {}}})();
function pbSubOpen(n){return pbSubState[n]!==false}
function togglePbSub(n,e){if(e&&e.target?.closest?.('button,input,select,textarea,a,label'))return;pbSubState[n]=!pbSubOpen(n);try{persistUiState('pbSubOpen',JSON.stringify(pbSubState))}catch(err){}const el=document.querySelector(`[data-pb-sub="${n}"]`);if(el){el.classList.toggle('pb-collapsed',!pbSubOpen(n));el.querySelector('.pb-sub-head')?.setAttribute('aria-expanded',String(pbSubOpen(n)))}}
function postBattleIncomeView(r,f){const en=siteLanguage==='en';const p=ensurePostBattleData(r),dice=postBattleDieRows(),selected=postBattleSelectedDice(p),sum=selected.reduce((a,b)=>a+b,0),shards=selected.length?postBattleShards(sum):0,warriors=Math.max(1,r.fighters.length),available=Number(r.wyrdstone||0),sold=Math.min(Number(p.soldShards||0),available),income=sold>0?postBattleIncomeMatrix(warriors,sold):null,exploration=postBattleExploration(p),allRolls=dice.filter(d=>Number.isInteger(Number(d.value))).map(d=>Number(d.value)),selectedCount=dice.filter(d=>d.selected).length,heroes=postBattleEligibleHeroes(r),stragglerChoice=p.exploration?.stragglerChoice||'',bonuses=explorationBonusList(r);return `<div class="postbattle-shell"><div class="postbattle-toolbar"><div><div class="eyebrow">POST-BATTLE / STEP 3</div><h3>Income & Exploration</h3><p>${en?'One die per Hero validated as a survivor, +1 die on a win, plus any extra dice allowed. Six dice maximum are kept.':'Un dé pour chaque Hero validé comme survivant, +1 dé en cas de victoire, puis les dés supplémentaires autorisés. Six dés maximum sont retenus.'}</p></div><button type="button" class="button danger-outline" onclick="resetPostBattle()">${en?'Reset':'Réinitialiser'}</button></div><div class="postbattle-grid"><section class="sheet-block postbattle-panel pb-sub${pbSubOpen('1')?'':' pb-collapsed'}" data-pb-sub="1"><div class="sheet-block-head prominent-section pb-sub-head" role="button" tabindex="0" aria-expanded="${pbSubOpen('1')}" onclick="togglePbSub('1',event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();togglePbSub('1',event)}"><span class="pb-sub-chevron" aria-hidden="true">⌄</span><div><h4><b class="pb-sub-num">1</b>${en?'Exploration Dice':'Dés d’Exploration'}</h4><small>${en?'Check exactly the Heroes who survived the battle. Henchmen don’t roll a die.':'Coche précisément les Heroes qui ont survécu à la bataille. Les Henchmen ne lancent pas de dé.'}</small></div><span class="postbattle-counter">${selectedCount}/6 ${en?'kept':'retenus'}</span></div><div class="postbattle-income-layout"><div class="postbattle-heroes-column"><div class="postbattle-hero-validation"><span class="postbattle-field-title">${en?'Heroes who survived':'Heroes ayant survécu'}</span>${heroes.length?heroes.map(x=>{const checked=p.survivingHeroIds.includes(x.instance);return `<label class="postbattle-hero-check"><input type="checkbox" ${checked?'checked':''} onchange="togglePostBattleHero('${x.instance}',this.checked)"><span><b>${esc(x.name)}</b><small>${esc(x.type||'Hero')}</small></span><em>✓</em></label>`}).join(''):`<div class="empty compact">${en?'No eligible Hero in the warband.':'Aucun Hero éligible dans la bande.'}</div>`}<small class="postbattle-help">${p.heroCount} Hero${p.heroCount!==1?'s':''} ${en?'validated':`validé${p.heroCount!==1?'s':''}`} → ${p.heroCount} ${en?`di${p.heroCount!==1?'ce':'e'}`:`dé${p.heroCount!==1?'s':''}`}.</small></div></div><div class="postbattle-roll-column"><div class="postbattle-dice-head"><span>${en?'Each die can be rolled or entered manually.':'Chaque dé peut être lancé ou saisi manuellement.'}</span></div><div class="postbattle-dice-list">${dice.length?dice.map((d,i)=>`<div class="postbattle-die ${d.selected?'selected':''} ${d.value?'rolled':''}"><button type="button" class="postbattle-select" title="${d.selected?(en?'Remove from the 6 kept dice':'Retirer des 6 dés retenus'):(en?'Keep this die':'Retenir ce dé')}" onclick="togglePostBattleDie(${i})">${d.selected?'✓':'○'}</button><span class="postbattle-die-source">${esc(d.source||(en?'Die':'Dé'))}</span><input class="postbattle-die-input" type="number" min="1" max="6" placeholder="–" value="${d.value??''}" onchange="editPostBattleDie(${i},this.value)"><button type="button" class="button secondary small" onclick="rollPostBattleDie(${i})">🎲 ${d.value?(en?'Reroll':'Relancer'):(en?'Roll':'Lancer')}</button></div>`).join(''):`<div class="empty compact">${en?'Check at least one surviving Hero to generate the dice.':'Coche au moins un Hero survivant pour générer les dés.'}</div>`}</div></div><div class="postbattle-bonus-controls"><label class="postbattle-check"><input type="checkbox" ${p.winner?'checked':''} onchange="setPostBattleWinner(this.checked)"><span>${en?'Won the last battle':'Victoire de la dernière bataille'} <b>+1 ${en?'die':'dé'}</b></span></label><label><span>${en?'Extra dice':'Dés supplémentaires'}</span><input type="number" min="0" max="20" value="${p.extraDice}" onchange="setPostBattleNumber('extraDice',this.value)"><small>${en?'Skills, equipment or any other allowed bonus':'Compétences, équipement ou autre bonus autorisé'}</small></label></div></div><div class="postbattle-summary"><div><span>${en?'Dice generated':'Dés générés'}</span><strong>${dice.length}</strong></div><div><span>${en?'Dice filled in':'Dés renseignés'}</span><strong>${allRolls.length}</strong></div><div><span>${en?'Dice kept':'Dés retenus'}</span><strong>${selected.length}</strong></div><div><span>${en?'Total':'Total'}</span><strong>${selected.length?sum:'—'}</strong></div><div><span>${en?'Shards found':'Shards trouvés'}</span><strong>${selected.length?shards:'—'}</strong></div></div></section><section class="sheet-block postbattle-panel pb-sub${pbSubOpen('2')?'':' pb-collapsed'}" data-pb-sub="2"><div class="sheet-block-head prominent-section pb-sub-head" role="button" tabindex="0" aria-expanded="${pbSubOpen('2')}" onclick="togglePbSub('2',event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();togglePbSub('2',event)}"><span class="pb-sub-chevron" aria-hidden="true">⌄</span><div><h4><b class="pb-sub-num">2</b>${en?'Exploration':'Exploration'}</h4><small>${en?'The most numerous multiple wins; ties keep the highest result.':'Le multiple le plus nombreux prime ; à égalité, le résultat le plus élevé est retenu.'}</small></div></div>${exploration?`<div class="exploration-result"><div class="exploration-badge">${exploration.count===2?'DOUBLE':exploration.count===3?'TRIPLE':exploration.count===4?(en?'QUADRUPLE':'QUATRE'):exploration.count===5?(en?'QUINTUPLE':'CINQ'):(en?'SEXTUPLE':'SIX')} · ${exploration.face}</div><h3>${esc(exploration.result.name)}</h3><p class="exploration-lore"><em>${esc(frData(`explore-lore:${exploration.tier}:${exploration.face}`,EXPLORATION_LORE[exploration.tier][exploration.face]))}</em></p><div class="exploration-effect"><strong>${en?'Rules / resolution':'Règles / résolution'}</strong><p>${esc(frData(`explore:${exploration.tier}:${exploration.face}`,exploration.result.text))}</p></div>${exploration.tier==='doubles'&&exploration.face===4&&explorationIsUndead(r)?`<div class="exploration-choice"><strong>${en?'Straggler — Undead warband choice':'Straggler — choix de la bande Undead'}</strong><div><button class="button secondary ${stragglerChoice==='skeleton'?'active':''}" onclick="setStragglerChoice('skeleton')">☠ Skeleton Warrior</button><button class="button secondary ${stragglerChoice==='zombie'?'active':''}" onclick="setStragglerChoice('zombie')">🧟 Zombie Warrior</button></div></div>`:''}${exploration.tier==='triples'&&exploration.face===3&&explorationIsUndead(r)?`<div class="exploration-choice"><strong>${en?'Prisoners — Undead warband choice':'Prisonniers — choix de la bande Undead'}</strong><div><button class="button secondary ${stragglerChoice==='skeleton'?'active':''}" onclick="setStragglerChoice('skeleton')">☠ Skeleton Warrior</button><button class="button secondary ${stragglerChoice==='zombie'?'active':''}" onclick="setStragglerChoice('zombie')">🧟 Zombie Warrior</button></div></div>`:''}<button type="button" class="button primary" onclick="applyExplorationReward()">🎲 ${en?`Automatically resolve ${esc(exploration.result.name)}’s rewards`:`Résoudre automatiquement les récompenses de ${esc(exploration.result.name)}`}</button><small class="exploration-repeat-help">${en?'This result stays available: you can reroll the rewards or pick a new option without undoing the previous one.':'Cette résolution reste disponible : tu peux relancer les récompenses ou choisir une nouvelle option sans annuler la précédente.'}</small></div>`:`<div class="empty compact"><strong>${en?'No unusual location detected.':'Aucun lieu inhabituel détecté.'}</strong><span>${en?'Fill in at least two matching dice to display the matching entry.':'Renseigne au moins deux dés identiques pour afficher l’entrée correspondante.'}</span></div>`}${selected.length?`<div class="shard-result"><span>${en?'Table result':'Résultat de la table'}</span><strong>${shards} ${en?`wyrdstone shard${shards!==1?'s':''}`:`shard${shards!==1?'s':''} de wyrdstone`}</strong><button type="button" class="button primary small" onclick="cashPostBattleWyrdstone()">＋ ${en?'Put this wyrdstone in stock':'Mettre ces wyrdstone en réserve'}</button><small>${en?'Adds this result to the warband’s Wyrdstone stock. You can click again to add the pool again.':'Ajoute ce résultat à la réserve Wyrdstone de la bande. Tu peux recliquer pour ajouter à nouveau la pool.'}</small></div>`:''}${bonuses.length?`<div class="exploration-bonus-strip"><div class="exploration-bonus-title"><span>${en?'UNLOCKED EXPLORATION EFFECTS':'EFFETS D’EXPLORATION DÉBLOQUÉS'}</span><small>${en?'These effects stay tied to the warband until removed.':'Ces effets restent liés à la bande jusqu’à leur suppression.'}</small></div>${bonuses.map(b=>`<div class="exploration-bonus"><span class="exploration-bonus-icon">${b.icon}</span><div><strong>${esc(b.label)}</strong><small>${esc(b.description)}</small></div><button type="button" class="equipment-action remove" title="${en?'Remove this bonus':'Supprimer ce bonus'}" onclick="removeExplorationBonus('${b.id}')">🗑</button></div>`).join('')}</div>`:''}</section></div><section class="sheet-block postbattle-panel pb-sub${pbSubOpen('3')?'':' pb-collapsed'}" data-pb-sub="3"><div class="sheet-block-head prominent-section pb-sub-head" role="button" tabindex="0" aria-expanded="${pbSubOpen('3')}" onclick="togglePbSub('3',event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();togglePbSub('3',event)}"><span class="pb-sub-chevron" aria-hidden="true">⌄</span><div><h4><b class="pb-sub-num">3</b>${en?'Selling wyrdstone':'Vente de wyrdstone'}</h4><small>${en?'The table uses the number of warriors and the number of shards sold.':'Le tableau utilise le nombre de guerriers et le nombre de shards vendus.'}</small></div><span class="postbattle-counter">${available} shard${available!==1?'s':''} ${en?'available':'disponibles'}</span></div><div class="postbattle-controls income-controls"><div class="postbattle-readonly"><span>${en?'Warriors in the warband':'Guerriers dans la bande'}</span><strong>${warriors}</strong><small>${en?'Calculated automatically from the roster.':'Calculé automatiquement depuis le roster.'}</small></div><label><span>${en?'Shards sold':'Shards vendus'}</span><input type="number" min="0" max="${available}" value="${sold}" onchange="setPostBattleNumber('soldShards',this.value)" ${available?'':'disabled'}><small>${en?'The sale uses the Wyrdstone currently in stock.':'La vente utilise le Wyrdstone actuellement en réserve.'}</small></label><div class="income-total"><span>${en?'Calculated profit':'Profit calculé'}</span><strong>${income?income.value:0} GC</strong></div></div><div class="income-apply-row"><button type="button" class="button primary" onclick="sellPostBattleWyrdstone()" ${sold>0&&!p.incomeApplied?'':'disabled'}>${p.incomeApplied?(en?'✓ Sale applied':'✓ Vente appliquée'):(en?'💰 Sell the selected shards':'💰 Vendre les shards sélectionnés')}</button><span>${p.incomeApplied?(en?`Last sale: ${p.soldShards} shard${p.soldShards!==1?'s':''} · +${p.income} GC.`:`Dernière vente : ${p.soldShards} shard${p.soldShards!==1?'s':''} · +${p.income} GC.`):(en?'The amount will be removed from the Wyrdstone stock and added to the Treasury.':'Le montant sera retiré de la réserve Wyrdstone et ajouté au Trésor.')}</span></div><div class="income-table-wrap"><table class="postbattle-income-table"><thead><tr><th>${en?'Warriors':'Guerriers'}</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8+</th></tr></thead><tbody>${[['1–3',45,60,75,90,110,120,145,155],['4–6',40,55,70,80,100,110,130,140],['7–9',35,50,65,70,90,100,120,130],['10–12',30,45,60,65,80,90,110,120],['13–15',30,40,55,60,70,80,100,110],['16+',25,35,50,55,65,70,90,100]].map((row,i)=>`<tr class="${warriors>=1&&((i===0&&warriors<=3)||(i===1&&warriors>=4&&warriors<=6)||(i===2&&warriors>=7&&warriors<=9)||(i===3&&warriors>=10&&warriors<=12)||(i===4&&warriors>=13&&warriors<=15)||(i===5&&warriors>=16))?'current':''}">${row.map((v,j)=>j===0?`<th>${v}</th>`:`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div>`}
// ===== Step 4: post-battle actions (V-PBACTIONS) =====
// Each Leader/Champion not In Recovery, Captured, Critical or dead picks one
// action. Choices live in r.postBattle.actions (keyed by fighter instance)
// and only touch the roster when "Apply to roster" is pressed, so the
// player can change their mind until then. Actions are defined in
// POST_BATTLE_ACTIONS so new ones can be added later.
const POST_BATTLE_ACTIONS=[
  {id:'trade',en:'Visit the Trading Post',fr:'Visit the Trading Post'},
  {id:'sell',en:'Sell Captive',fr:'Sell Captive'},
  {id:'medic',en:'Medical Escort',fr:'Medical Escort'}
];
let postBattleStep4Open=false;
function rosterCaptives(r){if(!Array.isArray(r.captives))r.captives=[];return r.captives}
function pbaPlan(r){const p=ensurePostBattleData(r);if(!p.actions||typeof p.actions!=='object')p.actions={};return p.actions}
function pbaActors(r){return (r.fighters||[]).filter(x=>['Leader','Champion'].includes(x.type))}
function pbaBlockReason(x){const st=fighterStatus(x),en=siteLanguage==='en';if(st.dead)return en?'Dead.':'Mort.';if(st.captured)return en?'Captured: cannot act.':'Capturé : ne peut pas agir.';if(st.recovery)return en?'In Recovery: cannot act this time.':'En Recovery : ne peut pas agir cette fois.';if(st.critical)return en?'Critically injured: cannot act.':'Blessé critique : ne peut pas agir.';return ''}
function pbaEligible(r){return pbaActors(r).filter(x=>!pbaBlockReason(x))}
function pbaHalf5(v){return Math.ceil(Math.max(0,Number(v)||0)/2/5)*5}
function pbaCriticals(r){return (r.fighters||[]).filter(x=>{const st=fighterStatus(x);return st.critical&&!st.dead})}
function pbaSoldBy(plan,cid){return Object.keys(plan).find(k=>plan[k]?.action==='sell'&&(plan[k].captives||[]).includes(cid))}
function pbaEscortedBy(plan,pid){return Object.keys(plan).find(k=>plan[k]?.action==='medic'&&plan[k].patient===pid)}
function pbaSales(r){const plan=pbaPlan(r),caps=rosterCaptives(r);return Object.values(plan).filter(a=>a?.action==='sell').flatMap(a=>a.captives||[]).reduce((n,id)=>{const c=caps.find(q=>q.id===id);return n+(c?pbaHalf5(c.value):0)},0)}
function pbaFees(r,{pending=true}={}){return Object.values(pbaPlan(r)).filter(a=>a?.action==='medic'&&a.cost!=null&&a.pay!==false&&(pending||a.roll!=null)).reduce((n,a)=>n+Number(a.cost||0),0)}
function pbaRareBonus(r){const plan=pbaPlan(r),el=pbaEligible(r).filter(x=>plan[x.instance]?.action==='trade');const lead=el.some(x=>x.type==='Leader')?2:0,champs=el.filter(x=>x.type==='Champion').length,rep=Math.floor(Math.max(0,Number(r.reputation||0))/10);const cm=choiceRarityMod(r);return {lead,champs,rep,mod:cm.mod,modLabel:cm.label,total:lead+champs+rep+cm.mod}}
function pbaChange(fn){const r=activeRoster();if(!r)return;const p=ensurePostBattleData(r);if(p.actionsApplied)return;postBattleStep4Open=true;fn(r,pbaPlan(r));save(true);render('builder')}
function pbaSetAction(inst,a){pbaChange((r,plan)=>{const cur=plan[inst];plan[inst]=cur?.action===a?{action:null}:{action:a,captives:[],patient:null,cost:null,costDice:null,pay:true,roll:null,li:null}})}
function pbaToggleCaptive(inst,cid,on){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='sell')return;const other=pbaSoldBy(plan,cid);if(on&&other&&other!==inst)return;a.captives=(a.captives||[]).filter(x=>x!==cid);if(on)a.captives.push(cid)})}
function pbaSetPatient(inst,pid){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='medic')return;const other=pid&&pbaEscortedBy(plan,pid);if(other&&other!==inst)return;if(a.patient!==(pid||null)){a.cost=null;a.costDice=null;a.roll=null;a.li=null;a.pay=true}a.patient=pid||null})}
function pbaRollFee(inst){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='medic'||!a.patient)return;a.costDice=[postBattleRoll(),postBattleRoll()];a.cost=(a.costDice[0]+a.costDice[1])*10;a.roll=null;a.li=null;a.pay=true})}
// Back to the pay / don't-pay choice (to correct a mistake or reroll the D6).
function pbaClearResult(inst){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='medic')return;a.roll=null;a.li=null;a.pay=true})}
// Next session: start a fresh round of Step 4 actions. What was already
// applied to the roster stays as it is.
function pbaNewRound(){const r=activeRoster();if(!r)return;const p=ensurePostBattleData(r);p.actions={};p.actionsApplied=false;p.actionsLog=[];postBattleStep4Open=true;save(true);render('builder')}
function pbaAvailable(r){return Number(r.gold||0)+pbaSales(r)-pbaFees(r)}
function pbaPay(inst){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='medic'||a.cost==null)return;if(a.roll==null&&pbaAvailable(r)<0){toast(siteLanguage==='en'?'Not enough gold in the Stash':'Pas assez d’or dans la réserve');return}a.pay=true;a.roll=postBattleRoll();a.li=a.roll>=2&&a.roll<=5?postBattleRoll():null})}
function pbaNoPay(inst){pbaChange((r,plan)=>{const a=plan[inst];if(!a||a.action!=='medic'||a.cost==null)return;a.pay=false;a.roll=0;a.li=null})}
function pbaOpenEscorts(r){const plan=pbaPlan(r);return pbaEligible(r).filter(x=>{const a=plan[x.instance];return a?.action==='medic'&&(!a.patient||a.roll==null)})}
function applyPostBattleActions(){
  const en=siteLanguage==='en';const r=activeRoster();if(!r)return;const p=ensurePostBattleData(r);if(p.actionsApplied)return;
  const open=pbaOpenEscorts(r);if(open.length){toast(en?`Finish the Medical Escort for ${open.map(x=>x.name).join(', ')} first`:`Termine d’abord le Medical Escort de ${open.map(x=>x.name).join(', ')}`);return}
  const plan=pbaPlan(r),caps=rosterCaptives(r),log=[];
  const sales=pbaSales(r),fees=pbaFees(r,{pending:false});
  Object.entries(plan).forEach(([inst,a])=>{
    const actor=(r.fighters||[]).find(x=>x.instance===inst);if(!actor||!a?.action||pbaBlockReason(actor))return;
    if(a.action==='trade')log.push(en?`${actor.name}: Visit the Trading Post`:`${actor.name} : Visit the Trading Post`);
    if(a.action==='sell'){(a.captives||[]).forEach(cid=>{const c=caps.find(q=>q.id===cid);if(!c)return;log.push(en?`${actor.name} sold captive ${c.name} (+${pbaHalf5(c.value)} GC)`:`${actor.name} a vendu le captif ${c.name} (+${pbaHalf5(c.value)} GC)`)});r.captives=rosterCaptives(r).filter(c=>!(a.captives||[]).includes(c.id))}
    if(a.action==='medic'&&a.patient){
      const x=(r.fighters||[]).find(q=>q.instance===a.patient);if(!x)return;const st=fighterStatus(x);
      if(a.pay===false||a.roll===1){st.dead=true;st.critical=false;st.recovery=false;st.captured=false;log.push(en?`${actor.name} escorted ${x.name}: ${a.pay===false?'not treated':'complications'}, dead`:`${actor.name} a escorté ${x.name} : ${a.pay===false?'non soigné':'complications'}, mort`)}
      else if(a.roll===6){st.critical=false;st.recovery=true;log.push(en?`${actor.name} escorted ${x.name}: full recovery, in Recovery (−${a.cost} GC)`:`${actor.name} a escorté ${x.name} : récupération complète, en Recovery (−${a.cost} GC)`)}
      else{const roll=50+Number(a.li||1);const res=lastingInjuryByRoll(roll);st.critical=false;st.recovery=true;if(res){normalizeInjuries(x);const inj=injuryObjectFromResult(res);x.injuries.push(inj);applyInjuryStatMods(x,inj,1)}log.push(en?`${actor.name} escorted ${x.name}: stabilized, Lasting Injury ${roll}${res?` ${res.name}`:''} (−${a.cost} GC)`:`${actor.name} a escorté ${x.name} : stabilisé, Lasting Injury ${roll}${res?` ${res.name}`:''} (−${a.cost} GC)`)}
    }
  });
  r.gold=Math.max(0,Number(r.gold||0)+sales-fees);
  const bonus=pbaRareBonus(r);p.rareBonus=bonus.total;p.actionsLog=log;p.actionsApplied=true;
  if(sales||fees)logHistory(r,'treasury',en?`Post-battle actions: ${sales?`+${sales} GC captives`:''}${sales&&fees?', ':''}${fees?`−${fees} GC physician`:''}`:`Actions post-bataille : ${sales?`+${sales} GC captifs`:''}${sales&&fees?', ':''}${fees?`−${fees} GC physician`:''}`);
  log.filter(t=>/escort/i.test(t)).forEach(t=>logHistory(r,'xp',t));
  postBattleStep4Open=true;save(true);render('builder');toast(en?'Post-battle actions applied':'Actions post-bataille appliquées');
}
function pbaOutcomeMarkup(a){
  const en=siteLanguage==='en';const die=n=>`<span class="pba-die">${n}</span>`;
  if(a.pay===false)return `<div class="pba-outcome bad"><b>${en?'Not treated.':'Non soigné.'}</b> ${en?'The warrior dies.':'Le combattant meurt.'}</div>`;
  if(a.roll===1)return `<div class="pba-outcome bad">${die(1)} <b>Complications.</b> ${en?'The warrior dies.':'Le combattant meurt.'}</div>`;
  if(a.roll===6)return `<div class="pba-outcome good">${die(6)} <b>Full Recovery.</b> ${en?'Goes into Recovery, no lasting effect.':'Part en Recovery, sans séquelle.'}</div>`;
  const res=lastingInjuryByRoll(50+Number(a.li||1));
  return `<div class="pba-outcome mid">${die(a.roll)} <b>Stabilized.</b> Lasting Injury D66 = <b class="pba-mono">5${a.li}</b>${res?` · ${esc(res.name)}`:''}. ${en?'Goes into Recovery.':'Part en Recovery.'}</div>`;
}
function pbaActorMarkup(r,x){
  const en=siteLanguage==='en';const plan=pbaPlan(r),a=plan[x.instance]||{action:null},block=pbaBlockReason(x),applied=!!r.postBattle?.actionsApplied;
  const caps=rosterCaptives(r),crits=pbaCriticals(r),lockedMedic=false;
  const st=fighterStatus(x);
  const badges=`<span class="pba-badge${x.type==='Leader'?' lead':''}">${esc(x.type)}</span>${st.recovery?'<span class="pba-badge warn">In Recovery</span>':''}${st.captured?`<span class="pba-badge bad">${en?'Captured':'Capturé'}</span>`:''}${st.critical&&!st.dead?'<span class="pba-badge bad">Critical</span>':''}${st.dead?'<span class="pba-badge bad">Dead</span>':''}`;
  let segs='';
  if(!block){segs=`<div class="pba-segs" role="group" aria-label="${esc(x.name)}">${POST_BATTLE_ACTIONS.map(def=>{let dis=applied||(lockedMedic&&def.id!=='medic');let title='';if(def.id==='sell'&&!caps.some(c=>c.rescueChance&&(!pbaSoldBy(plan,c.id)||pbaSoldBy(plan,c.id)===x.instance))){dis=true;title=en?'No captive can be sold':'Aucun captif ne peut être vendu'}if(def.id==='medic'&&!crits.some(c=>c.instance!==x.instance&&(!pbaEscortedBy(plan,c.instance)||pbaEscortedBy(plan,c.instance)===x.instance))){dis=true;title=en?'No critically injured warrior to escort':'Aucun blessé critique à escorter'}return `<button type="button" class="pba-seg${a.action===def.id?' on':''}" ${dis?'disabled':''} ${title?`title="${esc(title)}"`:''} onclick="pbaSetAction('${esc(x.instance)}','${def.id}')">${esc(en?def.en:def.fr)}</button>`}).join('')}</div>`}
  let detail='';
  if(!block&&a.action==='trade'){const b=x.type==='Leader'?2:1;detail=`<div class="pba-detail"><span>✓ ${en?`Adds <b class="pba-mono">+${b}</b> to the Seek Rare Equipment roll at the Trading Post.`:`Ajoute <b class="pba-mono">+${b}</b> au jet de Seek Rare Equipment au Trading Post.`}</span></div>`}
  if(!block&&a.action==='sell'){
    const rows=caps.map(c=>{const other=pbaSoldBy(plan,c.id);const taken=other&&other!==x.instance;const dis=applied||!c.rescueChance||taken;const note=!c.rescueChance?(en?'Their warband has not had a chance to rescue them yet':'Leur bande n’a pas encore eu l’occasion de les secourir'):taken?(en?'Already sold by another warrior':'Déjà vendu par un autre combattant'):(en?`Half of ${Number(c.value||0)} GC, rounded up to 5`:`Moitié de ${Number(c.value||0)} GC, arrondie au 5 supérieur`);return `<label class="pba-cap"><input type="checkbox" ${(a.captives||[]).includes(c.id)?'checked':''} ${dis?'disabled':''} onchange="pbaToggleCaptive('${esc(x.instance)}','${esc(c.id)}',this.checked)"><span><b>${esc(c.name)}</b><small>${esc(c.warband||'—')} · ${note}</small></span><b class="pba-mono pba-plus">+${pbaHalf5(c.value)} GC</b></label>`}).join('');
    detail=`<div class="pba-detail"><small>${en?'Sell any number of captives. The gold goes to the treasury.':'Vends autant de captifs que tu veux. L’or va dans le trésor.'}</small>${rows||`<small>${en?'No captive in the Stash.':'Aucun captif dans la réserve.'}</small>`}</div>`;
  }
  if(!block&&a.action==='medic'){
    const patientX=a.patient?(r.fighters||[]).find(q=>q.instance===a.patient):null;
    const optList=crits.filter(c=>c.instance!==x.instance);if(patientX&&!optList.includes(patientX))optList.unshift(patientX);
    const opts=optList.map(c=>{const other=pbaEscortedBy(plan,c.instance);const taken=other&&other!==x.instance;return `<option value="${esc(c.instance)}" ${a.patient===c.instance?'selected':''} ${taken?'disabled':''}>${esc(c.name)}${taken?(en?' (already escorted)':' (déjà escorté)'):''}</option>`}).join('');
    let body=`<label class="pba-row"><span>${en?'Patient':'Patient'}</span><select ${applied?'disabled':''} onchange="pbaSetPatient('${esc(x.instance)}',this.value)"><option value="">${en?'Choose a critically injured warrior…':'Choisis un blessé critique…'}</option>${opts}</select></label>`;
    if(a.patient){
      if(a.cost==null)body+=`<div class="pba-row"><button type="button" class="button secondary" onclick="pbaRollFee('${esc(x.instance)}')">${en?'Roll physician fee (2D6 × 10)':'Lancer le coût du Physician (2D6 × 10)'}</button></div>`;
      else{
        body+=`<div class="pba-row">${en?'Fee':'Coût'} : <span class="pba-die">${a.costDice?.[0]??'?'}</span><span class="pba-die">${a.costDice?.[1]??'?'}</span> × 10 = <b class="pba-mono">${a.cost} GC</b>${applied?'':`<button type="button" class="pba-mini" onclick="pbaRollFee('${esc(x.instance)}')">↻ ${en?'Reroll fee':'Relancer le coût'}</button>`}</div>`;
        if(a.roll==null){const ok=pbaAvailable(r)>=0;body+=`<div class="pba-row"><button type="button" class="button primary" ${ok?'':'disabled'} onclick="pbaPay('${esc(x.instance)}')">${en?`Pay ${a.cost} GC and roll D6`:`Payer ${a.cost} GC et lancer 1D6`}</button><button type="button" class="button danger-outline" onclick="pbaNoPay('${esc(x.instance)}')">${en?'Don’t pay (warrior dies)':'Ne pas payer (le combattant meurt)'}</button></div>${ok?'':`<div class="pba-outcome bad">${en?'Not enough gold: the warrior cannot be treated.':'Pas assez d’or : le combattant ne peut pas être soigné.'}</div>`}`}
        else body+=pbaOutcomeMarkup(a)+(applied?'':`<div class="pba-row">${a.pay!==false?`<button type="button" class="pba-mini" onclick="pbaPay('${esc(x.instance)}')">↻ ${en?'Reroll D6':'Relancer le D6'}</button>`:''}<button type="button" class="pba-mini" onclick="pbaClearResult('${esc(x.instance)}')">✎ ${en?'Change choice':'Changer le choix'}</button></div>`);
      }
    }
    detail=`<div class="pba-detail">${body}</div>`;
  }
  return `<div class="pba-actor${block?' locked':''}"><div class="pba-actor-top"><div class="pba-who"><strong>${esc(x.name)}</strong><div class="pba-badges">${badges}</div></div>${segs}</div>${block?`<small class="pba-why">${block}</small>`:''}${detail}</div>`;
}
function postBattleActionsView(r,f){
  const en=siteLanguage==='en';const p=ensurePostBattleData(r),plan=pbaPlan(r),applied=!!p.actionsApplied;
  const actors=pbaActors(r),elig=pbaEligible(r),used=elig.filter(x=>plan[x.instance]?.action).length;
  const sales=pbaSales(r),paid=pbaFees(r,{pending:false}),pending=pbaFees(r)-paid,bonus=pbaRareBonus(r);
  const crits=pbaCriticals(r),unescorted=crits.filter(c=>!pbaEscortedBy(plan,c.instance));
  const open=pbaOpenEscorts(r);
  const changes=[];
  Object.values(plan).forEach(a=>{if(a?.action==='sell')(a.captives||[]).forEach(cid=>{const c=rosterCaptives(r).find(q=>q.id===cid);if(c)changes.push(`<div><span>${en?'Captive sold':'Captif vendu'} · ${esc(c.name)}</span><span class="pba-plus">+${pbaHalf5(c.value)} GC</span></div>`)});if(a?.action==='medic'&&a.patient&&a.roll!=null){const x=(r.fighters||[]).find(q=>q.instance===a.patient);if(!x)return;const res=a.pay===false||a.roll===1?`<span class="pba-minus">${en?'Dead':'Mort'}</span>`:a.roll===6?'<span>Recovery</span>':`<span>Recovery · 5${a.li}</span>`;changes.push(`<div><span>${esc(x.name)}</span>${res}</div>`)}});
  const actorsHtml=actors.length?actors.map(x=>pbaActorMarkup(r,x)).join(''):`<div class="empty compact">${en?'No Leader or Champion in this warband.':'Aucun Leader ou Champion dans cette bande.'}</div>`;
  const appliedHtml=applied?`<div class="pba-card"><h4>${en?'Applied':'Appliqué'}</h4><div class="pba-ledger">${(p.actionsLog||[]).length?(p.actionsLog||[]).map(t=>`<div><span>${esc(t)}</span></div>`).join(''):`<div><span>${en?'No action taken.':'Aucune action effectuée.'}</span></div>`}</div><button type="button" class="button secondary pba-apply" onclick="pbaNewRound()">${en?'New round of actions (next session)':'Nouvelle série d’actions (session suivante)'}</button><small class="pba-hint">${en?'Changes already applied stay on the roster. Reset at the top restarts the whole post-battle sequence.':'Les changements déjà appliqués restent sur le roster. Réinitialiser en haut relance toute la séquence post-bataille.'}</small></div>`:'';
  return `<div class="postbattle-shell"><div class="pba-grid"><section class="sheet-block postbattle-panel"><div class="sheet-block-head prominent-section"><div><h4>${en?'Who acts':'Qui agit'}</h4><small>${en?'Each Leader or Champion makes one action, in any order. Not if In Recovery or Captured.':'Chaque Leader ou Champion effectue une action, dans l’ordre voulu. Pas s’il est en Recovery ou Captured.'}</small></div><span class="pba-badge lead">${used} / ${elig.length}</span></div>${actorsHtml}</section>
  <aside class="pba-side">
    <div class="pba-card"><h4>${en?'Treasury after actions':'Trésor après actions'}</h4><div class="pba-ledger">${applied?`<div class="tot"><span>${en?'Treasury':'Trésor'}</span><span class="pba-mono">${Number(r.gold||0)} GC</span></div>`:`<div><span>${en?'Treasury now':'Trésor actuel'}</span><span class="pba-mono">${Number(r.gold||0)} GC</span></div>${sales?`<div><span>${en?'Captives sold':'Captifs vendus'}</span><span class="pba-mono pba-plus">+${sales} GC</span></div>`:''}${paid?`<div><span>${en?'Physician fees':'Frais de Physician'}</span><span class="pba-mono pba-minus">−${paid} GC</span></div>`:''}${pending?`<div><span>${en?'Fee rolled, not paid yet':'Coût lancé, pas encore payé'}</span><span class="pba-mono pba-minus">(−${pending} GC)</span></div>`:''}<div class="tot"><span>${en?'After actions':'Après actions'}</span><span class="pba-mono">${Number(r.gold||0)+sales-paid} GC</span></div>`}</div></div>
    <div class="pba-card"><h4>Seek Rare Equipment</h4><div class="pba-avail"><b class="pba-mono">${(v=>(v>=0?'+':'')+v)(applied&&Number.isFinite(p.rareBonus)?p.rareBonus:bonus.total)}</b><small>${en?'added to the 2D6 Availability roll at the Trading Post':'ajouté au jet de 2D6 de disponibilité au Trading Post'}</small></div><div class="pba-ledger pba-mods"><div><span>${en?'Leader trading':'Leader au Trading Post'}</span><span class="pba-mono">+${bonus.lead}</span></div><div><span>${en?`Champions trading (${bonus.champs})`:`Champions au Trading Post (${bonus.champs})`}</span><span class="pba-mono">+${bonus.champs}</span></div><div><span>${en?`Reputation ${Number(r.reputation||0)} (per full 10)`:`Réputation ${Number(r.reputation||0)} (par tranche de 10)`}</span><span class="pba-mono">+${bonus.rep}</span></div>${bonus.mod?`<div><span>${esc(bonus.modLabel)}</span><span class="pba-mono">${bonus.mod>0?'+':''}${bonus.mod}</span></div>`:''}</div></div>
    ${!applied?`<div class="pba-card"><h4>${en?'Roster changes':'Changements du roster'}</h4><div class="pba-ledger">${changes.length?changes.join(''):`<div><span class="pba-hint">${en?'Nothing yet.':'Rien pour l’instant.'}</span></div>`}${unescorted.map(c=>`<div><span>${esc(c.name)} ${en?'(no escort)':'(sans escorte)'}</span><span class="pba-minus">${en?'Still critical':'Toujours critique'}</span></div>`).join('')}</div>${unescorted.length?`<small class="pba-hint">${en?'A Critical Injury is fatal unless a Physician saves the warrior. Treat them here or from their fighter sheet.':'Une Critical Injury est mortelle sauf si un Physician sauve le combattant. Soigne-le ici ou depuis sa fiche.'}</small>`:''}</div>
    <button type="button" class="button primary pba-apply" ${open.length?'disabled':''} onclick="applyPostBattleActions()">${en?'Apply to roster':'Appliquer au roster'}</button><small class="pba-hint">${open.length?(en?`Finish the Medical Escort for ${esc(open.map(x=>x.name).join(', '))} first.`:`Termine d’abord le Medical Escort de ${esc(open.map(x=>x.name).join(', '))}.`):(en?'Unused actions are simply skipped.':'Les actions non utilisées sont simplement ignorées.')}</small>`:appliedHtml}
  </aside></div></div>`;
}
// ===== Step 5: Trading Post (V-TRADINGPOST) =====
// A visit has one Seek Rare Equipment roll (2D6 + the Step 4 bonus) that
// sets the Availability level, then two separate shops: the warband's own
// Band List (everything, band prices) and a Trading Post (Common items, plus
// Rare items up to Availability). Bought items go to the Stash.
//
// Built for campaign Trading Posts later: every shop read and every
// purchase goes through tradingPost*() below. Today there is a single
// unlimited post. A campaign can register city posts in TRADING_POSTS with
// a `stock` map (normalized item name -> count shared by every warband);
// tradingPostStock/Take/Give already respect it, and the UI already shows
// "x left" and a post picker once there is more than one post.
const TRADING_POSTS=[{id:'default',en:'Trading Post',fr:'Trading Post',stock:null}];
let tpMobileShop='band',postBattleStep5Open=false,tpBandCat='all',tpPostCat='all',tpBandSearch='',tpPostSearch='',tpShowLocked=true;
function tradingPostList(){return TRADING_POSTS}
function tradingPostById(id){return tradingPostList().find(t=>t.id===id)||tradingPostList()[0]}
function tradingPostStock(post,name){if(!post?.stock)return null;const n=post.stock[normName(name)];return Number.isFinite(n)?n:0}
function tradingPostTake(post,name){if(!post?.stock)return true;const k=normName(name);if(!(post.stock[k]>0))return false;post.stock[k]--;return true}
function tradingPostGive(post,name){if(!post?.stock)return;const k=normName(name);post.stock[k]=(post.stock[k]||0)+1}
function tradingRarity(w){const raw=String(w?.availability||w?.rarity||'');const m=raw.match(/rare\s*(\d+)/i);if(m)return Number(m[1]);return 0}
function tradingData(r){const p=ensurePostBattleData(r);if(!p.trading||typeof p.trading!=='object')p.trading={};const t=p.trading;if(!t.postId)t.postId=tradingPostList()[0].id;if(!Array.isArray(t.purchases))t.purchases=[];return t}
function tradingSeekBonus(r){const p=ensurePostBattleData(r);return p.actionsApplied&&Number.isFinite(p.rareBonus)?p.rareBonus:pbaRareBonus(r).total}
function tradingAvailability(r){const t=tradingData(r);if(Number.isFinite(t.availability))return t.availability;return null}
function tradingCustoms(f){const customs=allCustomEquipmentList();const embedded=(f?.equipment||[]).filter(e=>e&&typeof e==='object'&&isCustomEquipment(e));embedded.forEach(e=>{if(!customs.some(c=>normName(c.name)===normName(e.name)))customs.push(e)});return customs}
// The warband's own Warband Type Equipment list: the faction's equipment
// names plus the catalog's per-faction band flags. Only a warband with
// neither (e.g. a custom warband) falls back to what its fighter profiles
// can access.
function tradingBandItems(r){const f=faction(r);if(!f)return [];const names=new Set((f.equipment||[]).map(e=>normName(typeof e==='string'?e:e?.name)).filter(Boolean));const hasList=names.size>0||D.weapons.some(w=>w.bandByFaction&&f.id in w.bandByFaction);const ws=f.warriors||[];if(String(f.id).startsWith('custom-warband-')){const acc=new Set();ws.forEach(x=>(Array.isArray(x.equipmentAccess)?x.equipmentAccess:[]).forEach(n=>acc.add(normName(n))));const own=(f.equipment||[]).filter(e=>e&&typeof e==='object');const ownNames=new Set(own.map(e=>normName(e.name)));return [...D.weapons.filter(w=>!w.hidden&&acc.has(normName(w.name))&&!ownNames.has(normName(w.name))),...own.filter(e=>acc.has(normName(e.name))||!ws.some(x=>Array.isArray(x.equipmentAccess)))].map(w=>({w,price:Number(equipmentPrice(w,f,'band')||0),rarity:tradingRarity(w)}))}const allowed=w=>hasList?(names.has(normName(w.name))||w.bandByFaction?.[f.id]===true||(isCustomEquipment(w)&&customEquipmentForFaction(w,f.id))):ws.some(x=>{try{return warriorBandAllowed(w,x)}catch(e){return false}});const customs=tradingCustoms(f).filter(w=>customEquipmentForFaction(w,f.id)&&allowed(w));const customNames=new Set(customs.map(w=>normName(w.name)));return [...D.weapons.filter(w=>!w.hidden&&w.name!=='Natural Weapons'&&w.name!=='Unarmed'&&!customNames.has(normName(w.name))&&allowed(w)),...customs].map(w=>({w,price:Number(equipmentPrice(w,f,'band')||0),rarity:tradingRarity(w)}))}
function tradingPostItems(r,post){const f=faction(r);const customs=tradingCustoms(f).filter(w=>w.market);const names=new Set(customs.map(w=>normName(w.name)));let list=[...D.weapons.filter(w=>!w.hidden&&w.market!==false&&!names.has(normName(w.name))),...customs];if(post?.stock)list=list.filter(w=>normName(w.name) in post.stock);return list.map(w=>({w,price:Number(equipmentPrice(w,f||{},'market')||0),rarity:tradingRarity(w)}))}
function tradingLockReason(r,it){if(!it.rarity)return '';const a=tradingAvailability(r),en=siteLanguage==='en';if(a==null)return en?'Roll rarity first':'Lance la rareté d’abord';if(it.rarity>a)return en?`Needs Availability ${it.rarity}`:`Disponibilité ${it.rarity} requise`;return ''}
function tradingChange(fn){const r=activeRoster();if(!r)return;postBattleStep5Open=true;const out=fn(r,tradingData(r));if(out===false)return;save(true);render('builder')}
function rollTradingRarity(manual){tradingChange((r,t)=>{const again=Number.isFinite(t.availability);const bonus=tradingSeekBonus(r);if(manual!=null){const v=Math.floor(Number(manual));if(!(v>=2&&v<=12)){toast(siteLanguage==='en'?'Enter a 2D6 total between 2 and 12':'Indique un total de 2D6 entre 2 et 12');return false}t.dice=null;t.manual=v;t.bonus=bonus;t.availability=v+bonus}else{t.dice=[postBattleRoll(),postBattleRoll()];t.manual=null;t.bonus=bonus;t.availability=t.dice[0]+t.dice[1]+bonus}logHistory(r,'equipment',siteLanguage==='en'?`Seek Rare Equipment${again?' (changed)':''}: Availability ${t.availability}`:`Seek Rare Equipment${again?' (modifié)':''} : disponibilité ${t.availability}`)})}
// Next session: a fresh Trading Post visit (new rarity roll, empty purchase
// list). Items already bought stay in the Stash.
function newTradingVisit(){tradingChange((r,t)=>{t.availability=null;t.dice=null;t.manual=null;t.bonus=null;t.purchases=[];logHistory(r,'equipment',siteLanguage==='en'?'New Trading Post visit':'Nouvelle visite au Trading Post')})}
function setTradingPost(id){tradingChange((r,t)=>{if(t.purchases.length){toast(siteLanguage==='en'?'Undo this visit’s purchases before changing Trading Post':'Annule les achats de cette visite avant de changer de Trading Post');return false}t.postId=tradingPostById(id).id})}
function buyTradingItem(src,name){tradingChange((r,t)=>{const en=siteLanguage==='en';const post=tradingPostById(t.postId);const list=src==='band'?tradingBandItems(r):tradingPostItems(r,post);const it=list.find(i=>normName(i.w.name)===normName(name));if(!it)return false;if(src!=='band'&&tradingLockReason(r,it)){toast(tradingLockReason(r,it));return false}if(Number(r.gold||0)<it.price){toast(en?'Not enough gold':'Pas assez d’or');return false}if(src!=='band'&&!tradingPostTake(post,it.w.name)){toast(en?'Sold out':'Épuisé');return false}const w=it.w;const reserveId=crypto.randomUUID();r.reserve=Array.isArray(r.reserve)?r.reserve:[];r.reserve.push({reserveId,stashId:crypto.randomUUID(),name:w.name,paid:it.price,value:it.price,price:it.price,category:w.category,subcategory:w.subcategory||w.category,rarity:w.rarity||'',availability:w.availability||w.rarity||'—',profile:w.profile||null,profile2:w.profile2||null,traits:w.traits||[],customEquipmentId:w.customEquipmentId||null,weaponSlotCost:weaponSlots(w),boughtFrom:src==='band'?'band':post.id});r.gold=Number(r.gold||0)-it.price;t.purchases.push({id:crypto.randomUUID(),reserveId,name:w.name,price:it.price,src,postId:post.id});logHistory(r,'equipment',en?`<b>${esc(w.name)}</b> bought (${src==='band'?'Band List':esc(post.en)}) for ${it.price} GC, added to the Stash`:`<b>${esc(w.name)}</b> acheté (${src==='band'?'Band List':esc(post.fr)}) pour ${it.price} GC, ajouté à la réserve`);toast(en?`${w.name} bought · −${it.price} GC`:`${w.name} acheté · −${it.price} GC`)})}
function undoTradingPurchase(id){tradingChange((r,t)=>{const en=siteLanguage==='en';const pu=t.purchases.find(x=>x.id===id);if(!pu)return false;const idx=(r.reserve||[]).findIndex(e=>e.reserveId===pu.reserveId);if(idx<0){toast(en?'This item already left the Stash: it can’t be undone':'Cet objet a déjà quitté la réserve : impossible d’annuler');return false}r.reserve.splice(idx,1);r.gold=Number(r.gold||0)+Number(pu.price||0);if(pu.src!=='band')tradingPostGive(tradingPostById(pu.postId),pu.name);t.purchases=t.purchases.filter(x=>x.id!==id);logHistory(r,'equipment',en?`Purchase undone: <b>${esc(pu.name)}</b> (+${pu.price} GC)`:`Achat annulé : <b>${esc(pu.name)}</b> (+${pu.price} GC)`)})}
function setTradingCat(which,cat){if(which==='band')tpBandCat=cat;else tpPostCat=cat;postBattleStep5Open=true;render('builder')}
function setTradingMobileShop(v){tpMobileShop=v==='post'?'post':'band';postBattleStep5Open=true;render('builder')}
function setTradingShowLocked(v){tpShowLocked=!!v;postBattleStep5Open=true;render('builder')}
function filterTradingList(which,q){if(which==='band')tpBandSearch=q;else tpPostSearch=q;const term=normName(q||'');document.querySelectorAll(`#tp-list-${which} .tp-item`).forEach(el=>{el.hidden=!!term&&!normName(el.dataset.name||'').includes(term)})}
function tradingItemsMarkup(r,which,items){
  const en=siteLanguage==='en';const t=tradingData(r),post=tradingPostById(t.postId);const cat=which==='band'?tpBandCat:tpPostCat,q=normName(which==='band'?tpBandSearch:tpPostSearch);
  let list=items.filter(it=>cat==='all'||canonEquipmentCategory(equipmentCategory(it.w))===cat);
  if(which==='post'&&!tpShowLocked)list=list.filter(it=>!tradingLockReason(r,it));
  list.sort((a,b)=>a.rarity-b.rarity||a.w.name.localeCompare(b.w.name));
  if(!list.length)return `<div class="tp-empty">${en?'No item here.':'Aucun objet ici.'}</div>`;
  return list.map(it=>{const lock=which==='post'?tradingLockReason(r,it):'';const stock=which==='post'?tradingPostStock(post,it.w.name):null;const out=stock!=null&&stock<=0;const poor=it.price>Number(r.gold||0);const dis=!!lock||out||poor;
    return `<div class="tp-item${lock||out?' locked':''}" data-name="${esc(it.w.name)}" ${q&&!normName(it.w.name).includes(q)?'hidden':''}><div class="tp-nm"><b>${refLink('equipment',it.w.name,it.w.name)}${it.rarity?`<span class="tp-tag rare">Rare ${it.rarity}</span>`:`<span class="tp-tag">Common</span>`}</b><small>${esc(tradingCatLabel(canonEquipmentCategory(equipmentCategory(it.w))))}${stock!=null?` · ${out?(en?'sold out':'épuisé'):(en?`${stock} left`:`${stock} restant${stock>1?'s':''}`)}`:''}${lock?` · <span class="tp-why">${esc(lock)}</span>`:''}</small></div><span class="tp-price">${it.price} GC</span><button type="button" class="button ${dis?'secondary':'primary'} tp-buy" ${dis?'disabled':''} ${poor&&!lock&&!out?`title="${en?'Not enough gold':'Pas assez d’or'}"`:''} onclick="buyTradingItem('${which}','${esc(it.w.name).replace(/'/g,"\\'")}')">${en?'Buy':'Acheter'}</button></div>`}).join('');
}
function tradingCatLabel(c){if(siteLanguage!=='en')return c;return EQUIPMENT_SECTIONS.find(s=>s.cat===c)?.label||c}
function tradingChipsMarkup(which,items){const cur=which==='band'?tpBandCat:tpPostCat;const cats=EQUIPMENT_SECTIONS.map(s=>s.cat).filter(c=>items.some(it=>canonEquipmentCategory(equipmentCategory(it.w))===c));const en=siteLanguage==='en';const label=c=>{const sec=EQUIPMENT_SECTIONS.find(s=>s.cat===c);return en?(sec?.label||c):c};return `<div class="tp-chips">${['all',...cats].map(c=>`<button type="button" class="tp-chip${cur===c?' on':''}" onclick="setTradingCat('${which}','${esc(c).replace(/'/g,"\\'")}')">${c==='all'?(en?'All':'Tout'):esc(label(c))}</button>`).join('')}</div>`}
function tradingPostView(r,f){
  const en=siteLanguage==='en';const t=tradingData(r),post=tradingPostById(t.postId),a=tradingAvailability(r),bonus=Number.isFinite(t.bonus)?t.bonus:tradingSeekBonus(r);
  const b=pbaRareBonus(r);const p=ensurePostBattleData(r);
  const band=tradingBandItems(r),market=tradingPostItems(r,post);const openCount=market.filter(it=>!tradingLockReason(r,it)).length;
  const spent=t.purchases.reduce((n,x)=>n+Number(x.price||0),0);
  const dice=t.dice?`<span class="tp-die">${t.dice[0]}</span><span>+</span><span class="tp-die">${t.dice[1]}</span>`:t.manual!=null?`<span class="tp-die">${t.manual}</span>`:`<span class="tp-die tp-die-blank">?</span><span>+</span><span class="tp-die tp-die-blank">?</span>`;
  const posts=tradingPostList();
  const postPicker=posts.length>1?`<label class="tp-post-pick"><span>${en?'Trading Post':'Trading Post'}</span><select onchange="setTradingPost(this.value)">${posts.map(x=>`<option value="${esc(x.id)}" ${x.id===post.id?'selected':''}>${esc(en?x.en:x.fr)}</option>`).join('')}</select></label>`:'';
  return `<div class="postbattle-shell tp-shell">
  <section class="tp-roll"><div><div class="eyebrow">SEEK RARE EQUIPMENT</div><h4>${en?'Rarity roll':'Jet de rareté'}</h4><p>${en?'Roll 2D6 and add the Seek Rare bonus from Step 4. Rare items with a Rarity up to the result can be bought at the Trading Post.':'Lance 2D6 et ajoute le bonus Seek Rare de l’étape 4. Les objets Rare dont la rareté est inférieure ou égale au résultat peuvent être achetés au Trading Post.'}</p>
    <div class="tp-eq">${dice}<span>+</span><span class="tp-bonus">${bonus>=0?'+':''}${bonus} Seek Rare</span><span>=</span><b>${a??'?'}</b></div>
    <div class="tp-roll-actions"><button type="button" class="button ${a==null?'primary':'secondary'}" onclick="rollTradingRarity()">${a==null?(en?`Roll rarity (2D6 + ${bonus})`:`Lancer la rareté (2D6 + ${bonus})`):(en?'↻ Reroll':'↻ Relancer')}</button><span class="tp-manual"><label for="tpManual">${a==null?(en?'or enter your dice total':'ou saisis ton total de dés'):(en?'or correct the 2D6 total':'ou corrige le total de 2D6')}</label><input id="tpManual" type="number" min="2" max="12" placeholder="2–12" value="${t.manual??(t.dice?t.dice[0]+t.dice[1]:'')}"><button type="button" class="button secondary" onclick="rollTradingRarity(document.getElementById('tpManual').value)">${en?'Use':'Utiliser'}</button></span>${a!=null?`<button type="button" class="button secondary" onclick="newTradingVisit()">${en?'New visit (next session)':'Nouvelle visite (session suivante)'}</button>`:''}</div>
  </div><div class="tp-avail"><small>${en?'Availability level':'Niveau de disponibilité'}</small><span class="tp-big">${a??'—'}</span><small>${a!=null?(en?`Rare items up to Rarity ${a}, plus every Common item.`:`Objets Rare jusqu’à ${a}, plus tous les objets Common.`):(en?'Only Common items at the Trading Post until you roll.':'Seulement les objets Common au Trading Post avant le jet.')}</small><div class="tp-mods"><div><span>${en?'Leader trading':'Leader au Trading Post'}</span><span>+${b.lead}</span></div><div><span>${en?`Champions trading (${b.champs})`:`Champions au Trading Post (${b.champs})`}</span><span>+${b.champs}</span></div><div><span>${en?`Reputation ${Number(r.reputation||0)} (per full 10)`:`Réputation ${Number(r.reputation||0)} (par tranche de 10)`}</span><span>+${b.rep}</span></div>${b.mod?`<div><span>${esc(b.modLabel)}</span><span>${b.mod>0?'+':''}${b.mod}</span></div>`:''}${!p.actionsApplied?`<small>${en?'Step 4 not applied yet: bonus from current choices.':'Étape 4 pas encore appliquée : bonus selon les choix actuels.'}</small>`:''}</div></div></section>
  <div class="tp-switch" role="tablist" aria-label="${en?'Shop':'Boutique'}"><button type="button" role="tab" aria-selected="${tpMobileShop==='band'}" class="tp-switch-btn${tpMobileShop==='band'?' on':''}" onclick="setTradingMobileShop('band')">Band List <small>${band.length}</small></button><button type="button" role="tab" aria-selected="${tpMobileShop==='post'}" class="tp-switch-btn${tpMobileShop==='post'?' on':''}" onclick="setTradingMobileShop('post')">${esc(en?post.en:post.fr)} <small>${openCount}/${market.length}</small></button></div>
  <div class="tp-shops show-${tpMobileShop}">
    <section class="tp-shop tp-shop-band"><div class="tp-shop-h"><div class="tp-ttl"><h4>Band List</h4><small>${band.length} ${en?'items':'objets'}</small></div><small>${en?'Your warband’s equipment list, at its own prices. Everything here can be bought, whatever its rarity.':'La liste d’équipement de ta bande, à ses propres prix. Tout peut être acheté, quelle que soit la rareté.'}</small>${tradingChipsMarkup('band',band)}<input type="search" class="search" value="${esc(tpBandSearch)}" placeholder="${en?'Search the band list…':'Rechercher dans la band list…'}" oninput="filterTradingList('band',this.value)"></div><div class="tp-list" id="tp-list-band">${tradingItemsMarkup(r,'band',band)}</div></section>
    <section class="tp-shop tp-shop-post"><div class="tp-shop-h"><div class="tp-ttl"><h4>${esc(en?post.en:post.fr)}</h4><small>${openCount} / ${market.length} ${en?'available':'disponibles'}</small></div>${postPicker}<small>${en?'Common items always. Rare items only up to your Availability level.':'Objets Common toujours. Objets Rare seulement jusqu’à ton niveau de disponibilité.'}</small>${tradingChipsMarkup('post',market)}<div class="tp-tools"><input type="search" class="search" value="${esc(tpPostSearch)}" placeholder="${en?'Search the Trading Post…':'Rechercher au Trading Post…'}" oninput="filterTradingList('post',this.value)"><label class="tp-toggle"><input type="checkbox" ${tpShowLocked?'checked':''} onchange="setTradingShowLocked(this.checked)"> ${en?'Show locked rare items':'Afficher les objets Rare verrouillés'}</label></div></div><div class="tp-list" id="tp-list-post">${tradingItemsMarkup(r,'post',market)}</div></section>
    <aside class="tp-cart"><h4>${en?'This visit':'Cette visite'}</h4><div class="pba-ledger"><div><span>${en?'Spent':'Dépensé'}</span><span class="pba-mono pba-minus">${spent?`−${spent}`:'0'} GC</span></div><div class="tot"><span>${en?'Treasury':'Trésor'}</span><span class="pba-mono">${Number(r.gold||0)} GC</span></div></div><div class="tp-bought">${t.purchases.length?t.purchases.map(x=>`<div><span>${esc(x.name)} <small>${x.src==='band'?'Band List':esc(en?tradingPostById(x.postId).en:tradingPostById(x.postId).fr)}</small></span><span class="pba-mono">${x.price} GC <button type="button" title="${en?'Undo purchase':'Annuler l’achat'}" aria-label="${en?'Undo':'Annuler'} ${esc(x.name)}" onclick="undoTradingPurchase('${esc(x.id)}')">✕</button></span></div>`).join(''):`<div class="tp-empty">${en?'Nothing bought yet.':'Rien acheté pour l’instant.'}</div>`}</div><small class="pba-hint">${en?'Bought items go to the Stash, where you hand them out to fighters. ✕ undoes a purchase while the item is still in the Stash.':'Les objets achetés vont dans la réserve, d’où tu les distribues aux combattants. ✕ annule un achat tant que l’objet est dans la réserve.'}</small></aside>
  </div></div>`;
}
function postBattleView(r,f){const en=siteLanguage==='en';ensurePostBattleData(r);return `<div class="postbattle-accordion">${eyeOfTheGodsStep(r)}<details class="postbattle-step" open><summary><span><b>STEP 3</b> Income / Exploration <small>${en?'Dice, wyrdstone and exploration':'Dés, wyrdstone et exploration'}</small></span><i>⌄</i></summary><div class="postbattle-step-body">${postBattleIncomeView(r,f)}</div></details><details class="postbattle-step"${postBattleStep4Open?' open':''} ontoggle="postBattleStep4Open=this.open"><summary><span><b>STEP 4</b> Post-battle action <small>${en?'Leader and Champion actions':'Actions des Leaders et Champions'}</small></span><i>⌄</i></summary><div class="postbattle-step-body">${postBattleActionsView(r,f)}</div></details><details class="postbattle-step"${postBattleStep5Open?' open':''} ontoggle="postBattleStep5Open=this.open"><summary><span><b>STEP 5</b> Trading Post <small>${en?'Rarity roll, Band List and Trading Post':'Jet de rareté, Band List et Trading Post'}</small></span><i>⌄</i></summary><div class="postbattle-step-body">${tradingPostView(r,f)}</div></details></div>`}
function reserveView(r,f){const en=siteLanguage==='en';const reserve=Array.isArray(r.reserve)?r.reserve:[];const total=reserve.reduce((n,e)=>n+Number(e.value??e.price??0),0);return `<div class="roster-toolbar"><div><div class="eyebrow">${en?'RESERVE / STORED EQUIPMENT':'RESERVE / ÉQUIPEMENT STOCKÉ'}</div><h3>${en?'Warband stash':'Réserve de la bande'}</h3><p>${en?'Equipment bought or recovered, not assigned to a fighter. Its value still counts toward the warband’s value.':'Équipement acheté ou récupéré, non attribué à un combattant. La valeur reste comptée dans la valeur de bande.'}</p></div>${reserve.length?`<span class="reserve-summary-badge">${reserve.length} ${en?`item${reserve.length!==1?'s':''}`:`objet${reserve.length!==1?'s':''}`} · <span class="v">${total} GC</span></span>`:''}</div>${reserve.length?`<div class="reserve-list">${reserve.map((e,i)=>reserveItemRow(e,i)).join('')}</div>`:`<div class="empty large"><strong>${en?'Stash is empty.':'Réserve vide.'}</strong><span>${en?'Use the small ▣ button on a fighter’s equipment to put an item here.':'Utilise le petit bouton ▣ sur l\'équipement d\'un combattant pour placer un objet ici.'}</span></div>`}${captivesSectionMarkup(r)}`}
// V-CAPTIVES: captives this warband holds, entered by hand for now (a
// cross-player campaign version will come later). Sold through the Step 4
// "Sell Captive" post-battle action.
function captivesSectionMarkup(r){
  const en=siteLanguage==='en';const caps=rosterCaptives(r);
  const rows=caps.map(c=>`<div class="reserve-row"><div class="reserve-item-main"><div><strong>⛓ ${esc(c.name)}</strong><small>${esc(c.warband||(en?'Unknown warband':'Bande inconnue'))} · ${c.rescueChance?(en?'can be sold':'peut être vendu'):(en?'waiting for a rescue chance':'en attente d’une chance de sauvetage')}</small></div><strong>${Number(c.value||0)} GC</strong></div><div class="reserve-actions"><button type="button" class="equipment-action reserve-action-labeled" title="${en?'Their warband has had a chance to rescue them':'Leur bande a eu une chance de les secourir'}" onclick="toggleCaptiveRescueChance('${esc(c.id)}')">${c.rescueChance?'✓':'○'} ${en?'Rescue chance given':'Chance de sauvetage donnée'}</button><button type="button" class="equipment-action remove" title="${en?'Delete':'Supprimer'}" aria-label="${en?'Delete':'Supprimer'} ${esc(c.name)}" onclick="removeCaptive('${esc(c.id)}')">🗑</button></div></div>`).join('');
  return `<div class="roster-toolbar captives-toolbar"><div><div class="eyebrow">${en?'STASH / CAPTIVES':'RÉSERVE / CAPTIFS'}</div><h3>${en?'Captives':'Captifs'}</h3><p>${en?'Enemy warriors held by this warband. Once their warband has had a chance to rescue them, a Leader or Champion can sell them in Step 4 of the post-battle sequence for half their value.':'Combattants ennemis détenus par la bande. Une fois que leur bande a eu une chance de les secourir, un Leader ou Champion peut les vendre à l’étape 4 de la post-bataille pour la moitié de leur valeur.'}</p></div></div>${rows?`<div class="reserve-list">${rows}</div>`:`<div class="empty compact">${en?'No captive held.':'Aucun captif détenu.'}</div>`}<div class="captive-add"><input id="captiveName" class="search" placeholder="${en?'Captive name':'Nom du captif'}"><input id="captiveWarband" class="search" placeholder="${en?'Their warband':'Sa bande'}"><input id="captiveValue" class="search" type="number" min="0" step="5" placeholder="${en?'Value (GC)':'Valeur (GC)'}"><label class="captive-check"><input id="captiveRescue" type="checkbox"> ${en?'Rescue chance given':'Chance de sauvetage donnée'}</label><button type="button" class="button secondary" onclick="addCaptive()">＋ ${en?'Add captive':'Ajouter un captif'}</button></div>`;
}
function addCaptive(){const en=siteLanguage==='en';const r=activeRoster();if(!r)return;const name=($('#captiveName')?.value||'').trim();if(!name){toast(en?'Give the captive a name':'Donne un nom au captif');return}const value=Math.max(0,Math.floor(Number($('#captiveValue')?.value||0)));rosterCaptives(r).push({id:crypto.randomUUID(),name,warband:($('#captiveWarband')?.value||'').trim(),value,rescueChance:!!$('#captiveRescue')?.checked});logHistory(r,'settings',en?`Captive added: ${name}`:`Captif ajouté : ${name}`);save(true);render('builder')}
function removeCaptive(id){const r=activeRoster();if(!r)return;const c=rosterCaptives(r).find(x=>x.id===id);r.captives=rosterCaptives(r).filter(x=>x.id!==id);const plan=r.postBattle?.actions||{};Object.values(plan).forEach(a=>{if(a?.captives)a.captives=a.captives.filter(x=>x!==id)});if(c)logHistory(r,'settings',(siteLanguage==='en'?'Captive removed: ':'Captif retiré : ')+c.name);save(true);render('builder')}
function toggleCaptiveRescueChance(id){const r=activeRoster();if(!r)return;const c=rosterCaptives(r).find(x=>x.id===id);if(!c)return;c.rescueChance=!c.rescueChance;if(!c.rescueChance){Object.values(r.postBattle?.actions||{}).forEach(a=>{if(a?.captives)a.captives=a.captives.filter(x=>x!==id)})}save(true);render('builder')}
function reserveItemRow(e,i){const en=siteLanguage==='en';return `<div class="reserve-row"><div class="reserve-item-main"><div><strong>${refLink('equipment',e.name)}</strong><small>${esc(e.category||(en?'Equipment':'Équipement'))}</small></div><strong>${Number(e.value??e.price??0)} GC</strong></div><div class="reserve-actions"><button type="button" class="equipment-action reserve-action-labeled" title="${en?'Transfer to a fighter':'Transférer à un combattant'}" aria-label="${en?'Transfer':'Transférer'} ${esc(e.name)}" onclick="transferReserveEquipment(${i})">⇄ ${en?'Transfer':'Transférer'}</button><button type="button" class="equipment-action sell reserve-action-labeled" title="${en?'Sell':'Vendre'}" aria-label="${en?'Sell':'Vendre'} ${esc(e.name)}" onclick="sellReserveEquipment(${i})">⤓ ${en?'Sell':'Vendre'}</button><button type="button" class="equipment-action remove" title="${en?'Delete':'Supprimer'}" aria-label="${en?'Delete':'Supprimer'} ${esc(e.name)}" onclick="removeReserveEquipment(${i})">🗑</button></div></div>`}
// Groups a roster's fighters for display: first by role, in
// WARBAND_ROLE_ORDER (Leader → Champion → Raw Recruit → Henchman → Animal,
// anything else after), then — inside each role — by unit type (sourceName,
// the stable catalog name, so a renamed fighter still clusters with its
// kind), each unit-type cluster kept in the order its fighters first
// appear in r.fighters. A newly recruited fighter is always pushed to the
// end of r.fighters, so it naturally lands at the end of its own
// unit-type cluster — "a new Ghoul joins below the lowest existing
// Ghoul" — without this ever touching r.fighters itself (that array stays
// the single source of truth for drag-reorder and everything else; this
// only decides DISPLAY order). Returns [{role, indices:[original r.fighters
// index, …]}, …] for each role that has at least one fighter.
function rosterGroupedIndices(r){
  const byRole={};
  const roleFirstSeen=[];
  (r.fighters||[]).forEach((x,i)=>{
    const role=x.type||'Henchman';
    if(!byRole[role]){byRole[role]=[];roleFirstSeen.push(role);}
    byRole[role].push(i);
  });
  const roleKeys=[...WARBAND_ROLE_ORDER.filter(rl=>byRole[rl]),...roleFirstSeen.filter(rl=>!WARBAND_ROLE_ORDER.includes(rl))];
  return roleKeys.map(role=>{
    const idxs=byRole[role];
    const nameOrder=[],nameMap={};
    idxs.forEach(i=>{
      const key=normName(r.fighters[i].sourceName||r.fighters[i].name);
      if(!nameMap[key]){nameMap[key]=[];nameOrder.push(key);}
      nameMap[key].push(i);
    });
    return {role,indices:nameOrder.flatMap(k=>nameMap[k])};
  });
}
function rosterRoleSlug(role){return String(role||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');}
function rosterRoleLabel(role,en){
  // The role strings themselves (Leader/Champion/Raw Recruit/Henchman) are
  // shown verbatim everywhere else in the app (role badges, etc.) rather
  // than translated, so the section titles follow the same convention —
  // except Animal, which doesn't exist as a real type yet (see
  // WARBAND_ROLE_ORDER) and so has no English/French split to worry about.
  return role;
}
function rosterView(r,f){
  const en=siteLanguage==='en';
  const groups=rosterGroupedIndices(r);
  return `<div class="roster-toolbar"><div><div class="eyebrow">ACTIVE ROSTER</div><h3>${en?'Warband fighters':'Guerriers de la bande'}</h3><p>${en?'Click a fighter to open their full sheet. Changes are saved automatically. Drag the cards to set their order.':'Clique sur un combattant pour ouvrir sa fiche complète. Les modifications sont enregistrées automatiquement. Glisse les cartes pour définir leur ordre.'}</p></div><div class="roster-toolbar-actions">${r.fighters.length>1?`<select class="roster-jump-select" aria-label="${en?'Jump to a fighter':'Aller à un combattant'}" onchange="jumpToFighterCard(this.value);this.value=''"><option value="">↕ ${en?'Jump to…':'Aller à…'}</option>${r.fighters.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select>`:''}<button class="button primary" onclick="setGangTab('recruit')">＋ ${en?'Recruit':'Recruter'}</button></div></div>${groups.length>1?`<div class="roster-category-nav">${groups.map(g=>`<button type="button" class="button secondary" style="padding:5px 12px;font-size:11px" onclick="jumpToRosterSection('${esc(g.role)}')">${esc(rosterRoleLabel(g.role,en))} <span class="muted">${g.indices.length}</span></button>`).join('')}</div>`:''}${groups.length?`<div class="roster-sections">${groups.map(g=>`<div class="roster-section" id="roster-section-${esc(rosterRoleSlug(g.role))}"><div class="section-label">${esc(rosterRoleLabel(g.role,en).toUpperCase())} <span>${g.indices.length}</span></div><div class="fighter-list">${g.indices.map(i=>ownedFighterCard(r.fighters[i],i,f)).join('')}</div></div>`).join('')}</div>`:`<div class="empty large"><strong>${en?'Your warband is empty.':'Ta bande est vide.'}</strong><span>${en?'Use the Recruitment tab to pick your first fighters.':'Utilise l’onglet Recrutement pour choisir tes premiers combattants.'}</span><button class="button primary" onclick="setGangTab('recruit')">${en?'Open recruitment':'Ouvrir le recrutement'}</button></div>`}`;
}
function jumpToFighterCard(i){if(i===''||i==null)return;const el=document.querySelector(`.fighter-list [data-fighter-index="${CSS.escape(String(i))}"]`);if(!el)return;el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('fighter-card-jump-highlight');setTimeout(()=>el.classList.remove('fighter-card-jump-highlight'),1400)}
function jumpToRosterSection(role){const el=document.getElementById(`roster-section-${rosterRoleSlug(role)}`);if(!el)return;el.scrollIntoView({behavior:'smooth',block:'start'});el.classList.add('fighter-card-jump-highlight');setTimeout(()=>el.classList.remove('fighter-card-jump-highlight'),1400)}
function championLimitForRoster(r){return 2+Math.floor(Math.max(0,Number(r?.reputation||0))/10)}
// V-WARBEASTS: per the book's own War Beasts special rule ("activated and
// fight in exactly the same way as a henchman of your warband" / "count
// towards the maximum number of warriors allowed"), an Animal-type fighter
// counts as a Henchman for warband-composition purposes — the Henchman
// ratio requirement below — even though it still gets its own display
// section on the roster page (that's a presentation grouping, not a rules
// category) and is still excluded from Experience/advances (separately
// handled by advancementEligible, since War Beasts "never gain experience").
function compositionCounts(r){const fighters=Array.isArray(r?.fighters)?r.fighters:[];return {champions:fighters.filter(x=>advancementRole(x)==='Champion'||x.type==='Champion').length,henchmen:fighters.filter(x=>fighterSourceType(x)==='Henchman'||x.type==='Henchman'||x.type==='Animal').length,other:fighters.filter(x=>{const role=advancementRole(x);return role!=='Henchman'&&role!=='Champion'&&x.type!=='Henchman'&&x.type!=='Champion'&&x.type!=='Animal'}).length};}
function recruitmentRestriction(r,w){const en=siteLanguage==='en';if(!r||!w)return null;const counts=compositionCounts(r);const role=w.type==='Raw Recruit'?'Juves':(w.type==='Animal'?'Henchman':w.type);const limit=championLimitForRoster(r);if(role==='Champion'&&counts.champions>=limit)return en?`Champion limit reached: ${counts.champions}/${limit} (Reputation ${Number(r.reputation||0)})`:`Limite de Champions atteinte : ${counts.champions}/${limit} (Réputation ${Number(r.reputation||0)})`;if(role!=='Henchman'&&role!=='Champion'&&counts.henchmen<counts.other+1&&r.fighters.length>0)return en?`You need at least as many Henchmen as other warriors (${counts.henchmen} Henchmen / ${counts.other} others)`:`Il faut au moins autant de Henchmen que d'autres guerriers (${counts.henchmen} Henchmen / ${counts.other} autres)`;if(role==='Champion'&&counts.henchmen<counts.other+1&&r.fighters.length>0)return en?`You need at least as many Henchmen as other warriors (${counts.henchmen} Henchmen / ${counts.other} others)`:`Il faut au moins autant de Henchmen que d'autres guerriers (${counts.henchmen} Henchmen / ${counts.other} autres)`;return null;}
function recruitmentCompositionNotice(r){const en=siteLanguage==='en';const c=compositionCounts(r),limit=championLimitForRoster(r),valid=c.henchmen>=c.other;return `<div class="recruit-composition-notice ${valid?'valid':'warning'}"><div><strong>${en?'COMPOSITION · REPUTATION':'COMPOSITION · RÉPUTATION'} ${Number(r.reputation||0)}</strong><small>Champions : ${c.champions}/${limit} · Henchmen : ${c.henchmen} · ${en?'Others':'Autres'} : ${c.other}</small></div>${valid?`<span>✓ ${en?'Valid composition':'Composition valide'}</span>`:`<span>⚠ ${en?`Missing ${c.other-c.henchmen} Henchman${c.other-c.henchmen>1?'s':''}`:`Il manque ${c.other-c.henchmen} Henchman${c.other-c.henchmen>1?'s':''}`}</span>`}</div>`;}
// V-LEGALWARBANDPOPUP: recruiting/removing a fighter used to be hard-blocked
// the moment it would push the warband past the Champion cap or below the
// Henchman-ratio floor (recruitmentRestriction, used as a gate in
// addFighter), which it turns out isn't actually how the user wants this to
// work — a warband is allowed to become illegal (recruitment doesn't have
// to be turn-by-turn perfect), it just needs to be FLAGGED so the player
// knows to fix it before their next game, with an explanation of what to
// change. warbandLegalityIssues reports every current violation of the
// warband's current state (not a hypothetical post-recruit one); it's read
// live on every render by warbandLegalityBadgeMarkup (a persistent red
// resource badge) instead of being pushed as a popup on every purchase.
function warbandLegalityIssues(r){
  if(!r||!Array.isArray(r.fighters)||!r.fighters.length)return [];
  const en=siteLanguage==='en';
  const c=compositionCounts(r),limit=championLimitForRoster(r);
  const issues=[];
  if(c.champions>limit)issues.push(en?`Too many Champions: ${c.champions}/${limit} for Reputation ${Number(r.reputation||0)}. Remove ${c.champions-limit} Champion${c.champions-limit>1?'s':''}, or raise Reputation to allow more.`:`Trop de Champions : ${c.champions}/${limit} pour une Réputation de ${Number(r.reputation||0)}. Retire ${c.champions-limit} Champion${c.champions-limit>1?'s':''}, ou augmente la Réputation pour en autoriser plus.`);
  if(c.henchmen<c.other)issues.push(en?`Not enough Henchmen: ${c.henchmen} Henchmen for ${c.other} other fighters (need at least as many Henchmen as other fighters). Recruit ${c.other-c.henchmen} more Henchman${c.other-c.henchmen>1?'s':''}, or remove ${c.other-c.henchmen} other fighter${c.other-c.henchmen>1?'s':''}.`:`Pas assez de Henchmen : ${c.henchmen} Henchmen pour ${c.other} autres guerriers (il faut au moins autant de Henchmen que d'autres guerriers). Recrute ${c.other-c.henchmen} Henchman${c.other-c.henchmen>1?'s':''} de plus, ou retire ${c.other-c.henchmen} autre${c.other-c.henchmen>1?'s':''} guerrier${c.other-c.henchmen>1?'s':''}.`);
  return issues;
}
// V-LEGALWARBANDBADGE: a popup on every single recruit/removal ("Le pop up a
// chaque achat est a enlever") was too intrusive — the player already sees
// the recruit/removal succeed and doesn't need an interrupting modal on top
// of it every time. Composition legality is now a persistent, silent badge
// next to the band's resources instead (see the warband-overview block in
// builder()): a small red indicator that's simply there whenever the band is
// currently illegal, cleared the moment it no longer is, with the same
// explanation available on click instead of forced on every purchase.
function warbandLegalityBadgeMarkup(r){
  const issues=warbandLegalityIssues(r);
  if(!issues.length)return '';
  const en=siteLanguage==='en';
  return `<button type="button" class="warband-stat illegal-stat" onclick="openWarbandLegalityModal()"><span class="stat-icon">⚠</span><div><small>${en?'BUILD ERROR':'ERREUR DE BUILD'}</small><strong>${issues.length}</strong><span>${en?'Click for details':'Cliquer pour les détails'}</span></div></button>`;
}
function openWarbandLegalityModal(){
  const r=activeRoster();if(!r)return;
  const issues=warbandLegalityIssues(r);
  const en=siteLanguage==='en';
  if(!issues.length){closeModal();return}
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'ILLEGAL WARBAND':'BANDE ILLÉGALE'}</div><h2>${en?'This warband no longer follows the composition rules':'Cette bande ne respecte plus les règles de composition'}</h2><ul style="text-align:left;margin:0 0 16px;padding-left:20px;line-height:1.6">${issues.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><button type="button" class="button primary full" onclick="closeModal()">${en?'Got it':'Compris'}</button></div>`);
}
function logHistory(r,category,text){if(!r)return;if(!Array.isArray(r.history))r.history=[];r.history.unshift({id:crypto.randomUUID(),category,text,ts:Date.now()});if(r.history.length>300)r.history.length=300}
const HISTORY_CATS={recruit:{label:'Recrutement',color:'#7ddd2e'},xp:{label:'XP / Blessures',color:'#e6a8c8'},treasury:{label:'Trésorerie',color:'#f0dc4f'},equipment:{label:'Équipement',color:'#9cc3e0'},settings:{label:'Paramètres',color:'#c9a0f5'}};
let historyFilter='all';
function setHistoryFilter(cat){historyFilter=cat;render('builder')}
function historyDayLabel(ts){const d=new Date(ts),now=new Date();const startOfDay=x=>{const y=new Date(x);y.setHours(0,0,0,0);return y.getTime()};const diffDays=Math.round((startOfDay(now)-startOfDay(d))/86400000);if(diffDays===0)return 'Aujourd’hui';if(diffDays===1)return 'Hier';return d.toLocaleDateString('fr-FR',{day:'numeric',month:'long'})}
function historyRelativeTime(ts){const en=siteLanguage==='en';const diff=Date.now()-ts,min=Math.floor(diff/60000);if(min<1)return en?'just now':'à l’instant';if(min<60)return en?`${min} min ago`:`il y a ${min} min`;return new Date(ts).toLocaleTimeString(en?'en-GB':'fr-FR',{hour:'2-digit',minute:'2-digit'})}
function historyView(r){
  const all=Array.isArray(r.history)?r.history:[];
  const filtered=historyFilter==='all'?all:all.filter(e=>e.category===historyFilter);
  const chips=`<div class="hist-filters"><span class="hist-chip ${historyFilter==='all'?'active':''}" onclick="setHistoryFilter('all')">Tout</span>${Object.entries(HISTORY_CATS).map(([k,c])=>`<span class="hist-chip ${historyFilter===k?'active':''}" onclick="setHistoryFilter('${k}')"><span class="dot" style="background:${c.color}"></span>${c.label}</span>`).join('')}</div>`;
  if(!filtered.length)return `<div class="roster-toolbar"><div><div class="eyebrow">HISTORIQUE</div><h3>Historique de la bande</h3><p>Journal de toutes les modifications apportées à cette bande — recrutement, trésorerie, équipement, paramètres.</p></div></div>${chips}<div class="empty large"><strong>${all.length?'Aucune entrée pour ce filtre.':'Aucune activité enregistrée pour l’instant.'}</strong><span>${all.length?'Choisis un autre filtre ou reviens sur « Tout ».':'Recrute un combattant ou modifie la bande pour commencer le journal.'}</span></div>`;
  const groups=[];
  filtered.forEach(e=>{const label=historyDayLabel(e.ts);let g=groups.find(x=>x.label===label);if(!g){g={label,items:[]};groups.push(g)}g.items.push(e)});
  const body=groups.map(g=>`<div class="hist-day">${esc(g.label)}</div>${g.items.map(e=>{const cat=HISTORY_CATS[e.category]||{color:'#6f6f6a'};return `<div class="hist-row"><div class="hist-dot" style="background:${cat.color}"></div><div><div class="hist-text">${e.text}</div><div class="hist-meta">${historyRelativeTime(e.ts)}</div></div></div>`}).join('')}`).join('');
  return `<div class="roster-toolbar"><div><div class="eyebrow">HISTORIQUE</div><h3>Historique de la bande</h3><p>Journal de toutes les modifications apportées à cette bande — recrutement, trésorerie, équipement, paramètres.</p></div></div>${chips}<div class="hist-body">${body}</div>`;
}
function campaignView(r){const en=siteLanguage==='en';return `<div class="roster-toolbar"><div><div class="eyebrow">${en?'CAMPAIGN':'CAMPAGNE'}</div><h3>${en?'Campaign':'Campagne'}</h3><p>${en?'Track the warband within a campaign (standings, territories, rivalries).':'Suivi de la bande au sein d’une campagne (classement, territoires, rivalités).'}</p></div></div><div class="empty large"><strong>${en?'No campaign linked to this warband yet.':'Aucune campagne liée à cette bande pour l’instant.'}</strong><span>${en?'Campaign management (standings between warbands, territories, rivalries) is coming in a future update.':'La gestion de campagne (classement entre bandes, territoires, rivalités) arrive dans une prochaine mise à jour.'}</span></div>`}
function recruitmentView(f){const en=siteLanguage==='en';const r=activeRoster();return `<div class="recruit-head"><div><div class="eyebrow">${en?'RECRUITMENT':'RECRUTEMENT'} / ${esc(f.displayName)}</div><h3>${en?'Recruit a fighter':'Recruter un combattant'}</h3><p>${en?'Recruiting adds the fighter to the warband without opening their sheet. Open their card afterward from the roster.':'Le recrutement ajoute le combattant à la bande sans ouvrir sa fiche. Ouvre ensuite sa carte depuis le roster.'}</p></div></div>${recruitmentCompositionNotice(r)}<div class="recruit-select-row"><label>${en?'Fighter type':'Type de combattant'}<select id="typeFilter" class="select" onchange="filterFighters()"><option value="">${en?'All types':'Tous les types'}</option><option>Leader</option><option>Champion</option><option>Raw Recruit</option><option>Henchman</option></select></label><label class="grow">${en?'Search':'Rechercher'}<input id="fighterSearch" class="search" placeholder="${en?'Profile name…':'Nom du profil…'}" oninput="filterFighters()"></label></div><div class="fighter-pool" id="fighterPool">${fighterPool(f)}</div>`}
function chosenRow(x,i){return `<button class="chosen-v4" onclick="openFighterCard(${i})"><span class="chosen-sigil">${factionSigils[faction(activeRoster()).id]||'◆'}</span><span class="chosen-info"><b>${esc(x.name)}</b><small>${esc(x.type)} · ${fighterValue(x,faction(activeRoster()))} GC</small></span><span class="chosen-open">›</span></button>`}
var ARMOUR_SUITS=['Light armour','Light armor','Heavy armour','Heavy armor','Full plate armour','Full plate armor','Gromril plate','Gromril plate armour','Gromril plate armor','Ithilmar','Ithilmar mail','Ithilmar armour','Ithilmar armor','Sigmarite armour','Sigmarite armor','Chaos armour','Chaos armor'];
var FUR_CLOAKS=['Fur cloak','Wolf cloak'];
var OFFHAND_DEFENCE=['Shield','Buckler','Main Gauche','Left hand dagger','Sword breaker'];
function moveStashEquipmentToReserve(i){const r=activeRoster(),x=r?.fighters[editingIndex];if(!r||!x||!fighterUsesLoadouts(x))return;ensureFighterLoadouts(x);const e=x.equipmentStash?.[i];if(!e)return;if(normName(e.name)==='chaos armour'||normName(e.name)==='chaos armor'){toast(siteLanguage==='en'?'Chaos Armour is fused to its wearer and can’t be put in the stash.':'L’armure du Chaos est fusionnée au porteur et ne peut pas être mise en réserve.');return}r.reserve=r.reserve||[];r.reserve.push({...JSON.parse(JSON.stringify(e)),reserveId:crypto.randomUUID(),sourceFighter:x.name});x.equipmentStash.splice(i,1);x.equipmentLoadouts.forEach(l=>{l.equipmentIds=(l.equipmentIds||[]).filter(id=>id!==e.stashId);l.equipmentNames=l.equipmentIds.map(id=>x.equipmentStash.find(q=>q.stashId===id)?.name).filter(Boolean)});syncLoadoutProjection(x);syncCustomEquipmentEffects(x);save(true);render('fighter');toast(siteLanguage==='en'?`${e.name} put in the stash`:`${e.name} placé en réserve`)}

function moveEquipmentToReserve(i){const r=activeRoster(),x=r?.fighters[editingIndex],e=x?.equipmentSelected?.[i];if(!r||!x||!e)return;if(normName(e.name)==='chaos armour'||normName(e.name)==='chaos armor'){toast(siteLanguage==='en'?'Chaos Armour is fused to its wearer and can’t be put in the stash.':'L’armure du Chaos est fusionnée au porteur et ne peut pas être mise en réserve.');return}r.reserve=r.reserve||[];r.reserve.push({...JSON.parse(JSON.stringify(e)),reserveId:crypto.randomUUID(),sourceFighter:x.name});x.equipmentSelected.splice(i,1);syncCustomEquipmentEffects(x);logHistory(r,'equipment',siteLanguage==='en'?`<b>${esc(e.name)}</b> transferred to the <b>Equipment Stash</b> from <b>${esc(x.name)}</b>`:`<b>${esc(e.name)}</b> transféré vers la <b>Réserve d'équipement</b> depuis <b>${esc(x.name)}</b>`);save(true);equipmentOpen=true;render('fighter');toast(siteLanguage==='en'?`${e.name} put in the stash`:`${e.name} placé en réserve`)}
function transferReserveEquipment(i){const en=siteLanguage==='en';const r=activeRoster(),e=r?.reserve?.[i];if(!r||!e)return;
  // V-STASHTRANSFER-FIX: this item already belongs to the warband (it was
  // bought on the Market or moved out of another fighter's kit), so
  // reassigning it between fighters only needs to respect the physical
  // equip rules (weapon slots, armour exclusivity) via canEquip — NOT
  // warriorBandAllowed, which is the per-fighter admin-curated "Band List"
  // access-grant check (equipmentAccess/equipmentAccessGroups). A freshly
  // recruited book fighter has equipmentAccessGroups=[] by default, so
  // warriorBandAllowed rejected every item for every fighter here, leaving
  // the transfer dialog permanently empty — exactly the reported bug. The
  // faction link for custom equipment is still worth honoring, so that one
  // check is kept via isCustomEquipment, without the rest of the gate.
  const eligible=r.fighters.map((x,idx)=>{const access=isCustomEquipment(e)?!!customEquipmentForFaction(e,faction(r)?.id):true;const check=fighterUsesLoadouts(x)?{ok:true,msg:''}:canEquip(x,e);return {x,idx,ok:check.ok&&access,reason:!access?(en?'Equipment not allowed for this profile':'Équipement non autorisé pour ce profil'):check.msg}}).filter(a=>a.ok);openModal(`<div class="skill-dialog"><div class="eyebrow">${en?'STASH · TRANSFER':'RÉSERVE · TRANSFERT'}</div><h2>${esc(e.name)}</h2><p>${en?'Choose which fighter to assign this equipment to. Weapon limits, profile access and armour rules are checked.':'Choisis le combattant auquel attribuer cet équipement. Les limites d’armes, l’accès au profil et les règles d’armure sont vérifiés.'}</p><div class="reserve-transfer-list">${eligible.length?eligible.map(a=>`<button type="button" class="skill-modal-skill" onclick="confirmTransferReserve(${i},${a.idx})"><span>${esc(a.x.name)}</span><small>${esc(a.x.type)} · ${currentWeaponSlots(a.x)}/3</small></button>`).join(''):`<div class="empty compact">${en?'No fighter can currently equip this item.':'Aucun combattant ne peut actuellement équiper cet objet.'}</div>`}</div><div class="purchase-actions"><button type="button" class="button secondary" onclick="closeModal()">${en?'Close':'Fermer'}</button></div></div>`)}
function confirmTransferReserve(ri,fi){const r=activeRoster(),e=r?.reserve?.[ri],x=r?.fighters?.[fi];if(!r||!e||!x)return;
  // V-STASHTRANSFER-FIX: mirror the eligibility check in transferReserveEquipment above.
  const access=isCustomEquipment(e)?!!customEquipmentForFaction(e,faction(r)?.id):true,check=fighterUsesLoadouts(x)?{ok:true,msg:''}:canEquip(x,e);if(!access||!check.ok){toast(!access?(siteLanguage==='en'?'Equipment not allowed for this profile':'Équipement non autorisé pour ce profil'):check.msg);return}const copy={...JSON.parse(JSON.stringify(e)),stashId:crypto.randomUUID(),paid:0};if(fighterUsesLoadouts(x)){ensureFighterLoadouts(x);x.equipmentStash=x.equipmentStash||[];x.equipmentStash.push(copy);syncLoadoutProjection(x);}else{x.equipmentSelected=x.equipmentSelected||[];x.equipmentSelected.push(copy);}syncCustomEquipmentEffects(x);r.reserve.splice(ri,1);logHistory(r,'equipment',siteLanguage==='en'?`<b>${esc(e.name)}</b> transferred from the <b>Stash</b> to <b>${esc(x.name)}</b>`:`<b>${esc(e.name)}</b> transféré de la <b>Réserve</b> vers <b>${esc(x.name)}</b>`);save(true);closeModal();gangTab='reserve';render('builder');toast(siteLanguage==='en'?`${e.name} placed in ${x.name}'s kit`:`${e.name} placé dans le coffre de ${x.name}`)}
function sellReserveEquipment(i){const en=siteLanguage==='en';const r=activeRoster(),e=r?.reserve?.[i];if(!r||!e)return;const sale=Math.max(0,Math.floor(Number(e.value??e.price??0)/2));openModal(`<div class="sell-dialog"><div class="eyebrow">${en?'SELL FROM STASH':'VENTE DE RÉSERVE'}</div><h2>${en?`Sell “${esc(e.name)}”?`:`Vendre « ${esc(e.name)} » ?`}</h2><p>${en?'The M17 resale rule lets you sell equipment for half its listed price.':'La règle de revente du M17 permet de vendre l’équipement pour la moitié de son prix indiqué.'}</p><label>${en?'Gold recovered (GC)':'Or récupéré (GC)'}<input id="saleGold" type="number" min="0" step="1" value="${sale}"></label><div class="purchase-actions"><button type="button" class="button secondary" onclick="closeModal()">${en?'Cancel':'Annuler'}</button><button type="button" class="button primary" onclick="confirmSellReserveEquipment(${i})">${en?'Sell':'Vendre'}</button></div></div>`)}
function confirmSellReserveEquipment(i){const r=activeRoster(),e=r?.reserve?.[i];if(!r||!e)return;const gold=Math.max(0,Number($('#saleGold')?.value||0));if(!Number.isFinite(gold)){toast(siteLanguage==='en'?'Invalid amount':'Montant invalide');return}r.gold+=gold;r.reserve.splice(i,1);logHistory(r,'equipment',siteLanguage==='en'?`<b>${esc(e.name)}</b> sold from the stash — <b style="color:var(--accent)">+${gold} GC</b>`:`<b>${esc(e.name)}</b> vendu depuis la réserve — <b style="color:var(--accent)">+${gold} GC</b>`);save(true);closeModal();render('builder');toast(siteLanguage==='en'?`${e.name} sold · +${gold} GC`:`${e.name} vendu · +${gold} GC`)}
function removeReserveEquipment(i){const en=siteLanguage==='en';const r=activeRoster(),e=r?.reserve?.[i];if(!r||!e)return;openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'DELETE EQUIPMENT':'SUPPRESSION D’ÉQUIPEMENT'}</div><h2>${en?`Delete “${esc(e.name)}”?`:`Supprimer « ${esc(e.name)} » ?`}</h2><p>${en?'The item will be removed from the stash with no refund.':'L’objet sera retiré de la réserve sans remboursement.'}</p><button type="button" class="big-delete" onclick="confirmRemoveReserveEquipment(${i})">${en?'DELETE THE EQUIPMENT':'SUPPRIMER L’ÉQUIPEMENT'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`)}
function confirmRemoveReserveEquipment(i){const r=activeRoster();if(!r?.reserve?.[i])return;r.reserve.splice(i,1);save(true);closeModal();render('builder')}
function updateFighterStat(i,val){const x=activeRoster()?.fighters[editingIndex];if(!x)return;if(!Array.isArray(x.profile))x.profile=Array.isArray(x.baseProfile)?x.baseProfile.slice():[];let n=Math.round(Number(val));if(!Number.isFinite(n))n=Number(x.profile[i]||0);const max=maxProfileFor(x);n=Math.max(0,n);x.profile[i]=n;save(true);render('fighter')}
function statsTabMarkup(x){const en=siteLanguage==='en';const original=Array.isArray(x.baseProfile)?x.baseProfile:(Array.isArray(x.profile)?x.profile:[]);const current=Array.isArray(x.profile)?x.profile:original;return `<section class="sheet-block stats-collapse-block ${statsOpen?'is-open':'is-collapsed'}"><button type="button" class="equipment-collapse-head stats-collapse-head" onclick="toggleStatsPanel()"><span><span class="equipment-collapse-icon">${statsOpen?'−':'＋'}</span><strong>${en?'Edit characteristics':'Modifier les caractéristiques'}</strong></span><span>${statsOpen?(en?'Collapse':'Réduire'):(en?'Show':'Afficher')} · ${D.profileNames.length} ${en?'characteristics':'caractéristiques'}</span></button>${statsOpen?`<div class="stats-collapse-body"><div class="stats-inline-list">${D.profileNames.map((name,i)=>`<div class="stats-inline-row"><span class="stats-inline-name">${esc(name)}</span><span class="stats-inline-original" title="${en?'Original value':'Valeur d\'origine'}">${esc(original[i]??'—')}</span><span class="stats-inline-arrow">→</span><input class="stat-current-inline ${Number(current[i]??original[i]??0)>Number(maxProfileFor(x)?.[i]??Infinity)?'stat-input-overstat':''}" type="number" step="1" value="${esc(current[i]??original[i]??'')}" onchange="updateFighterStat(${i},this.value)" aria-label="${esc(name)} ${en?'current':'actuelle'}"><small>${en?'original':'origine'} ${esc(original[i]??'—')}</small></div>`).join('')}</div><p class="stats-inline-help">${en?'The value on the left is the original profile\'s. Only the current value is editable.':'La valeur de gauche est celle du profil d\'origine. Modifie uniquement la valeur actuelle.'}</p></div>`:''}</section>`}

