  const allItems=[...D.weapons,...allCustomEquipmentList()];
  const presentCats=new Set(allItems.map(w=>canonEquipmentCategory(equipmentCategory(w))));
  const catSections=EQUIPMENT_SECTIONS.filter(s=>presentCats.has(s.cat));
  const cats=['all',...catSections.map(s=>s.cat)];
  const catLabel=c=>c==='all'?(en?'All':'Toutes'):(en?(EQUIPMENT_SECTIONS.find(s=>s.cat===c)?.label||c):c);
  // V-KEEPBUYABLE: an item used to be hidden from this list the moment the
