/* ================= CUSTOM FIGHTER PROFILES ================= */
let customTab='fighters';
let customFighterEditId=null;
let customFighterSearch='';
// V-WARBANDROSTER: preselects the "Warband" field when opening the fighter
// form from inside a warband's own Combattants section (newWarbandFighter
// below) — a brand-new fighter otherwise defaults to the first official
// faction, which would silently NOT tie it to the warband it was created
// from.
let customFighterPresetWarbandId=null;
let customFighterRuleDraft=[];
let customFighterSkillDraft=[];
let customFighterDefaultEquipmentDraft=[];
let customFighterEquipmentAccessDraft=[];
let customFighterMagicAccessDraft={};

function customFighterList(){
  if(!Array.isArray(state.customFighters))state.customFighters=[];
  return state.customFighters;
}
function customFighterById(id){
  const hit=customFighterList().find(x=>x.customFighterId===id);
  if(hit)return hit;
  // V-ANIMALRECRUIT: an Animal-kind Custom Creature is recruited the same
  // way a Custom Fighter is (see addFighter/customFighterAsWarrior), so
  // every later re-sync that looks a recruited fighter's source up by
  // customFighterId (ensureFighterSourceData, maxProfileFor, the fighter
  // sheet, etc.) needs to find it here too, under its own
  // customCreatureId (aliased as customFighterId on the recruited copy —
  // see customCreatureAsWarrior). Never match a Mount this way: a Mount
  // isn't a fighter, it's equipment (mountCreatureAsEquipment).
  // allCustomCreatureList: an Animal published on an official warband is
  // offered in every recruitment pool, so it must also resolve here.
  return allCustomCreatureList().find(x=>x.customCreatureId===id&&x.kind==='animal')||null;
}
function customFighterFactionMatches(w,f){
  if(!w||!f)return false;
  const stored=normName(w.factionId||w.faction);
  const candidates=[f.id,f.displayName,f.baseFactionId,activeRoster()?.factionId].filter(Boolean).map(normName);
  if(w.customWarbandId && normName(f.id)===normName(`custom-warband-${w.customWarbandId}`))return true;
  const cwId=String(w.customWarbandId||'');
  if(cwId && normName(f.id)===normName(cwId))return true;
  if(candidates.includes(stored))return true;
  const obj=D.factions.find(a=>normName(a.id)===stored||normName(a.displayName)===stored);
  if(obj && candidates.some(c=>c===normName(obj.id)||c===normName(obj.displayName)||c===normName(obj.baseFactionId)))return true;
  return false;
}
function customFightersForFaction(f){
  if(!f)return [];
  return customFighterList().filter(w=>customFighterFactionMatches(w,f)).map(customFighterAsWarrior);
}
function customFighterAsWarrior(w){
  // An Animal-kind Custom Creature draft (has `kind`; a real Custom Fighter
  // draft never does) is shaped differently — route it to its own wrapper
  // instead of misreading it as a Henchman-default fighter draft.
  if(w&&w.kind)return customCreatureAsWarrior(w);
  return {
    ...w,
    id:w.customFighterId,
    customFighterId:w.customFighterId,
    custom:true,
    max:w.max===null||w.max===undefined||w.max===''?null:Number(w.max),
    type:w.type||'Henchman',
    profile:Array.isArray(w.profile)?w.profile.slice():P.map(()=>1),
    skillAccess:w.skillAccess||{},
    magicAccess:w.magicAccess||{},
    // V-WBEQUIPACCESSPRESERVE: this wrapper is also used (via
    // customWarbandWarriors) to re-package an OFFICIAL warrior for display
    // inside a custom warband — that warrior's real equipmentAccessGroups
    // (the book's own group tags, or 'ALL') is already sitting on `w` via
    // the spread above and must survive untouched. A genuinely
    // custom-authored fighter never sets equipmentAccessGroups itself (only
    // equipmentAccess, from the Custom tab's per-item chooser), so it still
    // falls through to the old derivation exactly as before.
    equipmentAccessGroups:w.equipmentAccessGroups!==undefined?w.equipmentAccessGroups:(Array.isArray(w.equipmentAccess)?w.equipmentAccess.slice():[]),
    rules:w.rules||'',
    race:w.race||fighterRace(w),
    ruleNames:fighterRuleNames({...w,ruleNames:Array.isArray(w.ruleNames)?w.ruleNames.slice():[]},null),
    description:w.description||''
  };
}
function customFighterAllEquipment(){
  const customs=allCustomEquipmentList();
  // V-MOUNTSHADOW: customs listed FIRST for DEDUPE PRIORITY — a custom item
  // (a Mount-kind Custom Creature especially: see mountCreatureEquipmentList)
  // sharing its name with a plain book entry (the stock "Warhorse", which
  // carries no creatureProfile at all) is the user's deliberate enrichment
  // of it, not a coincidence to leave ambiguous. D.weapons second means the
  // book version only fills the slot when nothing custom claims that name.
  const all=[...customs,...D.weapons.filter(w=>!w.hidden)];
  const seen=new Set();
  const deduped=all.filter(w=>{const k=normName(w.name);if(!k||seen.has(k))return false;seen.add(k);return true});
  // V-EQUIPCATALPHA: that custom-first ORDER was also what every category
  // group in customFighterEquipmentChooser (the Default Equipment/Equipment
  // Access checklists in Admin → Gestion and the Custom fighter builder)
  // inherited, since it just buckets this list by category without
  // re-sorting — so within a category, every officialized/custom item
  // appeared before every book item instead of interleaved alphabetically
  // ("the list is not alphabetical because it separates officialized item
  // and base item"). Sorting here, after the dedupe above (which still
  // needs the custom-first order to pick the right winner on a name
  // collision), makes every consumer of this list alphabetical by name
  // regardless of source, with no change to which copy wins a collision.
  return deduped.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));
}
function newCustomFighter(){customFighterEditId=null;customFighterRuleDraft=[];customFighterSkillDraft=[];customFighterDefaultEquipmentDraft=[];customFighterEquipmentAccessDraft=[];customFighterMagicAccessDraft={};render('custom');setTimeout(()=>$('#cfName')?.focus(),30)}
function editCustomFighter(id){const w=customFighterById(id);if(!w)return;customFighterEditId=id;customFighterRuleDraft=(w.ruleNames||[]).slice();customFighterSkillDraft=(w.defaultSkills||[]).slice();customFighterDefaultEquipmentDraft=(w.defaultEquipment||[]).slice();customFighterEquipmentAccessDraft=(w.equipmentAccess||[]).slice();customFighterMagicAccessDraft=JSON.parse(JSON.stringify(w.magicAccess||{}));render('custom')}
// V-WARBANDROSTER: entry points reached from a warband's own Combattants
// section — mirrors newExclusiveCustomEquipment/editExclusiveCustomEquipment.
// customWarbandCreateContextId makes saveCustomFighter jump back into the
