  const w=inWarband||(cw?customFighterAsWarrior(cw):null);
  if(!w)return;if(!Array.isArray(x.baseProfile)&&Array.isArray(w.profile))x.baseProfile=effectiveFighterProfile(w,f);if(w.rules)x.rules=w.rules;if(Array.isArray(w.ruleNames))x.ruleNames=w.ruleNames.slice();if(w.packRules)x.packRules=JSON.parse(JSON.stringify(w.packRules));if(w.packModifiers)x.packModifiers=JSON.parse(JSON.stringify(w.packModifiers));
