// When true, the fighter/equipment pickers below hide entries that come from
// an already-existing (official book) warband, so building a warband from
// scratch isn't buried under every other faction's roster. Anything already
// selected stays visible regardless, so toggling this can never silently
// drop a pick made earlier.
let customWarbandHideOfficial=true;
function toggleCustomWarbandHideOfficial(v){customWarbandHideOfficial=!!v;render('custom')}
let selectedCustomWarbandId=null;
/* ================= DUPLICATE AN EXISTING WARBAND (V149) ===================
   "Un duplicata du gang de base que je peux modifier pour faire une
   nouvelle warband": picks any book faction or published official warband
   and copies every one of its fighters into brand-new, independent custom
   fighter profiles (not live references) attached to a brand-new custom
   warband — so every copied fighter can be freely edited, removed, or
   added to, with zero link back to the source. Officializing the result
   afterward (same button as any other custom warband) is what turns it
   into a real, generally selectable warband. */
function openDuplicateWarbandPicker(){
  const en=siteLanguage==='en';
  const options=D.factions.filter(f=>!f.packId&&!isContentPoolFaction(f)).map(f=>`<option value="${esc(f.id)}">${esc(f.displayName)}${f.__official?' · '+(en?'official':'officielle'):''}</option>`).join('');
  openModal(`<div class="admin-live-editor"><div class="eyebrow">${en?'DUPLICATE':'DUPLIQUER'}</div><h2>${en?'Start a new warband from an existing one':'Démarrer une nouvelle warband à partir d’une existante'}</h2><p class="muted">${en?'Copies every fighter as an independent custom profile you can freely edit, remove or add to — nothing stays linked to the source. Once you’re happy with it, officialize it like any other custom warband to publish it.':'Copie chaque combattant en profil custom indépendant, librement modifiable, supprimable ou complétable — rien ne reste lié à la source. Une fois satisfait·e, officialise-la comme n’importe quelle autre warband custom pour la publier.'}</p><label class="custom-field wide"><span>${en?'Source warband':'Warband source'}</span><select id="dupWarbandSource">${options}</select></label><label class="custom-field wide"><span>${en?'New name':'Nouveau nom'}</span><input id="dupWarbandName" placeholder="${en?'e.g. My warband — supplement':'Ex. Ma bande — supplément'}"></label><label class="custom-check"><input type="checkbox" id="dupAsSupplement"> <span><b>${en?'Make it a Supplement of the source warband':'En faire un supplément de la warband d’origine'}</b><small>${en?'Replaces the source’s rules when a player picks it instead of showing its own tile in Create Warband — set at publish time; leave unchecked for an independent warband.':'Remplace les règles de la bande source quand un joueur la choisit, au lieu d’avoir sa propre case dans Créer une bande — ce choix est appliqué au moment de publier ; laisse décoché pour une bande indépendante.'}</small></span></label><div class="account-actions"><button class="button primary" type="button" onclick="confirmDuplicateWarband()">${en?'Duplicate':'Dupliquer'}</button><button class="button secondary" type="button" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div></div>`);
}
// V-WBEQUIPALLSHORTHAND: the 'ALL' shorthand shows up two ways in the data
// — as the bare string (equipmentAccessExplicit, and however admin-set
// overrides save it) and as a one-element array ["ALL"] (equipmentAccessGroups,
// for warriors like the Reiklander Sergeant) — both meaning the same thing,
// but only the bare-string form used to be recognized, so the array form
// fell through to the group-tag matching path and matched nothing (no item
// is tagged with a group literally named "ALL").
function equipmentGroupsMeansAll(groups){return groups==='ALL'||(Array.isArray(groups)&&groups.includes('ALL'))}
// Resolves which of faction `f`'s equipment items match a list of group
// tags (or the 'ALL' shorthand) — same membership lookup as
// warriorBandAllowed/duplicateWarriorEquipmentAccess below, factored out so
// the Rules: Warband fighter card can show the actual item names behind an
// "equipment access" category instead of just the bare category label.
function equipmentNamesForGroups(f,groups){
  if(!f)return [];
  const names=(f.equipment||[]).map(e=>typeof e==='string'?e:e?.name).filter(Boolean);
  if(equipmentGroupsMeansAll(groups))return names.slice();
  if(!Array.isArray(groups)||!groups.length)return [];
  const out=[];
  names.forEach(name=>{
    if(groups.includes('Natural Weapons')&&name==='Natural Weapons'){out.push(name);return}
    const key=Object.keys(f.equipmentItemGroups||{}).find(k=>normName(k)===normName(name));
    const memberships=key?(f.equipmentItemGroups[key]||[]):[];
    if(groups.some(g=>memberships.includes(g)))out.push(name);
  });
  return out;
}
// V-WBEQUIPACCESSRESOLVE: equipmentAccessGroups is genuinely two different
// shapes depending on where the warrior comes from. An OFFICIAL warrior's
// entries are the book's own broad group tags (e.g. "Close Combat
// Weapons", "Armour"), meant to be resolved against the faction's
// equipmentItemGroups membership map (equipmentNamesForGroups above). A
// warrior that is genuinely custom-authored (has its own customFighterId —
// built via the Custom tab's per-item "equipment access" chooser) instead
// stores individual item NAMES picked one by one, and a custom
// warband/faction never has an equipmentItemGroups map at all (that
// tagging only exists on the 11 parsed book factions) — so running those
// through equipmentNamesForGroups always came back empty, which is the
// "no item tagged in this category" bug: every category showed its raw
// entry as a bare label with nothing under it. This resolves each shape
// through the right path instead of forcing both through the official one.
function equipmentAccessResolvedNames(w,f){
  const raw=w.equipmentAccessGroups!==undefined?w.equipmentAccessGroups:(w.equipmentAccessExplicit!==undefined?w.equipmentAccessExplicit:(w.equipmentAccess!==undefined?w.equipmentAccess:[]));
  const isCustomFighter=!!w.customFighterId;
  if(equipmentGroupsMeansAll(raw)){
    if(isCustomFighter)return customFighterAllEquipment().map(e=>e.name);
    return (f?.equipment||[]).map(e=>typeof e==='string'?e:e?.name).filter(Boolean);
  }
  const list=Array.isArray(raw)?raw:[];
  if(!list.length)return [];
  if(isCustomFighter){
    const pool=customFighterAllEquipment();
    return list.map(n=>{
      if(n==='Natural Weapons')return n;
      const hit=pool.find(w2=>normName(w2.name)===normName(n));
      return hit?hit.name:n;
    });
  }
  return equipmentNamesForGroups(f,list);
}
function equipmentCategoryForName(name,en){
  if(name==='Natural Weapons')return en?'Natural weapons':'Armes naturelles';
  const hit=customFighterAllEquipment().find(w2=>normName(w2.name)===normName(name));
  return (hit&&(hit.category||hit.subcategory))||(en?'Other equipment':'Autre équipement');
}
// Groups a fighter's resolved equipment access by the item's REAL category
// instead of by the raw access-list entries themselves — for an official
// warrior those are broad book tags and for a custom fighter they're
// individual item names, neither of which is a category a reader would
// recognize as one. Dedupes by name (an item can be reachable through more
// than one raw entry) and reads as a clickable, categorized list, per the
// requested layout.
function equipmentAccessGroupedForDisplay(w,f,en){
  const names=equipmentAccessResolvedNames(w,f);
  const seen=new Set(),groups={},order=[];
  names.forEach(name=>{
    const key=normName(name);if(!key||seen.has(key))return;seen.add(key);
    const cat=equipmentCategoryForName(name,en);
    if(!groups[cat]){groups[cat]=[];order.push(cat);}
    groups[cat].push(name);
  });
  return order.sort((a,b)=>a.localeCompare(b)).map(cat=>({label:cat,items:groups[cat].slice().sort((a,b)=>a.localeCompare(b))}));
}
// Resolves which of `f`'s equipment items a source warrior `sw` should keep
// access to once copied out as an independent custom fighter — same
// group-tag logic as warriorBandAllowed, but against the warband being
// duplicated FROM rather than whatever roster happens to be open (there
// usually isn't one, from the Custom tab). No group info at all (most
// official-warband fighters) defaults to the whole faction list, same
// spirit as the "ALL" shorthand — better to over-grant than to hand back a
// fighter with no equipment options, which is trivial to trim afterward.
function duplicateWarriorEquipmentAccess(sw,f){
  const names=(f.equipment||[]).map(e=>typeof e==='string'?e:e?.name).filter(Boolean);
  const groups=sw?.equipmentAccessGroups;
  if(groups==null||equipmentGroupsMeansAll(groups))return names.slice();
  if(!Array.isArray(groups))return names.slice();
  const out=[];
  names.forEach(name=>{
    if(groups.includes('Natural Weapons')&&name==='Natural Weapons'){out.push(name);return}
    const key=Object.keys(f.equipmentItemGroups||{}).find(k=>normName(k)===normName(name));
    const memberships=key?(f.equipmentItemGroups[key]||[]):[];
    if(groups.some(g=>memberships.includes(g)))out.push(name);
  });
  return out;
}
// Copies a source warband's OWN band-wide content — traits, special rules,
// exclusive skill trees/skills, exclusive magic domains/spells — into new,
// independent custom entries attached to the duplicate, so "dupliquer" is a
// full copy (not just the fighter list). Book factions have none of this
// (their rules are the shared rulebook, not band-specific), so every `||[]`
// here is simply empty and this is a no-op for them. Renames a tree/domain
// that collides with something already existing globally (most often: the
// same source duplicated more than once) rather than merging into it, so
// each duplicate stays independently editable. Returns the old→new name
// maps so the caller can keep each copied fighter's skillAccess/magicAccess
// pointing at the right (possibly renamed) tree/domain.
function duplicateWarbandBandContent(f,cw){
  (f.traits||[]).forEach(t=>{
    if(!t?.name)return;
    const item={customContentId:crypto.randomUUID(),name:t.name,text:t.text||''};
    customContentList('traits').push(item);
    cw.traitIds.push(item.customContentId);
  });
  (f.specialRules||[]).forEach(r=>{
    if(!r?.name)return;
    const item={customContentId:crypto.randomUUID(),name:r.name,text:r.text||''};
    customContentList('special').push(item);
    cw.specialRuleIds.push(item.customContentId);
  });
  // V-DUPBANDRULENAMES (Task #79): f.bandRuleNames is a SEPARATE mechanism
  // from f.specialRules above — it's a list of bare NAME "keyword" tags an
  // admin toggled on for this warband via Gestion (adminWarbandRulesPanel),
  // each one pointing at an EXISTING book Référentiel special-rule entry
  // (e.g. "Frenzy", "Undead") rather than carrying its own custom text. A
  // custom warband (cw) has no equivalent field to hold a bare reference —
  // only specialRuleIds, which point at full custom content items — so
  // duplicating used to silently drop every one of these keyword tags.
  // Fixed by baking each one into its own independent custom special-rule
  // item (name + the book entry's own text, copied verbatim), same as any
  // other band-wide content copied here — skips a name already covered by
  // f.specialRules above so it isn't duplicated.
  const specialNamesSoFar=new Set((f.specialRules||[]).map(r=>normName(r?.name||'')));
  (f.bandRuleNames||[]).forEach(name=>{
    const n=normName(name);
    if(!name||specialNamesSoFar.has(n))return;
    specialNamesSoFar.add(n);
    const ref=referenceFind('special',name);
    const item={customContentId:crypto.randomUUID(),name:ref?.name||name,text:ref?.text||''};
    customContentList('special').push(item);
    cw.specialRuleIds.push(item.customContentId);
  });
  // V-OFFICIALSPELLDOMAINDRIFT (Task #54): a warband published before the
  // matching fix in bundleCustomContentForOfficialize/mergeOfficialWarbandPackage
  // can still carry a skill/spell whose own tree/domain field differs from
  // the tree/domain's canonical name by casing/whitespace. Treating every
  // spelling as its own separate tree/domain here would create a redundant
  // near-duplicate for each variant AND still leave the skill/spell
  // unattached wherever its exact spelling wasn't one already collected
  // from f.skillTrees/f.exclusiveSkillSets. Instead: collect every variant
  // encountered, create exactly ONE new tree/domain per normalized name,
  // and map every variant (plus, as a last-resort fallback, a normalized
  // lookup) onto that same copy — remapKeys() below still looks fighters'
  // skillAccess/magicAccess up by their own exact original key, which this
  // keeps satisfying since every variant is mapped, not just one.
  const treeNameMap=new Map(),treeCanonical=new Map();
  [...(f.skillTrees||[]).map(t=>t.name),...Object.keys(f.exclusiveSkillSets||{})].filter(Boolean).forEach(name=>{
    const nk=normName(name);
    if(!treeCanonical.has(nk)){
      const finalName=customTreeNameExists(name)?name+' (copie)':name;
      customSkillTreeList().push({id:crypto.randomUUID(),name:finalName,description:''});
      treeCanonical.set(nk,finalName);
    }
    treeNameMap.set(name,treeCanonical.get(nk));
  });
  (f.skills||[]).forEach(s=>{
    if(!s?.name||!s?.tree)return;
    customContentList('skills').push({customContentId:crypto.randomUUID(),name:s.name,text:s.text||'',tree:treeNameMap.get(s.tree)||treeCanonical.get(normName(s.tree))||s.tree});
  });
  const domainNameMap=new Map(),domainCanonical=new Map();
  [...(f.magicDomains||[]).map(d=>d.name),...Object.keys(f.exclusiveMagicDomains||{})].filter(Boolean).forEach(name=>{
    const nk=normName(name);
    if(!domainCanonical.has(nk)){
      const finalName=customDomainNameExists(name)?name+' (copie)':name;
      customMagicDomainList().push({id:crypto.randomUUID(),name:finalName,description:''});
      domainCanonical.set(nk,finalName);
    }
    domainNameMap.set(name,domainCanonical.get(nk));
  });
  (f.spells||[]).forEach(s=>{
    if(!s?.name||!s?.domain)return;
    customContentList('spells').push({customContentId:crypto.randomUUID(),name:s.name,text:s.text||'',domain:domainNameMap.get(s.domain)||domainCanonical.get(normName(s.domain))||s.domain});
  });
  return {treeNameMap,domainNameMap};
}
function confirmDuplicateWarband(){
  const en=siteLanguage==='en';
  const fid=$('#dupWarbandSource')?.value;
  const f=D.factions.find(x=>x.id===fid&&!x.packId);
  if(!f){toast(en?'Pick a source warband':'Choisis une warband source');return}
  const name=($('#dupWarbandName')?.value||'').trim()||(en?`${f.displayName} — copy`:`${f.displayName} — copie`);
  // V-WARBANDEXCLUSIVE: "make it a Supplement" checkbox on the duplicate
  // modal just pre-records the intent (supplementOfFactionId) — the actual
  // Supplement relationship is only ever created server-side at publish
  // time (adminOfficializeWarband's supplementOf param), see
  // officializeCustomWarband below, which reads this back to preselect it.
  const asSupplement=!!$('#dupAsSupplement')?.checked;
  const cw={id:crypto.randomUUID(),name,description:f.description||'',choices:f.choices&&typeof f.choices==='object'?JSON.parse(JSON.stringify(f.choices)):null,fighterIds:[],equipmentIds:[],fighterRefs:[],equipmentRefs:[],specialRuleIds:[],traitIds:[],supplementOfFactionId:asSupplement?f.id:null};
  customWarbandList().push(cw);
  const {treeNameMap,domainNameMap}=duplicateWarbandBandContent(f,cw);
  const remapKeys=(obj,map)=>{const out={};Object.entries(obj||{}).forEach(([k,v])=>{out[map.get(k)||k]=v});return out};
  (f.warriors||[]).forEach(sw=>{
    const item={
      customFighterId:crypto.randomUUID(),
      name:sw.name,type:sw.type||'Henchman',factionId:'',customWarbandId:cw.id,
      cost:Number(sw.cost||0),
      max:sw.max===undefined?null:sw.max,
      maxMode:sw.maxMode||'auto',
      manualMaxProfile:Array.isArray(sw.manualMaxProfile)?sw.manualMaxProfile.slice():null,
      profile:Array.isArray(sw.profile)?sw.profile.slice():P.map(()=>1),
      race:sw.race||'Human',
      ruleNames:Array.isArray(sw.ruleNames)?sw.ruleNames.slice():[],
      rules:sw.rules||(Array.isArray(sw.ruleNames)?sw.ruleNames.join(', '):''),
      skillAccess:remapKeys(sw.skillAccess,treeNameMap),
      magicAccess:remapKeys(sw.magicAccess,domainNameMap),
      defaultSkills:Array.isArray(sw.defaultSkills)?sw.defaultSkills.slice():[],
      defaultEquipment:Array.isArray(sw.defaultEquipment)?sw.defaultEquipment.slice():[],
      equipmentAccess:duplicateWarriorEquipmentAccess(sw,f),
      description:sw.description||''
    };
    customFighterList().push(item);
    cw.fighterIds.push(item.customFighterId);
    cw.fighterRefs.push(`custom:${item.customFighterId}`);
  });
  save(true);
  closeModal();
  customArea='warband';customContentTab='warband';customWarbandEditId=cw.id;customWarbandCreating=false;customWarbandSection='fighters';
  render('custom');
  const extra=cw.traitIds.length+cw.specialRuleIds.length+treeNameMap.size+domainNameMap.size;
  toast(en?`Duplicated — ${(f.warriors||[]).length} fighters${extra?` + ${extra} band rules/skill trees/magic domains`:''} copied, ready to edit`:`Dupliquée — ${(f.warriors||[]).length} combattants${extra?` + ${extra} règles/arbres/domaines de bande`:''} copiés, prêts à modifier`);
}
function customWarbandList(){
  if(!Array.isArray(state.customWarbands))state.customWarbands=[];
  return state.customWarbands
}
function customWarbandById(id){return customWarbandList().find(x=>x.id===id)||null}
function customWarbandFighterEntries(){
  const out=[];
  const seen=new Set();
  (D.factions||[]).forEach(f=>{
    (f.warriors||[]).forEach(w=>{
      const key=`official:${f.id}:${w.id}`;
      if(seen.has(key))return;
      seen.add(key);
      out.push({key,factionId:f.id,factionName:f.displayName||f.name||f.id,warrior:w,custom:false});
    });
  });
  customFighterList().forEach(w=>{
    const key=`custom:${w.customFighterId}`;
    if(seen.has(key))return;
    seen.add(key);
    out.push({key,factionId:'custom',factionName:'Custom',warrior:customFighterAsWarrior(w),custom:true,customFighterId:w.customFighterId});
  });
  return out;
}
function customWarbandEquipmentEntries(){
  const out=[];
  const seen=new Set();
  (D.weapons||[]).forEach(w=>{
    const key=`official:${w.name}`;
    if(seen.has(key))return;
    seen.add(key);
    out.push({key,equipment:w,custom:false});
  });
  allCustomEquipmentList().forEach(w=>{
    const key=`custom:${w.customEquipmentId}`;
    if(seen.has(key))return;
    seen.add(key);
    out.push({key,equipment:w,custom:true});
  });
  return out;
}
function customWarbandFighterRefs(cw){
  const base=Array.isArray(cw?.fighterRefs)?cw.fighterRefs:(cw?.fighterIds||[]).map(id=>`custom:${id}`);
  // V-WARBANDROSTER: a fighter whose own "Warband" field IS this warband
  // (customWarbandId===cw.id) is exclusively its — always union it in
  // rather than trust fighterRefs alone. This also repairs, on read, any
  // fighter that predates the fighterRefs sync fix in saveCustomFighter
  // (created with this warband selected, but never actually added to
  // fighterRefs) without a separate migration pass.
  if(!cw?.id)return base;
  const set=new Set(base);
  customFighterList().forEach(w=>{if(w.customWarbandId===cw.id)set.add(`custom:${w.customFighterId}`)});
  return [...set];
}
function customWarbandEquipmentRefs(cw){
  if(Array.isArray(cw?.equipmentRefs))return cw.equipmentRefs;
  return (cw?.equipmentIds||[]).map(id=>`custom:${id}`);
}
function customWarbandWarriors(cw){
  const refs=new Set(customWarbandFighterRefs(cw));
  return customWarbandFighterEntries().filter(e=>refs.has(e.key)).map(e=>{
    if(e.custom)return e.warrior;
    return customFighterAsWarrior({
      ...e.warrior,
      id:`custom-warband-fighter-${cw.id}-${e.factionId}-${e.warrior.id}`,
      customFighterId:null,
      factionId:e.factionId,
      sourceFactionId:e.factionId,
      sourceWarriorId:e.warrior.id
    });
  });
}
function customWarbandEquipmentObjects(cw){
  const refs=new Set(customWarbandEquipmentRefs(cw));
  return customWarbandEquipmentEntries().filter(e=>refs.has(e.key)).map(e=>e.equipment);
}
function newCustomWarband(){customWarbandEditId=null;customWarbandCreating=true;customWarbandSection='fighters';render('custom');setTimeout(()=>$('#cwName')?.focus(),0)}
function editCustomWarband(id){if(!customWarbandById(id))return;customWarbandEditId=id;customWarbandCreating=false;customWarbandSection='fighters';render('custom')}
function deleteCustomWarband(id){const en=siteLanguage==='en';const cw=customWarbandById(id);if(!cw)return;openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'DELETE':'SUPPRESSION'}</div><h2>${en?'Delete “':'Supprimer « '}${esc(cw.name)}${en?'”?':' » ?'}</h2><button type="button" class="big-delete" onclick="confirmDeleteCustomWarband('${id}')">${en?'DELETE':'SUPPRIMER'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`)}
// V-ORPHANFIGHTERS: retroactive cleanup for fighters already left dangling by
// a custom warband deleted BEFORE the fix in confirmDeleteCustomWarband below
// existed — a fighter whose customWarbandId points at a warband that no
// longer exists in customWarbandList(). customFighterRow can't resolve that
// id to a name, so its origin label falls through to '—': exactly the
// unlabeled "ghost" profiles cluttering Custom > Combattants. Never touches
// a fighter that's been individually officialized (officialWarbandId set) —
// that's still the live editable source for published content regardless of
// what happened to the custom warband record.
function orphanCustomFighterIds(){
  const liveIds=new Set(customWarbandList().map(cw=>cw.id));
  return customFighterList().filter(w=>w.customWarbandId&&!liveIds.has(w.customWarbandId)&&!w.officialWarbandId).map(w=>w.customFighterId);
}
function cleanupOrphanCustomFighters(){
  const en=siteLanguage==='en';
  const ids=orphanCustomFighterIds();
  if(!ids.length){toast(en?'No orphan profile to clean up':'Aucun profil orphelin à nettoyer');return}
  const names=ids.map(id=>customFighterById(id)?.name||id).slice(0,12);
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'CLEANUP':'NETTOYAGE'}</div><h2>${en?`Delete ${ids.length} orphan profile${ids.length>1?'s':''}?`:`Supprimer ${ids.length} profil${ids.length>1?'s':''} orphelin${ids.length>1?'s':''} ?`}</h2><p>${en?'These custom fighters belonged to a warband that was already deleted and no longer serve any purpose.':'Ces combattants custom appartenaient à une warband déjà supprimée et ne servent plus à rien.'}</p><div class="muted" style="text-align:left;margin:10px 0;max-height:160px;overflow:auto">${names.map(n=>esc(n)).join('<br>')}${ids.length>names.length?`<br>… +${ids.length-names.length}`:''}</div><button type="button" class="big-delete" onclick="confirmCleanupOrphanCustomFighters()">${en?'DELETE':'SUPPRIMER'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`);
}
function confirmCleanupOrphanCustomFighters(){
  const en=siteLanguage==='en';
  const ids=orphanCustomFighterIds();
  ids.forEach(id=>markDeleted('customFighters',id));
  state.customFighters=customFighterList().filter(w=>!ids.includes(w.customFighterId));
  save(true);closeModal();render('custom');
  toast(en?`${ids.length} orphan profile${ids.length>1?'s':''} deleted`:`${ids.length} profil${ids.length>1?'s':''} orphelin${ids.length>1?'s':''} supprimé${ids.length>1?'s':''}`);
}
// V-CUSTOMCLEANUP: two library-wide cleanups next to the orphan one.
// Both only ever touch this account's LOCAL Custom copies (state.custom*):
// published/official content lives in its own server-side definition and is
// only written by an explicit Officialize / Publish / Admin save, never by
// these, so what is online stays exactly as it is.
const CUSTOM_CLEANUP_KINDS=[
  {tab:'fighters',stateKey:'customFighters',idKey:'customFighterId',list:()=>customFighterList()},
  {tab:'equipment',stateKey:'customEquipment',idKey:'customEquipmentId',list:()=>customEquipmentList()},
  {tab:'creatures',stateKey:'customCreatures',idKey:'customCreatureId',list:()=>customCreatureList()},
  {tab:'traits',stateKey:'customTraits',idKey:'customContentId',list:()=>customContentList('traits')},
  {tab:'skills',stateKey:'customSkills',idKey:'customContentId',list:()=>customContentList('skills')},
  {tab:'spells',stateKey:'customSpells',idKey:'customContentId',list:()=>customContentList('spells')},
  {tab:'special',stateKey:'customSpecialRules',idKey:'customContentId',list:()=>customContentList('special')}
];
const CUSTOM_CLEANUP_VOLATILE=new Set(['customFighterId','customEquipmentId','customCreatureId','customContentId','updatedAt','archived','officialWarbandId']);
function customCleanupSignature(x){const o={};Object.keys(x||{}).sort().forEach(k=>{if(!CUSTOM_CLEANUP_VOLATILE.has(k))o[k]=x[k]});return JSON.stringify(o)}
function customRosterFighterIds(){const ids=new Set();(state.rosters||[]).forEach(r=>(r.fighters||[]).forEach(x=>{if(x?.customFighterId)ids.add(x.customFighterId)}));return ids}
// Exact copies only (same name AND same content), e.g. from importing or
// duplicating twice. Per group, the copy that is published, else used by a
// warband/roster, else the first one is kept; references to the removed
// copies are re-pointed to it.
function customDuplicatePlan(){
  const official={fighters:officializedFighterIdSet(),equipment:officializedEquipmentIdSet(),...officializedContentIdSets()};
  const used=new Set();customWarbandList().forEach(cw=>['fighterIds','equipmentIds','specialRuleIds','traitIds'].forEach(k=>(cw[k]||[]).forEach(id=>used.add(id))));
  customRosterFighterIds().forEach(id=>used.add(id));
  const plan=[];
  CUSTOM_CLEANUP_KINDS.forEach(k=>{
    const groups=new Map();
    k.list().forEach(x=>{const sig=customCleanupSignature(x);if(!groups.has(sig))groups.set(sig,[]);groups.get(sig).push(x)});
    groups.forEach(g=>{
      if(g.length<2)return;
      const off=official[k.tab]||new Set();
      const keep=g.find(x=>off.has(x[k.idKey]))||g.find(x=>used.has(x[k.idKey]))||g[0];
      g.forEach(x=>{if(x!==keep&&!off.has(x[k.idKey]))plan.push({kind:k,id:x[k.idKey],keepId:keep[k.idKey],name:x.name||'—'})});
    });
  });
  return plan;
}
// What is live online (merged official warbands), to recognise a local copy
// of something already published even when its local "published" link is
// gone (e.g. its published warband's local copy was deleted earlier).
// Each set also has a .origin Map (key → official warband id) so a kept
// local copy can be re-linked to the warband it is published in.
function customOnlineSets(){
  const out={};['fighters','equipment','traits','skills','spells','special','trees','domains'].forEach(k=>{out[k]=new Set();out[k].origin=new Map()});
  const add=(k,key,oid)=>{if(!key)return;out[k].add(key);if(!out[k].origin.has(key))out[k].origin.set(key,oid)};
  (D.factions||[]).forEach(f=>{if(!f.__official)return;const oid=String(f.id||'').replace(/^official-/,'');
    (f.warriors||[]).forEach(w=>add('fighters',w?.customFighterId,oid));
    (f.equipment||[]).forEach(w=>add('equipment',w?.customEquipmentId,oid));
    (f.traits||[]).forEach(t=>add('traits',normName(t?.name),oid));
    (f.skills||[]).forEach(t=>add('skills',normName(t?.name),oid));
    (f.spells||[]).forEach(t=>add('spells',normName(t?.name),oid));
    (f.specialRules||[]).forEach(t=>add('special',normName(t?.name),oid));
    Object.keys(f.exclusiveSkillSets||{}).forEach(k=>add('trees',normName(k),oid));
    Object.keys(f.exclusiveMagicDomains||{}).forEach(k=>add('domains',normName(k),oid));
  });
  ['traits','skills','spells','special'].forEach(c=>(RULES.categories[c]||[]).forEach(e=>{if(e.__official)add(c,normName(e.name),null)}));
  return out;
}
// Local copies of content that is live online count as officialized for the
// Custom library (they go to the OFFICIALIZED folder instead of looking like
// unpublished work), even when their local "published" link was lost.
function customOnlineCopyIds(tab){
  const on=customOnlineSets()[tab];if(!on)return [];
  if(tab==='fighters')return customFighterList().filter(w=>on.has(w.customFighterId)).map(w=>w.customFighterId);
  if(tab==='equipment')return customEquipmentList().filter(w=>on.has(w.customEquipmentId)).map(w=>w.customEquipmentId);
  return customContentList(tab).filter(x=>on.has(normName(x.name))).map(x=>x.customContentId);
}
function customPublishedPlan(){
  const online=customOnlineSets();
  const rosterCw=new Set((state.rosters||[]).map(r=>r.customWarbandId).filter(Boolean));
  const rosterFighters=customRosterFighterIds();
  const all=customWarbandList();
  // Only a warband whose official version is actually live (published, so
  // merged into D.factions) counts: one sent back to draft/archived online
  // keeps its local copy, the only one players could get it back from.
  const liveOfficial=new Set((D.factions||[]).filter(f=>f.__official).map(f=>String(f.id||'').replace(/^official-/,'')));
  const cws=all.filter(cw=>cw.officialId&&liveOfficial.has(String(cw.officialId))&&!rosterCw.has(cw.id));
  const remaining=all.filter(cw=>!cws.includes(cw));
  // Anything a warband that stays (not published, or still used by a
  // roster) relies on is kept, so that warband keeps working.
  const keepIds=new Set(),keepNames={equipment:new Set(),traits:new Set(),skills:new Set(),spells:new Set(),special:new Set()};
  remaining.forEach(cw=>{
    ['fighterIds','equipmentIds','specialRuleIds','traitIds'].forEach(k=>(cw[k]||[]).forEach(id=>keepIds.add(id)));
    let b;try{b=bundleCustomContentForOfficialize(cw,customWarbandFaction(cw))}catch(e){return}
    (b.equipment||[]).forEach(e=>keepNames.equipment.add(normName(e.name)));
    (b.traits||[]).forEach(e=>keepNames.traits.add(normName(e.name)));
    (b.skills||[]).forEach(e=>keepNames.skills.add(normName(e.name)));
    (b.spells||[]).forEach(e=>keepNames.spells.add(normName(e.name)));
    (b.specialRules||[]).forEach(e=>keepNames.special.add(normName(e.name)));
  });
  const official={fighters:officializedFighterIdSet(),equipment:officializedEquipmentIdSet(),...officializedContentIdSets()};
  // Which published warband each published item came with, so an item that
  // has to stay (still used elsewhere) keeps its published status once that
  // warband's local copy is gone, instead of popping back into the list.
  const origin=new Map();
  cws.forEach(cw=>{
    ['fighterIds','equipmentIds','specialRuleIds','traitIds'].forEach(k=>(cw[k]||[]).forEach(id=>{if(!origin.has(id))origin.set(id,cw.officialId)}));
    let b;try{b=bundleCustomContentForOfficialize(cw,customWarbandFaction(cw))}catch(e){return}
    const byName=(tab,list)=>(list||[]).forEach(e=>{const k=CUSTOM_CLEANUP_KINDS.find(q=>q.tab===tab);const x=k&&k.list().find(q=>normName(q.name)===normName(e.name));if(x&&!origin.has(x[k.idKey]))origin.set(x[k.idKey],cw.officialId)});
    byName('equipment',b.equipment);byName('traits',b.traits);byName('skills',b.skills);byName('spells',b.spells);byName('special',b.specialRules);
  });
  const items=[],flag=[],kept=[];
  CUSTOM_CLEANUP_KINDS.forEach(k=>{
    const off=official[k.tab];if(!off)return;
    k.list().forEach(x=>{const id=x[k.idKey];
      const isOnline=k.tab==='fighters'||k.tab==='equipment'?online[k.tab].has(id):(online[k.tab]&&online[k.tab].has(normName(x.name)));
      if(!off.has(id)&&!isOnline)return;
      const keep=keepIds.has(id)||(k.tab==='fighters'&&rosterFighters.has(id))||(keepNames[k.tab]&&keepNames[k.tab].has(normName(x.name)))
        // A published item that belongs to a published warband still kept
        // locally (used by a roster) stays with it.
        ||(k.tab==='fighters'&&x.customWarbandId&&all.some(cw=>cw.id===x.customWarbandId&&!cws.includes(cw)));
      const onlineOid=k.tab==='fighters'||k.tab==='equipment'?online[k.tab]?.origin.get(id):online[k.tab]?.origin.get(normName(x.name));
      if(keep){if(!x.officialWarbandId&&(origin.get(id)||onlineOid))flag.push({kind:k,id,officialId:origin.get(id)||onlineOid});kept.push(`${customCleanupTypeLabel(k.tab)} · ${x.name||'—'}`);return}
      items.push({kind:k,id,name:x.name||'—'})});
  });
  // Trees/domains: published as a whole, or left with nothing but deleted
  // entries, and not offered by a profile that stays.
  const delIds=new Set(items.map(x=>x.id));
  const parents=[];
  [['skills','skillAccess'],['spells','magicAccess']].forEach(([kind,acc])=>{
    const list=kind==='skills'?customSkillTreeList():customMagicDomainList();
    list.forEach(pt=>{
      const its=customBuilderItems(kind,pt);
      const left=its.filter(x=>!delIds.has(x.customContentId));
      const live=(kind==='skills'?online.trees:online.domains).has(normName(pt.name));
      const goes=(pt.officialWarbandId||live)?!left.length:(its.length>0&&!left.length);
      if(!goes)return;
      const n=normName(pt.name);
      const offered=customFighterList().some(w=>!delIds.has(w.customFighterId)&&!official.fighters.has(w.customFighterId)&&Object.keys(w?.[acc]||{}).some(q=>normName(q)===n));
      if(offered)return;
      parents.push({kind,id:pt.id,name:pt.name});
    });
  });
  return {cws,items,parents,flag,kept};
}
// V-CUSTOMUNUSED: everything local Custom content is referenced by — custom
// warbands (their full officialize bundle: fighters' default/accessible
// equipment, skill trees, magic domains, rules), standalone custom
// fighters, choice options, and the fighters of every roster. Names are
// normalised; ids cover what is linked by id.
function customUsageIndex(){
  const names={equipment:new Set(),traits:new Set(),skills:new Set(),spells:new Set(),special:new Set(),trees:new Set(),domains:new Set()};
  const ids=new Set();
  const addBundle=b=>{(b.equipment||[]).forEach(e=>names.equipment.add(normName(e.name)));(b.traits||[]).forEach(e=>names.traits.add(normName(e.name)));(b.skills||[]).forEach(e=>names.skills.add(normName(e.name)));(b.spells||[]).forEach(e=>names.spells.add(normName(e.name)));(b.specialRules||[]).forEach(e=>names.special.add(normName(e.name)))};
  const addAccess=w=>{Object.keys(w?.skillAccess||{}).forEach(k=>names.trees.add(normName(k)));Object.keys(w?.magicAccess||{}).forEach(k=>names.domains.add(normName(k)))};
  customWarbandList().forEach(cw=>{
    ['fighterIds','equipmentIds','specialRuleIds','traitIds'].forEach(k=>(cw[k]||[]).forEach(id=>ids.add(id)));
    try{addBundle(bundleCustomContentForOfficialize(cw,customWarbandFaction(cw)))}catch(e){}
    (cw.choices?.groups||[]).forEach(g=>(g.options||[]).forEach(o=>{[...(o.ruleNames||[]),...(o.recruitRuleNames||[])].forEach(n=>names.special.add(normName(n)));(o.magicDomains||[]).forEach(n=>names.domains.add(normName(n)))}));
  });
  const fighters=customFighterList();
  fighters.forEach(addAccess);
  try{const fx={id:'custom-all',warriors:fighters.map(w=>customFighterAsWarrior(w)),equipment:[]};addBundle(bundleCustomContentForOfficialize({id:'custom-all',specialRuleIds:[],traitIds:[]},fx))}catch(e){}
  (state.rosters||[]).forEach(r=>(r.fighters||[]).forEach(x=>{
    if(x?.customFighterId)ids.add(x.customFighterId);
    [...(x.skills||[])].forEach(n=>names.skills.add(normName(typeof n==='string'?n:n?.name)));
    [...(x.spells||[])].forEach(n=>names.spells.add(normName(typeof n==='string'?n:n?.name)));
    [...(x.extraRuleNames||[]),...(x.rules||[]),...(x.specialRules||[])].forEach(n=>names.special.add(normName(typeof n==='string'?n:n?.name)));
    [...(x.equipmentSelected||[]),...(x.equipmentStash||[])].forEach(e=>names.equipment.add(normName(e?.name)));
    (x.unlockedMagicDomains||[]).forEach(n=>names.domains.add(normName(n)));
  }));
  // Equipment that stays keeps its own traits.
  customEquipmentList().forEach(e=>{if(names.equipment.has(normName(e.name))||ids.has(e.customEquipmentId)){[e.profile?.traits,e.traits,...(Array.isArray(e.profiles)?e.profiles.map(q=>q?.traits):[])].flatMap(t=>Array.isArray(t)?t:String(t||'').split(',')).forEach(n=>{n=String(n||'').replace(/\s*\(.*$/,'').trim();if(n)names.traits.add(normName(n))})}});
  return {names,ids};
}
// Unused + not published: candidates for "Remove unused items". Fighters
// and creatures are left out on purpose (a profile is a creation in itself).
function customUnusedPlan(){
  const u=customUsageIndex();
  const official={equipment:officializedEquipmentIdSet(),...officializedContentIdSets()};
  const items=[];
  CUSTOM_CLEANUP_KINDS.filter(k=>['equipment','traits','skills','spells','special'].includes(k.tab)).forEach(k=>{
    k.list().forEach(x=>{const id=x[k.idKey];if(official[k.tab]?.has(id)||u.ids.has(id))return;
      if(u.names[k.tab].has(normName(x.name)))return;
      if(k.tab==='skills'&&u.names.trees.has(normName(x.tree||'')))return;
      if(k.tab==='spells'&&u.names.domains.has(normName(x.domain||'')))return;
      items.push({kind:k,id,name:x.name||'—',place:x.tree||x.domain||''})});
  });
  const del=new Set(items.map(x=>x.id));const parents=[];
  [['skills','trees'],['spells','domains']].forEach(([kind,nk])=>{
    (kind==='skills'?customSkillTreeList():customMagicDomainList()).forEach(pt=>{
      if(pt.officialWarbandId||u.names[nk].has(normName(pt.name)))return;
      if(customBuilderItems(kind,pt).every(x=>del.has(x.customContentId)))parents.push({kind,id:pt.id,name:pt.name});
    });
  });
  return {items,parents};
}
function cleanupCustomUnused(){
  const en=siteLanguage==='en';const p=customUnusedPlan();const n=p.items.length+p.parents.length;
  if(!n){toast(en?'No unused item':'Aucun élément inutilisé');return}
  const row=(val,label)=>`<label class="cwc-check" style="display:flex;gap:6px;text-align:left"><input type="checkbox" class="cuPick" value="${esc(val)}" checked> ${esc(label)}</label>`;
  const rows=[...p.parents.map(x=>row(`p:${x.kind}:${x.id}`,`${x.kind==='skills'?(en?'Skill tree':'Arbre de compétences'):(en?'Magic domain':'Domaine de magie')} · ${x.name}`)),...p.items.map(x=>row(`i:${x.kind.tab}:${x.id}`,`${customCleanupTypeLabel(x.kind.tab)} · ${x.name}${x.place?` (${x.place})`:''}`))];
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'CLEANUP':'NETTOYAGE'}</div><h2>${en?`Remove unused items?`:`Supprimer les éléments inutilisés ?`}</h2><p>${en?'Not published, and used by none of your custom warbands, custom profiles, choices or warbands. Untick what you want to keep (e.g. something you just created). Only local Custom data is changed.':'Ni publiés, ni utilisés par tes warbands custom, tes profils custom, tes choix ou tes bandes. Décoche ce que tu veux garder (par ex. une création toute récente). Seules tes données Custom locales changent.'}</p><div style="max-height:260px;overflow:auto;margin:10px 0;display:grid;gap:4px">${rows.join('')}</div><button type="button" class="big-delete" onclick="confirmCleanupCustomUnused()">${en?'DELETE SELECTED':'SUPPRIMER LA SÉLECTION'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`);
}
function confirmCleanupCustomUnused(){
  const en=siteLanguage==='en';
  const picked=[...document.querySelectorAll('.cuPick:checked')].map(i=>i.value);
  const p=customUnusedPlan();
  const items=p.items.filter(x=>picked.includes(`i:${x.kind.tab}:${x.id}`));
  const parents=p.parents.filter(x=>picked.includes(`p:${x.kind}:${x.id}`));
  // A tree/domain only goes if none of its entries were unticked.
  const keptItems=new Set(p.items.filter(x=>!items.includes(x)).map(x=>x.id));
  const goParents=parents.filter(pt=>customBuilderItems(pt.kind,(pt.kind==='skills'?customSkillTreeById(pt.id):customMagicDomainById(pt.id))).every(x=>!keptItems.has(x.customContentId)));
  items.forEach(x=>markDeleted(x.kind.stateKey,x.id));
  CUSTOM_CLEANUP_KINDS.forEach(k=>{const del=new Set(items.filter(x=>x.kind===k).map(x=>x.id));if(del.size)state[k.stateKey]=k.list().filter(x=>!del.has(x[k.idKey]))});
  goParents.forEach(pt=>{const key=pt.kind==='skills'?'customSkillTrees':'customMagicDomains';markDeleted(key,pt.id);state[key]=(pt.kind==='skills'?customSkillTreeList():customMagicDomainList()).filter(x=>x.id!==pt.id)});
  const n=items.length+goParents.length;
  save(true);closeModal();render('custom');
  toast(en?`${n} unused item${n>1?'s':''} removed`:`${n} élément${n>1?'s':''} inutilisé${n>1?'s':''} supprimé${n>1?'s':''}`);
}
// V-CUSTOMCOMPARE: "is my Custom content really online?" Fetches the live
// official warbands (published only, what every player gets) and, for an
// admin, every official warband with its status, then sorts each local
// Custom item into: live online / only in an official warband that is not
// published (draft) / online but with a different text / not published at
// all. Read-only: nothing is changed, locally or online.
function cmpNorm(t){return String(t||'').replace(/\s+/g,' ').trim()}
async function openCustomCompare(){
  const en=siteLanguage==='en';
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'COMPARE':'COMPARAISON'}</div><h2>${en?'Comparing with what is online…':'Comparaison avec le contenu en ligne…'}</h2></div>`);
  let live=[],adminRows=null;const full=new Map();
  try{const r=await window.MordheimundaAPI.officialWarbands();live=Array.isArray(r?.warbands)?r.warbands:[]}catch(e){}
  if(isAdminSession()){try{const r=await window.MordheimundaAPI.adminListWarbands();adminRows=Array.isArray(r?.warbands)?r.warbands:(Array.isArray(r)?r:null)}catch(e){}}
  const liveIds=new Set(live.map(w=>String(w.id||'').replace(/^official-/,'')));
  live.forEach(w=>full.set(String(w.id||'').replace(/^official-/,''),{name:w.displayName||w.name,status:'published',def:w}));
  if(adminRows){for(const row of adminRows){const id=String(row.id);if(full.has(id)){full.get(id).status=row.status||'published';continue}
    try{const r=await window.MordheimundaAPI.adminGetWarband(id);const w=r?.warband||r;full.set(id,{name:row.name,status:row.status||'draft',def:w?.definition||w||{}})}catch(e){full.set(id,{name:row.name,status:row.status||'draft',def:{}})}}}
  const idx={fighters:new Map(),equipment:new Map(),traits:new Map(),skills:new Map(),spells:new Map(),special:new Map(),trees:new Map(),domains:new Map()};
  const put=(k,key,id,text)=>{if(!key)return;const a=idx[k].get(key)||[];a.push({id,text});idx[k].set(key,a)};
  full.forEach((w,id)=>{const d=w.def||{};
    (d.warriors||[]).forEach(x=>put('fighters',x?.customFighterId,id));
    (d.equipment||[]).forEach(x=>put('equipment',x?.customEquipmentId,id));
    (d.traits||[]).forEach(x=>put('traits',normName(x?.name),id,x?.text));
    (d.skills||[]).forEach(x=>put('skills',normName(x?.name),id,x?.text));
    (d.spells||[]).forEach(x=>put('spells',normName(x?.name),id,x?.text));
    (d.specialRules||[]).forEach(x=>put('special',normName(x?.name),id,x?.text));
    (d.skillTrees||[]).forEach(x=>put('trees',normName(x?.name||x),id));
    (d.magicDomains||[]).forEach(x=>put('domains',normName(x?.name||x),id));
  });
  const usedBy=item=>customWarbandList().filter(cw=>{try{const b=bundleCustomContentForOfficialize(cw,customWarbandFaction(cw));return [...(b.equipment||[]),...(b.traits||[]),...(b.skills||[]),...(b.spells||[]),...(b.specialRules||[])].some(e=>normName(e.name)===normName(item))||customWarbandWarriors(cw).some(w=>normName(w.name)===normName(item))}catch(e){return false}}).map(cw=>cw.name);
  const groups={live:[],draft:[],diff:[],none:[]};
  const sortItem=(label,name,hits,localText)=>{
    const liveHits=(hits||[]).filter(h=>liveIds.has(h.id));
    const row=`${label} · ${name}`;
    if(liveHits.length){if(localText!=null&&liveHits.every(h=>h.text!=null&&cmpNorm(h.text)!==cmpNorm(localText)))groups.diff.push(`${row} — ${liveHits.map(h=>full.get(h.id)?.name).join(', ')}`);else groups.live.push(row);return}
    if((hits||[]).length){groups.draft.push(`${row} — ${hits.map(h=>`${full.get(h.id)?.name} (${full.get(h.id)?.status})`).join(', ')}`);return}
    const u=usedBy(name);groups.none.push(`${row}${u.length?` — ${en?'used by':'utilisé par'} ${u.join(', ')}`:''}`);
  };
  customFighterList().forEach(w=>sortItem(customCleanupTypeLabel('fighters'),w.name,idx.fighters.get(w.customFighterId),null));
  customEquipmentList().forEach(w=>sortItem(customCleanupTypeLabel('equipment'),w.name,idx.equipment.get(w.customEquipmentId),null));
  ['traits','skills','spells','special'].forEach(k=>customContentList(k).forEach(x=>sortItem(customCleanupTypeLabel(k),x.name,idx[k].get(normName(x.name)),x.text||'')));
  customSkillTreeList().forEach(t=>sortItem(en?'Skill tree':'Arbre de compétences',t.name,idx.trees.get(normName(t.name)),null));
  customMagicDomainList().forEach(t=>sortItem(en?'Magic domain':'Domaine de magie',t.name,idx.domains.get(normName(t.name)),null));
  const cwRows=customWarbandList().map(cw=>{const o=cw.officialId?full.get(String(cw.officialId)):null;
    const st=!cw.officialId?(en?'not officialized':'non officialisée'):!o?(adminRows?(en?'⚠ officialized here but NOT FOUND online (deleted?)':'⚠ officialisée ici mais INTROUVABLE en ligne (supprimée ?)'):(en?'not live (draft/archived, or deleted)':'pas en ligne (brouillon/archivée, ou supprimée)')):o.status==='published'?(en?'✓ live':'✓ en ligne'):`⚠ ${o.status} — ${en?'not visible to players':'invisible pour les joueurs'}`;
    return `${cw.name} — ${st}`});
  const sec=(title,rows,open)=>`<details class="custom-collapse"${open?' open':''} style="text-align:left"><summary><span>${title}</span><small>${rows.length}</small></summary>${rows.length?customCleanupListMarkup(rows):`<p class="muted">—</p>`}</details>`;
  openModal(`<div class="delete-dialog" style="text-align:left"><div class="eyebrow">${en?'COMPARE · READ ONLY':'COMPARAISON · LECTURE SEULE'}</div><h2>${en?'Your Custom library vs online':'Ta bibliothèque Custom vs en ligne'}</h2><p class="muted">${en?`${liveIds.size} published official warband${liveIds.size>1?'s':''} online`:`${liveIds.size} warband${liveIds.size>1?'s':''} officielle${liveIds.size>1?'s':''} publiée${liveIds.size>1?'s':''} en ligne`}${adminRows?` · ${full.size-liveIds.size} ${en?'not published (draft/archived)':'non publiée(s) (brouillon/archivée)'}`:''}. ${en?'Nothing is changed.':'Rien n’est modifié.'}</p>
   ${sec(en?'Your custom warbands':'Tes warbands custom',cwRows,true)}
   ${sec(en?'⚠ Online but with a different text':'⚠ En ligne mais avec un texte différent',groups.diff,true)}
   ${sec(en?'⚠ Only in an official warband that is not published':'⚠ Seulement dans une warband officielle non publiée',groups.draft,true)}
   ${sec(en?'Not published (only on your account)':'Non publiés (seulement sur ton compte)',groups.none,true)}
   ${sec(en?'✓ Live online':'✓ En ligne',groups.live,false)}
   <button type="button" class="button secondary full" onclick="closeModal()">${en?'Close':'Fermer'}</button></div>`);
}
function customCleanupButtonsMarkup(){
  const en=siteLanguage==='en';let dup=0,pub=0;
  try{dup=customDuplicatePlan().length}catch(e){}
  try{const p=customPublishedPlan();pub=p.cws.length+p.items.length+p.parents.length}catch(e){}
  let unused=0;try{const p=customUnusedPlan();unused=p.items.length+p.parents.length}catch(e){}
  return `<button class="button secondary" type="button" onclick="openCustomCompare()">🔍 ${en?'Compare with online':'Comparer avec le publié'}</button>`+(dup?`<button class="button secondary" type="button" onclick="cleanupCustomDuplicates()">🧹 ${en?`Remove ${dup} duplicate${dup>1?'s':''}`:`Supprimer ${dup} doublon${dup>1?'s':''}`}</button>`:'')
    +(pub?`<button class="button secondary" type="button" onclick="cleanupCustomPublished()">🧹 ${en?`Remove ${pub} published local cop${pub>1?'ies':'y'}`:`Supprimer ${pub} copie${pub>1?'s':''} locale${pub>1?'s':''} officialisée${pub>1?'s':''}`}</button>`:'')
    +(unused?`<button class="button secondary" type="button" onclick="cleanupCustomUnused()">🧹 ${en?`Remove unused items (${unused})`:`Supprimer les éléments inutilisés (${unused})`}</button>`:'');
}
function customCleanupListMarkup(rows){
  const en=siteLanguage==='en';const max=40;
  return `<ul class="muted" style="text-align:left;max-height:200px;overflow:auto;margin:10px 0;padding-left:18px">${rows.slice(0,max).map(r=>`<li>${esc(r)}</li>`).join('')}${rows.length>max?`<li>${en?`… and ${rows.length-max} more`:`… et ${rows.length-max} autres`}</li>`:''}</ul>`;
}
function customCleanupTypeLabel(tab){const en=siteLanguage==='en';const m={fighters:en?'Fighter':'Profil',equipment:en?'Equipment':'Équipement',creatures:en?'Creature':'Créature',traits:'Trait',skills:en?'Skill':'Compétence',spells:en?'Spell':'Sort',special:en?'Special rule':'Règle spéciale'};return m[tab]||tab}
function cleanupCustomDuplicates(){
  const en=siteLanguage==='en';const plan=customDuplicatePlan();
  if(!plan.length){toast(en?'No duplicate to remove':'Aucun doublon à supprimer');return}
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'CLEANUP':'NETTOYAGE'}</div><h2>${en?`Remove ${plan.length} duplicate${plan.length>1?'s':''}?`:`Supprimer ${plan.length} doublon${plan.length>1?'s':''} ?`}</h2><p>${en?'Exact copies (same name and same content). One copy of each is kept, and warbands using a removed copy are switched to the kept one. Nothing published online is changed.':'Copies identiques (même nom et même contenu). Une copie de chaque est gardée, et les warbands qui utilisaient une copie supprimée passent sur celle gardée. Rien de ce qui est en ligne n’est modifié.'}</p>${customCleanupListMarkup(plan.map(x=>`${customCleanupTypeLabel(x.kind.tab)} · ${x.name}`))}<button type="button" class="big-delete" onclick="confirmCleanupCustomDuplicates()">${en?'DELETE':'SUPPRIMER'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`);
}
function confirmCleanupCustomDuplicates(){
  const en=siteLanguage==='en';const plan=customDuplicatePlan();
  const remap=new Map(plan.map(x=>[x.id,x.keepId]));
  const swap=arr=>Array.isArray(arr)?[...new Set(arr.map(id=>remap.get(id)||id))]:arr;
  const swapRef=arr=>Array.isArray(arr)?[...new Set(arr.map(r=>typeof r==='string'&&r.startsWith('custom:')&&remap.has(r.slice(7))?'custom:'+remap.get(r.slice(7)):r))]:arr;
  customWarbandList().forEach(cw=>{['fighterIds','equipmentIds','specialRuleIds','traitIds'].forEach(k=>{if(cw[k])cw[k]=swap(cw[k])});['fighterRefs','equipmentRefs'].forEach(k=>{if(cw[k])cw[k]=swapRef(cw[k])})});
  (state.rosters||[]).forEach(r=>(r.fighters||[]).forEach(x=>{if(x?.customFighterId&&remap.has(x.customFighterId))x.customFighterId=remap.get(x.customFighterId)}));
  plan.forEach(x=>markDeleted(x.kind.stateKey,x.id));
  CUSTOM_CLEANUP_KINDS.forEach(k=>{const del=new Set(plan.filter(x=>x.kind===k).map(x=>x.id));if(del.size)state[k.stateKey]=k.list().filter(x=>!del.has(x[k.idKey]))});
  save(true);closeModal();render('custom');
  toast(en?`${plan.length} duplicate${plan.length>1?'s':''} removed`:`${plan.length} doublon${plan.length>1?'s':''} supprimé${plan.length>1?'s':''}`);
}
function cleanupCustomPublished(){
  const en=siteLanguage==='en';const p=customPublishedPlan();const n=p.cws.length+p.items.length+p.parents.length;
  if(!n){toast(en?'No published local copy to remove':'Aucune copie locale officialisée à supprimer');return}
  const rows=[...p.cws.map(cw=>`Warband · ${cw.name}`),...p.parents.map(x=>`${x.kind==='skills'?(en?'Skill tree':'Arbre de compétences'):(en?'Magic domain':'Domaine de magie')} · ${x.name}`),...p.items.map(x=>`${customCleanupTypeLabel(x.kind.tab)} · ${x.name}`)];
  openModal(`<div class="delete-dialog"><div class="eyebrow">${en?'CLEANUP':'NETTOYAGE'}</div><h2>${en?`Remove ${n} published local cop${n>1?'ies':'y'}?`:`Supprimer ${n} copie${n>1?'s':''} locale${n>1?'s':''} officialisée${n>1?'s':''} ?`}</h2><p>${en?'Only the copies kept in your Custom library are removed. <b>The published versions stay online, unchanged, for every player</b>, and remain editable in Admin → Manage. You will no longer be able to re-publish them from Custom (★ / Publish changes). Anything an unpublished creation or one of your warbands still uses is kept.':'Seules les copies gardées dans ta bibliothèque Custom sont supprimées. <b>Les versions officialisées restent en ligne, inchangées, pour tous les joueurs</b>, et restent modifiables dans Admin → Gestion. Tu ne pourras plus les republier depuis Custom (★ / Publier les modifications). Tout ce qu’une création non publiée ou une de tes bandes utilise encore est gardé.'}</p>${customCleanupListMarkup(rows)}${p.kept.length?`<p class="muted">${en?`Kept because an unpublished custom warband, a custom profile or one of your warbands still uses them (${p.kept.length}):`:`Gardés car une warband custom non publiée, un profil custom ou une de tes bandes les utilise encore (${p.kept.length}) :`}</p>${customCleanupListMarkup(p.kept)}`:''}<button type="button" class="big-delete" onclick="confirmCleanupCustomPublished()">${en?'DELETE':'SUPPRIMER'}</button><button type="button" class="button secondary full" onclick="closeModal()">${en?'Cancel':'Annuler'}</button></div>`);
}
function confirmCleanupCustomPublished(){
  const en=siteLanguage==='en';const p=customPublishedPlan();const n=p.cws.length+p.items.length+p.parents.length;
  const cwIds=new Set(p.cws.map(cw=>cw.id));
  p.flag.forEach(f=>{const x=f.kind.list().find(q=>q[f.kind.idKey]===f.id);if(x&&!x.officialWarbandId)x.officialWarbandId=f.officialId});
  p.parents.forEach(pt=>{const key=pt.kind==='skills'?'customSkillTrees':'customMagicDomains';markDeleted(key,pt.id);state[key]=(pt.kind==='skills'?customSkillTreeList():customMagicDomainList()).filter(x=>x.id!==pt.id)});
  cwIds.forEach(id=>markDeleted('customWarbands',id));
  state.customWarbands=customWarbandList().filter(cw=>!cwIds.has(cw.id));
  p.items.forEach(x=>markDeleted(x.kind.stateKey,x.id));
  CUSTOM_CLEANUP_KINDS.forEach(k=>{const del=new Set(p.items.filter(x=>x.kind===k).map(x=>x.id));if(del.size)state[k.stateKey]=k.list().filter(x=>!del.has(x[k.idKey]))});
  if(customWarbandEditId&&cwIds.has(customWarbandEditId))customWarbandEditId=null;
  save(true);closeModal();render('custom');
  toast(en?`${n} published local cop${n>1?'ies':'y'} removed — online versions unchanged`:`${n} copie${n>1?'s':''} locale${n>1?'s':''} supprimée${n>1?'s':''} — versions en ligne inchangées`);
}
function confirmDeleteCustomWarband(id){
  const en=siteLanguage==='en';
  const cw=customWarbandById(id);
  markDeleted('customWarbands',id);state.customWarbands=customWarbandList().filter(x=>x.id!==id);
  // V-ORPHANFIGHTERS: a custom fighter created FOR this warband (its
  // customWarbandId set at creation — warriorToCustomFighterDraft on
  // duplicate/import, or customFighterForm when saved with this warband
  // picked — with factionId left empty, it only makes sense attached here)
  // used to survive the warband's own deletion with a now-dangling
  // customWarbandId. customFighterRow's bandLabel couldn't resolve that id
  // to anything, so it fell through to '—': an unlabeled "ghost" profile
  // stuck forever in Custom > Combattants with no visible origin. Unlike
  // equipment (shared/reusable, no per-warband ownership field), these
  // fighters aren't reused elsewhere, so it's safe to remove them with the
  // warband instead of leaving them behind. Never touches one already
  // officialized (officialWarbandId set) — that copy is still the live
  // editable source for a published warband regardless of this custom
  // record's fate.
  const orphanFighterIds=(cw?.fighterIds||[]).filter(fid=>{
    const w=customFighterById(fid);
    return w&&w.customWarbandId===id&&!w.officialWarbandId;
  });
  orphanFighterIds.forEach(fid=>markDeleted('customFighters',fid));
  if(orphanFighterIds.length)state.customFighters=customFighterList().filter(w=>!orphanFighterIds.includes(w.customFighterId));
  if(customWarbandEditId===id)customWarbandEditId=null;
  save(true);closeModal();render('custom');
  toast(orphanFighterIds.length?(en?`Custom warband deleted (+${orphanFighterIds.length} fighter${orphanFighterIds.length>1?'s':''} that ${orphanFighterIds.length>1?'were':'was'} exclusive to it)`:`Warband custom supprimée (+${orphanFighterIds.length} combattant${orphanFighterIds.length>1?'s':''} qui lui ${orphanFighterIds.length>1?'étaient':'était'} exclusif${orphanFighterIds.length>1?'s':''})`):(en?'Custom warband deleted':'Warband custom supprimée'));
}
function saveCustomWarbandMeta(){const en=siteLanguage==='en';const name=($('#cwName')?.value||'').trim(),description=($('#cwDescription')?.value||'').trim();if(!name){toast(en?'Give the Warband a name':'Donne un nom à la Warband');return}let cw=customWarbandById(customWarbandEditId);const isNew=!cw;if(!cw){cw={id:crypto.randomUUID(),name:'',description:'',fighterIds:[],equipmentIds:[],fighterRefs:[],equipmentRefs:[],specialRuleIds:[],traitIds:[]};state.customWarbands.push(cw)}cw.name=name;cw.description=description;customWarbandEditId=null;customWarbandCreating=false;save(true);render('custom');toast(isNew?(en?'Warband created — use Edit to configure it':'Warband créée — utilise Modifier pour la configurer'):(en?'Warband saved':'Warband sauvegardée'))}
function setCustomWarbandSection(v){if(customWarbandEditId){customWarbandSection=v;render('custom')}}
function saveCustomWarbandConfiguration(){
  const en=siteLanguage==='en';
  const cw=customWarbandById(customWarbandEditId);if(!cw)return;
  if(customWarbandSection==='fighters'){
    cw.fighterRefs=[...document.querySelectorAll('.cwFighter:checked')].map(x=>x.value);
    cw.fighterIds=cw.fighterRefs.filter(v=>v.startsWith('custom:')).map(v=>v.slice(7));
  }else if(customWarbandSection==='equipment'){
    cw.equipmentRefs=[...document.querySelectorAll('.cwEquipment:checked')].map(x=>x.value);
    cw.equipmentIds=cw.equipmentRefs.filter(v=>v.startsWith('custom:')).map(v=>v.slice(7));
  }else if(customWarbandSection==='special')cw.specialRuleIds=[...document.querySelectorAll('.cwSpecialRule:checked')].map(x=>x.value);
  else cw.traitIds=[...document.querySelectorAll('.cwTrait:checked')].map(x=>x.value);
  save(true);render('custom');toast(en?'Configuration saved':'Configuration sauvegardée')
}
function customWarbandSummaryRow(cw){const en=siteLanguage==='en';return `<article class="custom-item-row"><div class="custom-item-main"><div class="custom-item-icon">⚔</div><div><strong>${esc(cw.name)}</strong>${cw.officialId?`<small><span class="official-draft-tag">${en?'OFFICIAL EDITION':'ÉDITION OFFICIELLE'}</span></small>`:''}</div></div><div class="custom-item-actions"><button type="button" class="equipment-action" onclick="editCustomWarband('${cw.id}')">✎</button><button type="button" class="equipment-action" title="${en?'Duplicate (e.g. to make a sub-warband)':'Dupliquer (ex. pour une sous-bande)'}" aria-label="${en?'Duplicate':'Dupliquer'} ${esc(cw.name)}" onclick="duplicateCustomWarband('${cw.id}')">⧉</button><button type="button" class="equipment-action remove" onclick="deleteCustomWarband('${cw.id}')">🗑</button></div></article>`}
// Copy a custom warband: its own fighter profiles are copied (so they can be
// changed independently), equipment and rules stay shared library items,
// choices are copied (untick options in ⚙ Choices to restrict the copy).
function duplicateCustomWarband(id){
  const en=siteLanguage==='en';const src=customWarbandById(id);if(!src)return;
  const copy=JSON.parse(JSON.stringify(src));copy.id=crypto.randomUUID();delete copy.officialId;
  const taken=new Set(customWarbandList().map(c=>normName(c.name)));let name=`${src.name} — ${en?'copy':'copie'}`;let k=2;while(taken.has(normName(name))){name=`${src.name} — ${en?'copy':'copie'} ${k++}`}copy.name=name;
  const idMap=new Map();
  (src.fighterIds||[]).forEach(fid=>{const f=customFighterList().find(x=>x.customFighterId===fid);if(!f)return;const nf=JSON.parse(JSON.stringify(f));nf.customFighterId=crypto.randomUUID();nf.customWarbandId=copy.id;delete nf.officialWarbandId;state.customFighters.push(nf);idMap.set(fid,nf.customFighterId)});
  copy.fighterIds=(src.fighterIds||[]).map(f=>idMap.get(f)).filter(Boolean);
  copy.fighterRefs=(src.fighterRefs||[]).map(r=>{const m=String(r).match(/^custom:(.+)$/);return m&&idMap.has(m[1])?`custom:${idMap.get(m[1])}`:r});
  customWarbandList().push(copy);save(true);
  customArea='warband';customContentTab='warband';customWarbandEditId=copy.id;customWarbandCreating=false;customWarbandSection=copy.choices?'choices':'fighters';render('custom');
  toast(en?`${name} created`:`${name} créée`);
}
// V-WARBANDCHOICES editor: edit the warband's choices in Custom (names,
// texts, linked rules, which options are offered…) before publishing.
// Unticking "Offered" is how a duplicate becomes a sub-warband restricted to
// some options (e.g. only Chaos Undivided). Saved on change, no re-render.
function cwChoicesTarget(cwId){const cw=customWarbandById(cwId);return cw?.choices&&Array.isArray(cw.choices.groups)?cw:null}
function cwChoiceSet(cwId,gid,oid,field,value){const cw=cwChoicesTarget(cwId);if(!cw)return;const g=cw.choices.groups.find(x=>x.id===gid);if(!g)return;const o=oid?(g.options||[]).find(x=>x.id===oid):null;const tgt=oid?o:g;if(!tgt)return;
  if(field==='disabled')tgt.disabled=!value;
  else if(field==='coexist'){g.exclusiveExcept=Array.isArray(g.exclusiveExcept)?g.exclusiveExcept:[];g.exclusiveExcept=g.exclusiveExcept.filter(x=>x!==oid);if(value)g.exclusiveExcept.push(oid)}
  else if(field==='rarityMod'||field==='eyeTarget'||field==='eyeSkillTarget'){const n=Math.floor(Number(value));if(value===''||!Number.isFinite(n))delete tgt[field];else tgt[field]=n}
  else if(field==='leaderStatMods'){const mods={};String(value||'').split(/[,;\s]+/).forEach(t=>{const m=t.match(/^([A-Za-z]+)\s*([+-]\d+)$/);if(m&&P.includes(m[1].toUpperCase()))mods[m[1].toUpperCase()]=Number(m[2])});if(Object.keys(mods).length)tgt.leaderStatMods=mods;else delete tgt.leaderStatMods}
  else if(field==='labelEn'||field==='labelFr'){tgt.label=typeof tgt.label==='object'&&tgt.label?tgt.label:{en:String(tgt.label||''),fr:String(tgt.label||'')};tgt.label[field==='labelEn'?'en':'fr']=String(value||'')}
  else tgt[field]=String(value||'');
  save(true)}
function cwChoiceToggleList(cwId,gid,oid,field,name,on){const cw=cwChoicesTarget(cwId);if(!cw)return;const g=cw.choices.groups.find(x=>x.id===gid);const tgt=oid?(g?.options||[]).find(x=>x.id===oid):g;if(!tgt)return;const list=Array.isArray(tgt[field])?tgt[field]:[];tgt[field]=on?[...new Set([...list,name])]:list.filter(n=>normName(n)!==normName(name));save(true)}
function cwEyeSet(cwId,field,value){const cw=cwChoicesTarget(cwId);if(!cw)return;if(field==='enabled'){if(value){cw.choices.eyeOfTheGods=cw.choices.eyeOfTheGods||cw.choices._eyeOff||{group:(cw.choices.groups.find(g=>g.when!=='creation')||{}).id,baseTarget:12};delete cw.choices._eyeOff}else{cw.choices._eyeOff=cw.choices.eyeOfTheGods;delete cw.choices.eyeOfTheGods}save(true);render('custom');return}const e=cw.choices.eyeOfTheGods;if(!e)return;if(field==='baseTarget'||field==='skillTarget'){const n=Math.floor(Number(value));if(Number.isFinite(n))e[field]=n}else e[field]=String(value||'');save(true)}
function customWarbandChoicesEditor(cw){
  const en=siteLanguage==='en';
  if(!cw.choices||!Array.isArray(cw.choices.groups)||!cw.choices.groups.length)return `<div class="empty compact">${en?'This warband has no choices. Choices come with an imported warband that defines them (e.g. Marauders of Chaos: tribe, Marks, Eye of the Gods), and are kept when you duplicate it.':'Cette warband n’a pas de choix. Les choix viennent d’une warband importée qui les définit (ex. Marauders of Chaos : tribu, Marques, Œil des Dieux) et sont conservés quand tu la dupliques.'}</div>`;
  const id=esc(cw.id);
  const ruleNames=[...(cw.specialRuleIds||[]).map(i=>customContentById('special',i)?.name),...(cw.traitIds||[]).map(i=>customContentById('traits',i)?.name)].filter(Boolean);
  const fighterNames=customWarbandWarriors(cw).map(w=>w.name);
  const domainNames=Object.keys(customMergedMagicDomains(customWarbandFaction(cw))).sort((a,b)=>a.localeCompare(b));
  const lab=g=>typeof g.label==='object'&&g.label?g.label:{en:String(g.label||''),fr:String(g.label||'')};
  const chk=(on,handler,label)=>`<label class="cwc-check"><input type="checkbox" ${on?'checked':''} onchange="${handler}"> ${label}</label>`;
  const groups=cw.choices.groups.map(g=>{const gid=esc(g.id);const L=lab(g);
    const head=`<div class="cwc-group-head"><div class="cwc-fields"><label><span>${en?'Name (EN)':'Nom (EN)'}</span><input class="search" value="${esc(L.en||'')}" onchange="cwChoiceSet('${id}','${gid}',null,'labelEn',this.value)"></label><label><span>${en?'Name (FR)':'Nom (FR)'}</span><input class="search" value="${esc(L.fr||'')}" onchange="cwChoiceSet('${id}','${gid}',null,'labelFr',this.value)"></label></div><small class="muted">${g.when==='creation'?(en?'Chosen when the warband is created (popup), changeable with Modify.':'Choisi à la création de la bande (popup), modifiable avec Modifier.'):(en?'Chosen when recruiting these fighters (popup), changeable from their sheet:':'Choisi au recrutement de ces combattants (popup), modifiable depuis leur fiche :')}</small>${g.when==='recruit'?`<div class="cwc-list">${fighterNames.map(n=>chk((g.fighters||[]).some(x=>normName(x)===normName(n)),`cwChoiceToggleList('${id}','${gid}',null,'fighters','${esc(n).replace(/'/g,"\\'")}',this.checked)`,esc(n))).join('')}</div>`:''}</div>`;
    const opts=(g.options||[]).map(o=>{const oid=esc(o.id);return `<details class="cwc-opt${o.disabled?' off':''}"><summary><b>${esc(o.name)}</b>${o.disabled?`<span class="cwc-off">${en?'not offered':'non proposé'}</span>`:''}</summary><div class="cwc-opt-body">
      ${chk(!o.disabled,`cwChoiceSet('${id}','${gid}','${oid}','disabled',this.checked);this.closest('details').classList.toggle('off',!this.checked)`,en?'Offered in this warband':'Proposé dans cette warband')}
      <div class="cwc-fields"><label><span>${en?'Name':'Nom'}</span><input class="search" value="${esc(o.name||'')}" onchange="cwChoiceSet('${id}','${gid}','${oid}','name',this.value)"></label>
      ${g.when==='creation'?`<label><span>${en?'Rarity roll modifier':'Modificateur de rareté'}</span><input class="search" type="number" value="${o.rarityMod??''}" onchange="cwChoiceSet('${id}','${gid}','${oid}','rarityMod',this.value)"></label>${cw.choices.eyeOfTheGods?`<label><span>${en?'Eye of the Gods target':'Cible Œil des Dieux'}</span><input class="search" type="number" value="${o.eyeTarget??''}" placeholder="${en?'default':'défaut'}" onchange="cwChoiceSet('${id}','${gid}','${oid}','eyeTarget',this.value)"></label><label><span>${en?'…with the skill':'…avec la compétence'}</span><input class="search" type="number" value="${o.eyeSkillTarget??''}" placeholder="${en?'default':'défaut'}" onchange="cwChoiceSet('${id}','${gid}','${oid}','eyeSkillTarget',this.value)"></label>`:''}`:`<label><span>${en?'Leader stat bonus (e.g. T+1)':'Bonus de carac. du leader (ex. T+1)'}</span><input class="search" value="${esc(Object.entries(o.leaderStatMods||{}).map(([k,v])=>`${k}${v>0?'+':''}${v}`).join(' '))}" onchange="cwChoiceSet('${id}','${gid}','${oid}','leaderStatMods',this.value)"></label>`}</div>
      <label class="cwc-text"><span>${en?'Description':'Description'}</span><textarea class="wide-textarea" rows="2" onchange="cwChoiceSet('${id}','${gid}','${oid}','text',this.value)">${esc(o.text||'')}</textarea></label>
      ${g.when==='recruit'?chk((g.exclusiveExcept||[]).includes(o.id),`cwChoiceSet('${id}','${gid}','${oid}','coexist',this.checked)`,en?'Can coexist with other options in the warband':'Peut coexister avec les autres options dans la bande'):''}
      <div class="cwc-sub">${en?'Rules given':'Règles données'}</div><div class="cwc-list">${ruleNames.map(n=>chk((o.ruleNames||[]).some(x=>normName(x)===normName(n)),`cwChoiceToggleList('${id}','${gid}','${oid}','ruleNames','${esc(n).replace(/'/g,"\\'")}',this.checked)`,esc(n))).join('')}</div>
      ${g.when==='recruit'?`<div class="cwc-sub">${en?'Extra rules only when chosen at recruitment':'Règles en plus seulement si choisi au recrutement'}</div><div class="cwc-list">${ruleNames.map(n=>chk((o.recruitRuleNames||[]).some(x=>normName(x)===normName(n)),`cwChoiceToggleList('${id}','${gid}','${oid}','recruitRuleNames','${esc(n).replace(/'/g,"\\'")}',this.checked)`,esc(n))).join('')}</div>`:''}
      <div class="cwc-sub">${en?'Spell domains given (the fighter only sees the chosen option’s domains among those linked here)':'Domaines de sorts donnés (le combattant ne voit que ceux de l’option choisie parmi ceux liés ici)'}</div><div class="cwc-list">${domainNames.length?domainNames.map(n=>chk((o.magicDomains||[]).some(x=>normName(x)===normName(n)),`cwChoiceToggleList('${id}','${gid}','${oid}','magicDomains','${esc(n).replace(/'/g,"\\'")}',this.checked)`,esc(n))).join(''):`<span class="muted">${en?'No spell domain yet: create them in Custom → Spells.':'Aucun domaine pour l’instant : crée-les dans Custom → Sorts.'}</span>`}</div>
      ${domainNames.length?`<div class="cwc-sub">${en?'Only for these fighters (none checked = every fighter with this choice)':'Seulement pour ces combattants (aucun coché = tous ceux qui ont ce choix)'}</div><div class="cwc-list">${fighterNames.map(n=>chk((o.magicDomainFighters||[]).some(x=>normName(x)===normName(n)),`cwChoiceToggleList('${id}','${gid}','${oid}','magicDomainFighters','${esc(n).replace(/'/g,"\\'")}',this.checked)`,esc(n))).join('')}</div>`:''}
    </div></details>`}).join('');
    return `<section class="cwc-group"><div class="eyebrow">${esc((L.en||g.id).toUpperCase())}</div>${head}<div class="cwc-opts">${opts}</div></section>`}).join('');
  const e=cw.choices.eyeOfTheGods;
  const eye=`<section class="cwc-group"><div class="eyebrow">${en?'EYE OF THE GODS (POST-BATTLE STEP 0)':'ŒIL DES DIEUX (ÉTAPE 0 POST-BATAILLE)'}</div>${chk(!!e,`cwEyeSet('${id}','enabled',this.checked)`,en?'Enabled for this warband':'Activé pour cette warband')}${e?`<div class="cwc-fields"><label><span>${en?'Target (2D6 + bonus)':'Cible (2D6 + bonus)'}</span><input class="search" type="number" value="${Number(e.baseTarget)||12}" onchange="cwEyeSet('${id}','baseTarget',this.value)"></label><label><span>${en?'Skill lowering the target':'Compétence qui baisse la cible'}</span><input class="search" value="${esc(e.skillName||'')}" onchange="cwEyeSet('${id}','skillName',this.value)"></label><label><span>${en?'Target with that skill':'Cible avec cette compétence'}</span><input class="search" type="number" value="${e.skillTarget??''}" onchange="cwEyeSet('${id}','skillTarget',this.value)"></label><label><span>${en?'Spawn fighter':'Combattant Rejeton'}</span><select class="search" onchange="cwEyeSet('${id}','spawnFighter',this.value)">${fighterNames.map(n=>`<option ${normName(n)===normName(e.spawnFighter||'')?'selected':''}>${esc(n)}</option>`).join('')}</select></label></div><small class="muted">${en?'A Mark won through it goes to the leader and uses the options of the group:':'Une Marque gagnée ainsi va au leader et utilise les options du groupe :'} <b>${esc(lab(cw.choices.groups.find(g=>g.id===e.group)||{}).en||e.group||'')}</b></small>`:''}</section>`;
  return `<div class="cwc">${groups}${eye}</div>`;
}
function customWarbandEditor(cw){
 const en=siteLanguage==='en';
 const tabs=en?[['fighters','⚔ Fighters'],['equipment','◇ Equipment'],['special','✚ Special Rules'],['traits','◆ Traits'],['skills','✦ Skills / Spells'],['choices','⚙ Choices']]:[['fighters','⚔ Combattants'],['equipment','◇ Équipement'],['special','✚ Règles spéciales'],['traits','◆ Traits'],['skills','✦ Skills / Sorts'],['choices','⚙ Choix']];
 let body='';
 if(customWarbandSection==='fighters'){
   // V-WARBANDROSTER: matches the mockup — this warband's OWN fighter
   // profiles (customWarbandId===cw.id) are the primary view, shown as a
   // roster of rows with a ✎ edit shortcut, not buried in a checkbox picker
   // of every fighter in the game. "Recruter un combattant existant" below
   // stays for the separate, secondary case of pulling in a fighter that
   // belongs to another (official or custom) warband as-is.
   const exclusive=customFighterList().filter(w=>w.customWarbandId===cw.id);
   const roster=exclusive.length?`<div class="custom-item-list">${exclusive.map(w=>customFighterRow(w,false,`editWarbandFighter('${esc(w.customFighterId)}','${esc(cw.id)}')`)).join('')}</div>`:`<div class="empty compact">${en?'No fighter profile created for this warband.':'Aucun profil de combattant créé pour cette warband.'}</div>`;
   const createBtn=`<button type="button" class="button secondary" onclick="newWarbandFighter('${esc(cw.id)}')">＋ ${en?'Add a fighter profile':'Ajouter un profil de combattant'}</button>`;
   const sel=new Set(customWarbandFighterRefs(cw));
   const allItems=customWarbandFighterEntries().filter(e=>!(e.custom&&e.warrior.customWarbandId===cw.id));
   const items=allItems.filter(e=>e.custom||sel.has(e.key)||!customWarbandHideOfficial);
   const hiddenCount=allItems.length-items.length;
   const groups={};
   items.forEach(e=>(groups[e.factionName]||(groups[e.factionName]=[])).push(e));
   const hideToggle=`<label class="custom-hide-official-toggle"><input type="checkbox" ${customWarbandHideOfficial?'checked':''} onchange="toggleCustomWarbandHideOfficial(this.checked)"> ${en?'Hide fighters from already existing warbands':'Masquer les combattants des warbands déjà existantes'}${hiddenCount?` <small>(${hiddenCount} ${en?'hidden':'masqué'+(hiddenCount>1?'s':'')})</small>`:''}</label>`;
   const recruitPicker=allItems.length?`<div class="custom-choice-toolbar"><input class="search" placeholder="${en?'Search a fighter…':'Rechercher un combattant…'}" oninput="filterCustomWarbandChoices(this,'.cw-fighter-entry')"><span>${items.length} ${en?'profiles available':'profils disponibles'}</span></div>${hideToggle}${items.length?`<div class="custom-choice-list">${Object.entries(groups).map(([group,rows])=>`<details class="custom-collapse" open><summary><span>${esc(group)}</span><small>${rows.length}</small></summary><div class="custom-choice-list">${rows.map(e=>{const w=e.warrior;return `<label class="custom-check cw-fighter-entry" data-search="${esc((w.name+' '+group+' '+(w.type||'')).toLowerCase())}"><input class="cwFighter" type="checkbox" value="${esc(e.key)}" ${sel.has(e.key)?'checked':''}><span><b>${esc(w.name)}</b><small>${esc(w.type||'Henchman')} · ${Number(w.cost||0)} GC${e.custom?' · CUSTOM':''}</small></span></label>`}).join('')}</div></details>`).join('')}</div>`:`<div class="empty compact">${en?'Everything is hidden — uncheck the box above to see fighters from existing warbands.':'Tout est masqué — décoche la case ci-dessus pour voir les combattants des warbands existantes.'}</div>`}`:`<div class="empty compact">${en?'No other fighter available.':'Aucun autre combattant disponible.'}</div>`;
   body=createBtn+roster+`<details class="custom-collapse"><summary><span>${en?'RECRUIT AN EXISTING FIGHTER':'RECRUTER UN COMBATTANT EXISTANT'}</span><small>${en?'From another warband (official or custom), as-is':'D’une autre warband (officielle ou custom), tel quel'}</small></summary>${recruitPicker}</details>`
 } else if(customWarbandSection==='equipment'){
   const sel=new Set(customWarbandEquipmentRefs(cw));
   const allItems=customWarbandEquipmentEntries();
   const items=allItems.filter(e=>e.custom||sel.has(e.key)||!customWarbandHideOfficial);
   const hiddenCount=allItems.length-items.length;
   const groups={};
   items.forEach(e=>{const g=e.equipment.category||e.equipment.subcategory||(en?'Equipment':'Équipement');(groups[g]||(groups[g]=[])).push(e)});
   const hideToggle=`<label class="custom-hide-official-toggle"><input type="checkbox" ${customWarbandHideOfficial?'checked':''} onchange="toggleCustomWarbandHideOfficial(this.checked)"> ${en?'Hide equipment from already existing warbands':"Masquer l'équipement des warbands déjà existantes"}${hiddenCount?` <small>(${hiddenCount} ${en?'hidden':'masqué'+(hiddenCount>1?'s':'')})</small>`:''}</label>`;
   // V-WARBANDEXCLUSIVE: "+ Créer un équipement exclusif" builds a new item
   // straight from here (full form, weapon profile included) instead of
   // sending the person to Custom Générique and back — see
   // newExclusiveCustomEquipment/saveCustomEquipment.
   const createExclusive=`<button type="button" class="button secondary" onclick="newExclusiveCustomEquipment('${esc(cw.id)}')">＋ ${en?'Create equipment exclusive to this warband':'Créer un équipement exclusif à cette warband'}</button>`;
   body=createExclusive+(allItems.length?`<div class="custom-choice-toolbar"><input class="search" placeholder="${en?'Search equipment…':'Rechercher un équipement…'}" oninput="filterCustomWarbandChoices(this,'.cw-equipment-entry')"><span>${items.length} ${en?'items available':'équipements disponibles'}</span></div>${hideToggle}${items.length?`<div class="custom-choice-list">${Object.entries(groups).map(([group,rows])=>`<details class="custom-collapse" open><summary><span>${esc(group)}</span><small>${rows.length}</small></summary><div class="custom-choice-list">${rows.map(e=>{const w=e.equipment;const isExclusive=w.exclusiveWarbandId===cw.id;return `<div class="custom-choice-row"><label class="custom-check cw-equipment-entry" data-search="${esc((w.name+' '+group).toLowerCase())}"><input class="cwEquipment" type="checkbox" value="${esc(e.key)}" ${sel.has(e.key)?'checked':''}><span><b>${esc(w.name)}</b><small>${esc(group)} · ${Number(w.price??w.value??0)} GC${isExclusive?(en?' · EXCLUSIVE':' · EXCLUSIF'):e.custom?' · CUSTOM':''}</small></span></label>${isExclusive?`<button type="button" class="equipment-action" title="${en?'Edit':'Modifier'}" onclick="editExclusiveCustomEquipment('${esc(w.customEquipmentId)}','${esc(cw.id)}')">✎</button>`:''}</div>`}).join('')}</div></details>`).join('')}</div>`:`<div class="empty compact">${en?"Everything is hidden — uncheck the box above to see equipment from existing warbands.":"Tout est masqué — décoche la case ci-dessus pour voir l'équipement des warbands existantes."}</div>`}`:`<div class="empty compact">${en?'No equipment available.':'Aucun équipement disponible.'}</div>`)
 } else if(customWarbandSection==='choices'){
   body=customWarbandChoicesEditor(cw);
 } else if(customWarbandSection==='skills'){
   // V-WARBANDSKILLSNAV: skills/spells have no real "exclusive to this
   // warband" concept (see the V-OFFICIALIZESCOPE comment in
   // openOfficializeItemPicker) — a tree/domain is global by construction
   // the moment it exists, granted to a fighter via that fighter's own
   // Skill/Magic access fields (Custom Générique → Combattants → ✎). So
   // this tab is a shortcut to CREATE trees/domains and their
   // skills/spells without losing the warband context, not a picker —
   // Combattants is still where a given fighter gets access to one.
   const trees=customSkillTreeList(),domains=customMagicDomainList();
   const countIn=(kind,name)=>customContentList(kind).filter(x=>normName(x[kind==='skills'?'tree':'domain']||'')===normName(name)).length;
   const treeRows=trees.length?trees.map(t=>`<div class="custom-choice-row"><label class="custom-check" style="flex:1"><span><b>${esc(t.name)}</b><small>${countIn('skills',t.name)} ${en?'skill'+(countIn('skills',t.name)!==1?'s':''):'compétence'+(countIn('skills',t.name)!==1?'s':'')}</small></span></label><button type="button" class="equipment-action" title="${en?'Manage':'Gérer'}" onclick="openWarbandSkillsBuilder('skills','${esc(cw.id)}')">✎</button></div>`).join(''):`<div class="empty compact">${en?'No skill tree created.':'Aucun arbre de compétences créé.'}</div>`;
   const domainRows=domains.length?domains.map(d=>`<div class="custom-choice-row"><label class="custom-check" style="flex:1"><span><b>${esc(d.name)}</b><small>${countIn('spells',d.name)} ${en?'spell'+(countIn('spells',d.name)!==1?'s':''):'sort'+(countIn('spells',d.name)!==1?'s':'')}</small></span></label><button type="button" class="equipment-action" title="${en?'Manage':'Gérer'}" onclick="openWarbandSkillsBuilder('spells','${esc(cw.id)}')">✎</button></div>`).join(''):`<div class="empty compact">${en?'No magic domain created.':'Aucun domaine de magie créé.'}</div>`;
   body=`<p class="custom-field-help">${en?'Skills and spells are global — once created here, grant them to a specific fighter from its profile (Fighters → ✎ → Skill tree / Magic domain).':'Les compétences et sorts sont globaux — une fois créés ici, accorde-les à un combattant précis depuis son profil (Combattants → ✎ → Arbre de compétences / Domaine de magie).'}</p>
     <div class="custom-builder-intro"><div><div class="eyebrow">${en?'SKILL TREES':'ARBRES DE COMPÉTENCES'}</div></div><button type="button" class="button secondary" onclick="openWarbandSkillsBuilder('skills','${esc(cw.id)}')">＋ ${en?'Create a skill tree':'Créer un arbre de compétences'}</button></div>
     <div class="custom-choice-list">${treeRows}</div>
     <div class="custom-builder-intro" style="margin-top:16px"><div><div class="eyebrow">${en?'MAGIC DOMAINS':'DOMAINES DE MAGIE'}</div></div><button type="button" class="button secondary" onclick="openWarbandSkillsBuilder('spells','${esc(cw.id)}')">＋ ${en?'Create a magic domain':'Créer un domaine de magie'}</button></div>
     <div class="custom-choice-list">${domainRows}</div>`
 } else {const kind=customWarbandSection,key=kind==='special'?'specialRuleIds':'traitIds',cls=kind==='special'?'cwSpecialRule':'cwTrait',sel=cw[key]||[];
   // V-WARBANDEXCLUSIVE: a special rule exclusive to ANOTHER warband is
   // filtered out here (it's not selectable for this one); traits are
   // always global so nothing to filter for that kind.
   const items=customContentList(kind).filter(w=>kind!=='special'||!w.exclusiveWarbandId||w.exclusiveWarbandId===cw.id);
   const bandWideNotice=`<p class="custom-field-help">${en?`Checked here, ${kind==='special'?'a special rule':'a trait'} automatically applies to <b>every fighter</b> in this warband (not just one): the stat modifiers and granted skills written in its text are detected and applied on their own to each sheet.`:`Coché ici, ${kind==='special'?'une règle spéciale':'un trait'} s'applique automatiquement à <b>tous les combattants</b> de cette warband (pas à un seul) : les modificateurs de stat et compétences accordées écrits dans son texte sont détectés et appliqués tout seuls sur chaque fiche.`}</p>`;
   const createExclusive=`<button type="button" class="button secondary" onclick="newExclusiveCustomContent('${kind}','${esc(cw.id)}')">＋ ${en?(kind==='special'?'Create a special rule exclusive to this warband':'Create a trait'):(kind==='special'?'Créer une règle spéciale exclusive à cette warband':'Créer un trait')}</button>`;
   body=createExclusive+bandWideNotice+(items.length?`<div class="custom-choice-list">${items.map(w=>{const isExclusive=kind==='special'&&w.exclusiveWarbandId===cw.id;return `<div class="custom-choice-row"><label class="custom-check"><input class="${cls}" type="checkbox" value="${esc(w.customContentId)}" ${sel.includes(w.customContentId)?'checked':''}><span><b>${esc(w.name)}</b><small>${esc((w.text||'').slice(0,140))}${isExclusive?(en?' · EXCLUSIVE':' · EXCLUSIF'):''}</small></span></label><button type="button" class="equipment-action" title="${en?'Edit':'Modifier'}" onclick="editExclusiveCustomContent('${kind}','${esc(w.customContentId)}','${esc(cw.id)}')">✎</button></div>`}).join('')}</div>`:`<div class="empty compact">${en?'No custom content created.':'Aucun contenu custom créé.'}</div>`)}
 // V-WARBANDLOCK (Task #80): once an admin has edited the LIVE warband
 // directly (Admin → Gestion), the republish button here is disabled —
 // it would otherwise rebuild the whole definition from this local draft
 // and silently wipe out whatever the admin added straight on the server.
 const lockedAt=officialWarbandLockInfo(cw);
 const officialNotice=cw.officialId?`<div class="official-draft-notice"><span class="official-draft-tag">${en?'OFFICIAL EDITION':'ÉDITION OFFICIELLE'}</span><p>${en?'This band is the admin-only edit copy of a published official warband. Edit its fighters/equipment/rules with the same tools as for a custom warband (Custom tab → Profiles / Equipment), check them here as usual, then click <b>Publish changes</b> to push them to the server, visible to every account.':"Cette bande est la copie d'édition, réservée aux admins, d'une warband officielle publiée. Modifie ses combattants/équipements/règles avec les mêmes outils que pour une warband custom (onglet Custom → Profils / Équipements), coche-les ici comme d'habitude, puis clique <b>Publier les modifications</b> pour les pousser sur le serveur, visibles par tous les comptes."}</p>${lockedAt?`<p class="official-draft-locked-warning">🔒 ${en?`An admin modified this band directly since ${new Date(lockedAt).toLocaleDateString()} — republishing from this draft is disabled so as not to overwrite their changes. Go through <b>Admin → Manage</b> to keep editing it.`:`Un admin a modifié cette bande directement depuis le ${new Date(lockedAt).toLocaleDateString()} — la republication depuis ce brouillon est désactivée pour ne pas écraser ses changements. Passe par <b>Admin → Gérer</b> pour continuer à l’éditer.`}</p>`:''}</div>`:'';
 return `<section class="card custom-warband-editor">${officialNotice}${customWarbandMetaEditor(cw)}<div class="custom-builder-intro"><div><div class="eyebrow">${en?'CUSTOM WARBAND':'WARBAND CUSTOM'}</div><h3>${en?'Configuration':'Configuration'}</h3><p>${en?'Link to this Warband the fighters and equipment available across the whole game, as well as your custom rules and traits.':"Associe à cette Warband les combattants et équipements disponibles dans l'ensemble du jeu, ainsi que tes règles et traits custom."}</p></div></div><div class="custom-warband-sections">${tabs.map(([id,l])=>`<button type="button" class="${customWarbandSection===id?'active':''}" onclick="setCustomWarbandSection('${id}')">${l}</button>`).join('')}</div>${body}<div class="custom-actions"><button type="button" class="button primary" onclick="saveCustomWarbandConfiguration()">${en?'Save configuration':'Sauvegarder la configuration'}</button>${cw.officialId?(lockedAt?`<button type="button" class="button secondary" disabled title="${en?'Locked — an admin edited this band directly':'Verrouillé — un admin a édité cette bande directement'}">🔒 ${en?'Publishing disabled':'Publication désactivée'}</button>`:`<button type="button" class="button primary" onclick="publishOfficialWarbandChanges('${cw.id}')">⬆ ${en?'Publish changes':'Publier les modifications'}</button>`):''}</div></section>`;
}
// Post-creation name/description/icon editor — the initial create form
// (customWarbandCreateForm) only runs once, at creation, so this is the only
// place those fields can be changed afterward. The icon shown here is the
// same one rendered on the warband's tile in the "Create Warband" screen.
function customWarbandMetaEditor(cw){
 const en=siteLanguage==='en';
 const icon=cw.icon||'';
 return `<div class="custom-warband-meta-edit"><div class="custom-warband-icon-row"><span class="gang-icon custom-warband-tile-icon">${imageMarkup(icon,'custom-warband',esc(cw.name),cw.iconFocus)}</span><div class="custom-warband-icon-actions"><button type="button" class="button secondary" onclick="pickImage('custom-warband','${cw.id}')">${icon?(en?'Change icon':"Changer l'icône"):(en?'Add an icon':'Ajouter une icône')}</button>${icon?`<button type="button" class="button secondary" onclick="removeImage('custom-warband','${cw.id}')">${en?'Remove':'Retirer'}</button>`:''}</div></div><label class="custom-field"><span>${en?'Name':'Nom'}</span><input id="cwMetaName" value="${esc(cw.name)}"></label><label class="custom-field"><span>${en?'Description (optional)':'Description (facultatif)'}</span>${customTextToolbarMarkup('cwMetaDescription')}<textarea id="cwMetaDescription" class="wide-textarea" rows="3" placeholder="${en?'Band description…':'Description de la bande…'}">${esc(cw.description||'')}</textarea></label><div class="custom-actions"><button type="button" class="button secondary" onclick="saveCustomWarbandInfo('${cw.id}')">${en?'Save name / description':'Sauvegarder le nom / la description'}</button></div></div>`;
}
function saveCustomWarbandInfo(id){
 const en=siteLanguage==='en';
 const cw=customWarbandById(id);if(!cw)return;
 const name=($('#cwMetaName')?.value||'').trim();
 if(!name){toast(en?'Give the Warband a name':'Donne un nom à la Warband');return}
 cw.name=name;
 cw.description=($('#cwMetaDescription')?.value||'').trim();
 save(true);render('custom');toast(en?'Information saved':'Informations sauvegardées');
}
function filterCustomWarbandChoices(input,selector){const q=(input.value||'').trim().toLowerCase();document.querySelectorAll(selector).forEach(el=>{el.style.display=!q||(el.dataset.search||'').includes(q)?'':'none'})}
function customWarbandCreateForm(){const en=siteLanguage==='en';return `<section class="card custom-warband-create-form"><div class="eyebrow">${en?'NEW WARBAND':'NOUVELLE WARBAND'}</div><h3>${en?'Create a custom Warband':'Créer une Warband custom'}</h3><label class="custom-field"><span>${en?'Name':'Nom'}</span><input id="cwName" placeholder="${en?'Warband name':'Nom de la Warband'}"></label><label class="custom-field"><span>${en?'Description (optional)':'Description (facultatif)'}</span>${customTextToolbarMarkup('cwDescription')}<textarea id="cwDescription" class="wide-textarea" rows="4" placeholder="${en?'Band description…':'Description de la bande…'}"></textarea></label><div class="custom-actions"><button type="button" class="button secondary" onclick="customWarbandCreating=false;render('custom')">${en?'Cancel':'Annuler'}</button><button type="button" class="button primary" onclick="saveCustomWarbandMeta()">${en?'Save':'Sauvegarder'}</button></div></section>`}
function customWarbandPage(){const en=siteLanguage==='en';const list=customWarbandList();if(customWarbandCreating)return `<div class="custom-page"><div class="page-intro"><div><div class="eyebrow">FORGE / CUSTOM CONTENT</div><h2>${en?'Custom warbands':'Warbands personnalisées'}</h2><p>${en?'Create the warband first, then click Edit to open its configuration.':'Crée d’abord la Warband, puis clique sur Modifier pour ouvrir sa configuration.'}</p></div></div>${customWarbandCreateForm()}</div>`;if(customWarbandEditId){const cw=customWarbandById(customWarbandEditId);if(cw)return `<div class="custom-page"><div class="page-intro"><div><div class="eyebrow">FORGE / CUSTOM CONTENT / WARBAND</div><h2>${esc(cw.name)}</h2><p>${cw.description?customTextMarkup(cw.description):esc(en?'Custom warband':'Warband personnalisée')}</p></div><button type="button" class="button secondary" onclick="customWarbandEditId=null;render('custom')">${en?'← Library':'← Bibliothèque'}</button></div>${customWarbandEditor(cw)}</div>`}return `<div class="custom-page"><div class="page-intro"><div><div class="eyebrow">FORGE / CUSTOM CONTENT</div><h2>${en?'Custom warbands':'Warbands personnalisées'}</h2><p>${en?'Create and configure your own warbands without touching the official content.':'Crée et configure tes propres Warbands sans toucher au contenu officiel.'}</p></div><button type="button" class="button primary" onclick="newCustomWarband()">＋ ${en?'New warband':'Nouvelle Warband'}</button></div><div class="custom-workspace"><section class="card custom-editor"><div class="custom-library-head"><div><div class="eyebrow">${en?'LIBRARY':'BIBLIOTHÈQUE'}</div><h3>${en?'Custom warbands':'Warbands custom'}</h3></div><span>${list.length}</span></div><div class="custom-item-list">${list.length?list.map(customWarbandSummaryRow).join(''):`<div class="empty large"><strong>${en?'No custom warbands.':'Aucune Warband custom.'}</strong><span>${en?'Create the first one with the button above.':'Crée la première avec le bouton ci-dessus.'}</span></div>`}</div></section></div></div>`}

// Boot sequence: run only after every top-level `let`/`const`/function
// declaration in this file has been evaluated. Calling this earlier (it used
// to sit mid-file) could invoke render functions — e.g. custom() — that
// reference variables declared further down (customContentTab, customTab,
// customFighterEditId, ...) while they were still in their temporal dead
// zone, throwing a ReferenceError that aborted the rest of this script's
// top-level execution for the whole session (breaking the Custom tab and
// skipping the official-warband merge below).
// One-time data-hygiene pass: the source book was PDF-extracted, and a
// handful of entries (the last one parsed in a tree/section, e.g. the
// Academic skill "Haggle") had every subsequent skill/trait's heading+text
// accidentally appended after their own real text — visible on the page as
// one giant "block" of unrelated rules glued under a single card, instead of
// each skill getting its own separate card. The real, correctly-separated
// entry for every one of those skills already exists elsewhere in the data
// (e.g. "Fast Shot" has its own proper entry) — so the fix is to cut the
// bleed-over off, not to recover it. Runs once at boot, mutating RULES in
// place, so every reader (search, cards, peek tooltips, glossary links) sees
// the cleaned text.
function sanitizeReferenceTextBleed(){
  const cats=RULES&&RULES.categories;if(!cats)return;
  const allEntries=[];
  Object.keys(cats).forEach(k=>{if(Array.isArray(cats[k]))cats[k].forEach(e=>allEntries.push(e))});
  const nameSet=new Set();
  allEntries.forEach(e=>{if(e&&e.name&&String(e.name).trim().length>=5)nameSet.add(String(e.name).trim().toUpperCase())});
  const treeSet=new Set();
  allEntries.forEach(e=>{if(e&&e.category)treeSet.add(String(e.category).trim().toUpperCase());if(e&&e.tree)treeSet.add(String(e.tree).trim().toUpperCase())});
  let fixed=0;
  allEntries.forEach(e=>{
    if(!e||typeof e.text!=='string'||!e.text.includes('\n'))return;
    const ownName=String(e.name||'').trim().toUpperCase();
    const lines=e.text.split(/\n/);
    let cut=-1;
    for(let i=1;i<lines.length;i++){
      const t=lines[i].trim().toUpperCase();
      if(t&&t!==ownName&&nameSet.has(t)){cut=i;break}
    }
    if(cut>0){
      let kept=lines.slice(0,cut);
      while(kept.length&&treeSet.has(kept[kept.length-1].trim().toUpperCase()))kept.pop();
      const newText=kept.join('\n').trim();
      if(newText&&newText.length<e.text.length){
        e.text=newText;
        e.lines=newText.split(/\n+/).filter(Boolean).length||1;
        fixed++;
      }
    }
  });
  if(fixed)console.info('[ref-sanitize] trimmed PDF-extraction bleed from '+fixed+' entries');
}
sanitizeReferenceTextBleed();
refreshAdminNavVisibility();
// V-VALUEFLASH: on a device that has signed in before, the very first paint
// used to render immediately from the local cache (necroheim_roster_v4),
// then bootstrapAccountSession()'s async cloud fetch would come back with
// whatever changed meanwhile (another device, another session) and
// silently correct it — visible as a warband value (or gold, fighter
// count…) flashing from a stale number to the right one right after load.
// Only a device with a stored account session will ever hit that cloud
// merge, so only there is it worth a short, BOUNDED wait for that one
// check before the first render — capped so a slow/offline network still
// shows something quickly (falling back to the same immediate-render
// behavior, with the correction arriving the way it always did).
// V-VALUEFLASH2 (Task #76): the SAME flash also happened for weapon-price
// corrections, base-catalog fighter-cost corrections, and an official
// warband's own (possibly corrected) fighter/equipment costs — all of them
// change what total(r)/fighterValue add up to, exactly like the account
// merge above, but used to only ever load AFTER the first paint (the very
// last line of this file, unbounded). A roster's displayed "Valeur de
// bande" is summed live from D.factions/D.weapons on every render (see
// total()/fighterValue()), so as long as those three loads land before the
// FIRST render, the number is right from the very first frame — no local
// data is actually "stacking" anywhere, it was purely a load-order race.
// Folded into the same bounded wait so it's capped by the same timeout.
const hasStoredAccountSession=!!localStorage.getItem(ACCOUNT_SESSION_KEY);
// V-VALUEFLASH3 (4th recurrence — real root cause): the race below only hides
// the flash when costAffectingLoadsReady actually wins (or ties) against
// bootTimeout. On a cold-started serverless API (very common right after a
// period of inactivity — exactly when a returning player hits refresh) the
// fetches routinely take longer than the fixed 1500ms cap, so bootTimeout
// wins instead: the page paints from whatever local D.weapons/D.factions/
// catalogOverrideMap looked like BEFORE the corrections applied, and none of
// loadWeaponOverrides/loadCatalogOverrides/loadOfficialWarbands ever
// triggers a render on their own once they land late — unlike
// bootstrapAccountSession, which re-renders itself via applyRemoteData→
// scheduleRemoteRerender. So the number only ever "self-corrects" by
// accident, whenever some OTHER late loader (loadRaceTags/loadRuleNavGroups/
// loadDomainOverrides, a few lines below) happens to trigger its own render
// afterwards — explaining why it's intermittent, and why it kept coming
// back despite the timeout already being there. No data is stacking
// anywhere; total()/fighterValue() have always read live off D.weapons/
// D.factions — this just guarantees a render happens once those are
// actually correct, regardless of which side of the race won.
const bootTimeout=new Promise(resolve=>setTimeout(resolve,1500));
const costAffectingLoadsReady=Promise.all([loadWeaponOverrides().then(()=>loadCatalogOverrides()),loadOfficialWarbands()]);
costAffectingLoadsReady.then(()=>renderCurrentRoute());
if(hasStoredAccountSession){
  Promise.race([Promise.all([bootstrapAccountSession(),costAffectingLoadsReady]),bootTimeout]).finally(()=>{renderCurrentRoute();showPasswordReset();});
}else{
  Promise.race([costAffectingLoadsReady,bootTimeout]).finally(()=>{renderCurrentRoute();showPasswordReset();bootstrapAccountSession();});
}
loadRaceTags().then(()=>renderCurrentRoute());loadFactionCategories().then(()=>renderCurrentRoute());loadRuleNavGroups().then(()=>renderCurrentRoute());loadDomainOverrides().then(()=>renderCurrentRoute());loadSpellWeaponProfileOverrides();
loadScenarios().then(()=>renderCurrentRoute());loadDeploymentMaps().then(()=>renderCurrentRoute());
